window.__ARXIV_DATA__ = {"papers":[{"id":"2611.24941v1","title":"UltraTex: Aligning Physical Knowledge for High-Fidelity PBR Texture Generation","abstract":"Generating physically based rendering (PBR) texture maps for a 3D mesh from a single reference image is highly ambiguous, as the observed appearance entangles material identity, surface reflectance, and illumination. While current generative methods produce realistic albedo maps, they still struggle to infer accurate metallic and roughness attributes for relighting. We present UltraTex, a cascaded multi-view framework that moves beyond appearance matching by integrating physical knowledge into multi-view diffusion-based PBR generation. UltraTex first jointly predicts albedo and world-space shading normals to generate more detailed albedo maps, and then predicts metallic-roughness (MR) maps conditioned on the generated albedo, reference image, and material semantic priors. To inject material semantics, a lightweight adapter transforms hidden-layer features of a vision-language model (VLM) into intrinsic material representation tokens, providing part-level knowledge anchors for MR estimation. To model material-light interaction, photometric representation alignment guides intermediate diffusion features toward ground-truth material renderings under controlled lighting. This makes metallic and roughness variations observable through highlight intensity, specular sharpness, and local reflectance contrast, providing stronger guidance for fine-grained material prediction without explicit lighting supervision. Extensive experiments show that UltraTex generates high-quality textures and outperforms existing open-source and commercial methods in visual fidelity, material accuracy, and physical plausibility.","authors":["Jingzhi Bao","Xiaohe Ma","Hong Li","Yuanming Hu","Xiaoguang Han"],"published":"2026-11-18T18:59:57Z","updated":"2026-11-18T18:59:57Z","abstract_url":"https://arxiv.org/abs/2611.24941v1","html_url":"https://arxiv.org/html/2611.24941v1","pdf_url":"https://arxiv.org/pdf/2611.24941v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"html","source_text_chars":73645,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, diffusion 相关；摘要显示其主要贡献为：Generating physically based rendering (PBR) texture maps for a 3D mesh from a single reference image is highly ambiguous, as the observed appearance entangles material identity, surface reflectance, and illumination. While current generative methods produce r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24940v1","title":"$Z$-sight: Unifying Vision-Language-Action and Latent World Modeling","abstract":"We introduce $Z$-sight, a unified robot foundation model that couples vision-language-action (VLA) and generative latent world modeling. Video-based world action models (WAMs) show the value of joint future-and-action generation for control, yet inherit the heavy cost of video generators. Recent latent-space policies avoid pixel generation, yet typically align intermediate features or rely on frozen target encoders, decoupling future prediction from the VLM's native feature space. $Z$-sight instead predicts the future directly in the visual token space in which its VLM perceives the present. Coupling a foresight expert and a continuous action expert with the VLM in a mixture-of-transformers, $Z$-sight jointly denoises future spatial tokens and actions at inference without pixel reconstruction or external encoders. Trained on human video and robot trajectories, $Z$-sight achieves 81.9% success on SIMPLE (+9.6 points over the strongest baseline) and 73.3% across six Unitree G1 tasks (+20.0 points) at 110 ms per chunk, while remaining competitive on tabletop benchmarks.","authors":["Junjie Ye","Yiqi Zhao","Muchen Xu","Celina Shiyu Wang","Hao Dong","Ruohai Ge","Rong Xue","Benjamin J Kolligs","Aditya Dutt","Sasanka Nagavalli","Nassim A. Samad","Gaurav S. Sukhatme","Jyotirmoy V. Deshmukh","Yue Wang","Yuliang Guo"],"published":"2026-11-18T18:59:38Z","updated":"2026-11-18T18:59:38Z","abstract_url":"https://arxiv.org/abs/2611.24940v1","html_url":"https://arxiv.org/html/2611.24940v1","pdf_url":"https://arxiv.org/pdf/2611.24940v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":86804,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We introduce $Z$-sight, a unified robot foundation model that couples vision-language-action (VLA) and generative latent world modeling. Video-based world action models (WAMs) show the value of joint future-and-action generation for control, yet inherit the h...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24915v1","title":"PrismRestore: A Compact Restoration Toolbox for Agentic Image Restoration","abstract":"Agentic image restoration composes operations to handle mixed degradations, yet its toolbox often requires storing multiple restoration networks. We propose PrismRestore, which constructs a compact bank of callable restoration actions from a single frozen all-in-one model. Our approach builds on task-dependent yet overlapping channel responses in the shared model. An offline task-prior search uses activation and gradient statistics to group channels with similar response profiles, then searches task-specific modulation coefficients over non-representative channels while leaving representative channels unmodulated. The resulting prior bank enables explicit action selection and composition without additional restoration backbones or task-specific adapter modules. A state-conditioned policy learns to compose these actions using Group Relative Policy Optimization. Its objective separately normalizes fidelity and perceptual feedback within groups of trajectories sampled for the same input, and combines terminal evaluation with return-to-go derived from stepwise quality changes. Experiments on synthetic composite-degradation and real-world multi-task benchmarks show improvements over the evaluated all-in-one baselines and restoration quality competitive with multi-model agents. PrismRestore achieves these results with a single restoration backbone and faster inference than the evaluated agentic baselines.","authors":["Zhaocheng Yu","Kui Jiang","Jing Cao","Yiang Chen","Xiaocheng Feng","Junjun Jiang","Xianming Liu"],"published":"2026-11-18T18:48:01Z","updated":"2026-11-18T18:48:01Z","abstract_url":"https://arxiv.org/abs/2611.24915v1","html_url":"https://arxiv.org/html/2611.24915v1","pdf_url":"https://arxiv.org/pdf/2611.24915v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":50008,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic image restoration composes operations to handle mixed degradations, yet its toolbox often requires storing multiple restoration networks. We propose PrismRestore, which constructs a compact bank of callable restoration actions from a single frozen all...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24864v1","title":"NereidVLA: Learning to Understand and Navigate the Underwater World","abstract":"Underwater navigation requires translating visual spatial cues into motion, yet marine vision-language datasets rarely include paired robot trajectories. We present NereidVLA, a vision-language-action model that transfers marine spatial knowledge to language-conditioned 3D navigation. We first train Sea2Know on approximately two million marine examples to learn target grounding, spatial relations, and scene structure without paired robot-motion supervision. We then adapt it using expert trajectories executed under simulated underwater vehicle dynamics. Given RGB histories and a language instruction, NereidVLA predicts discrete motion tokens that decode into local 3D trajectories for closed-loop tracking. Evaluation combines an independent six-dimensional underwater navigation understanding benchmark with offline prediction and closed-loop navigation. Under matched navigation training and execution settings, marine spatial pretraining increases simulation success from 72.4% to 84.4%. Without fine-tuning on the real test environment, NereidVLA achieves 78.75% success in laboratory-pool robot trials, compared with 47.50% for InternVLA-N1. These results show that marine spatial supervision can support downstream motion learning and physical underwater navigation.","authors":["Chenjie Zhao","Zhiliang Zhu","Quan Chen","Yuquan Xue","Xingxue Shi","Puyue Wang","Zhiqiang Zhao","Kangye Zheng","Boyang Xu","Mingwei Lin","Dejun Li"],"published":"2026-11-18T18:19:00Z","updated":"2026-11-18T18:19:00Z","abstract_url":"https://arxiv.org/abs/2611.24864v1","html_url":"https://arxiv.org/html/2611.24864v1","pdf_url":"https://arxiv.org/pdf/2611.24864v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":58634,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Underwater navigation requires translating visual spatial cues into motion, yet marine vision-language datasets rarely include paired robot trajectories. We present NereidVLA, a vision-language-action model that transfers marine spatial knowledge to language-...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24862v1","title":"Gaspard: Expressive unified speech and gesture synthesis with continuous autoregressive flow-matching and decoupled classifier-free guidance","abstract":"Human communication involves highly coordinated multimodal signals such as speech and co-speech gestures. Existing approaches for generating both modalities commonly follow a cascaded pipeline, where speech is generated first and subsequently used to drive gesture generation; speech generation is therefore independent of gestures. We introduce Gaspard, a unified speech--gesture generation model based on continuous autoregressive generation with next-step flow-matching predictions, and trained on Seamless Interaction, a large-scale multimodal dataset. The heterogeneous temporal properties of speech and gesture motivate modality-specific prediction heads and decoupled classifier-free guidance over the two generation streams. This guidance rebalances the influence of speech and gesture at inference time, improving expressivity while mitigating dynamics collapse in continuous autoregressive gesture generation. Objective and perceptual evaluations show that Gaspard is a strong gesture generation model against unimodal baselines and that it produces highly synchronous speech and gestures compared to a matched cascaded system.","authors":["Téo Guichoux","Théodor Lemerle","Catherine Pelachaud","Nicolas Obin"],"published":"2026-11-18T18:18:44Z","updated":"2026-11-18T18:18:44Z","abstract_url":"https://arxiv.org/abs/2611.24862v1","html_url":"https://arxiv.org/html/2611.24862v1","pdf_url":"https://arxiv.org/pdf/2611.24862v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":87957,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Human communication involves highly coordinated multimodal signals such as speech and co-speech gestures. Existing approaches for generating both modalities commonly follow a cascaded pipeline, where speech is generated first and subsequently used to drive ge...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24806v1","title":"ReCoCo: From Patches to Compositions for Visual Representation Learning","abstract":"Self-supervised learning has produced powerful visual representations, yet learning strong dense features remains challenging. While consistency between augmented views provides strong image-level supervision, extending this principle to local visual content is less straightforward. Existing approaches often match individual patches across views or identify coherent regions, introducing uncertainties in correspondence estimation and assumptions about how visual content should be grouped. We introduce ReCoCo (Regional Composition Consistency), a principled approach that extends cross-view consistency to the regional level without requiring such correspondences or semantic grouping. ReCoCo represents the content shared between augmented views through compositions of their patch-level predictions over learned visual prototypes. By aligning these compositions, the model learns from regions containing multiple visual concepts without requiring them to be separated beforehand. ReCoCo integrates naturally with teacher-student self-distillation and introduces no additional learned parameters. Extensive experiments demonstrate substantial improvements in frozen-feature segmentation, clustering, and regional retrieval while maintaining competitive image-level recognition, alleviating the trade-off between dense and global representation quality.","authors":["Juan Gutiérrez","Saman Zadtootaghaj","José Luis Blanco-Murillo","Sara Atito"],"published":"2026-11-18T17:45:04Z","updated":"2026-11-18T17:45:04Z","abstract_url":"https://arxiv.org/abs/2611.24806v1","html_url":"https://arxiv.org/html/2611.24806v1","pdf_url":"https://arxiv.org/pdf/2611.24806v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"html","source_text_chars":53330,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, representation 相关；摘要显示其主要贡献为：Self-supervised learning has produced powerful visual representations, yet learning strong dense features remains challenging. While consistency between augmented views provides strong image-level supervision, extending this principle to local visual content...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24805v1","title":"Edge-Efficient Joint RAW Image Compression and Restoration for Smart Wearable Devices","abstract":"Smart wearable devices, such as augmented reality glasses, increasingly rely on cameras to understand and interact with their surroundings. However, their compact sensors often capture noisy RAW images, while limited compute and power make high-quality on-device restoration difficult. This creates an emerging need to reduce both local computation and transmission cost without sacrificing image quality. Two common solutions are to offload restoration or to compress the raw data before transmission. The first makes RAW transmission costly; the second reduces the payload but can spend bitrate preserving sensor noise. We address this fundamental mismatch with an asymmetric framework for joint RAW compression and restoration that directly optimizes the transmitted representation for clean image reconstruction. A lightweight on-device encoder compresses noisy RAW measurements into a bitstream, while a higher-capacity backend decoder jointly denoises and demosaics the encoded representation. We use knowledge distillation to train a smaller encoder for tighter compute budgets. Experiments on real and synthetic data show improved rate-restoration performance over strong cascaded compression-restoration pipelines and learned compression baselines. On SIDD, our method improves PSNR by more than 1.5 dB over cascaded baselines at approximately 0.25 bits per pixel. We further validate the method on real 12 MP RAW images captured with commercial smart glasses and measure sender-side latency on both smartphone and smart-glasses hardware. The distilled encoder achieves a 27.6$\\times$ NPU inference speedup over on-device NAFNet for 256$\\times$256 output patches. The code is available at https://github.com/coolsyn2000/CRAW","authors":["Yunong Sun","Sicheng Chen","Fei Xia"],"published":"2026-11-18T17:44:34Z","updated":"2026-11-18T17:44:34Z","abstract_url":"https://arxiv.org/abs/2611.24805v1","html_url":"https://arxiv.org/html/2611.24805v1","pdf_url":"https://arxiv.org/pdf/2611.24805v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":47821,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Smart wearable devices, such as augmented reality glasses, increasingly rely on cameras to understand and interact with their surroundings. However, their compact sensors often capture noisy RAW images, while limited compute and power make high-quality on-dev...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24795v1","title":"Ultimate3D: Teaching Multimodal LLMs 3D Camera-Object Relations by Large-Scale Visual Instruction Data","abstract":"Multimodal Large Language Models (MLLMs) struggle with accurately capturing camera-object relations, especially for object orientation, camera viewpoint, and camera shots. This stems from the fact that existing MLLMs are trained on images with limited diverse camera-object relations and corresponding textual descriptions. To address this, we propose a synthetic generation pipeline to create large-scale 3D visual instruction datasets. Our framework takes 3D assets as input and uses rendering and diffusion-based image generation models to create photorealistic images preserving precise camera-object relations. Additionally, large language models (LLMs) are used to generate text prompts for guiding visual instruction tuning and controlling image generation. We create Ultimate3D, a large-scale 3D-grounded 2D visual instruction dataset. Ultimate3D consists of 240K VQAs with precise camera-object annotations, and corresponding benchmark. MLLMs fine-tuned on our proposed dataset outperform commercial models by a large margin, achieving an average accuracy improvement of 29.7% on camera-object relation recognition tasks. Our code, dataset, and benchmark will contribute to broad MLLM applications.","authors":["Liu He","Yizhi Song","Ruiqi Xu","Baris Sarper Tezcan","Xiao Zeng","Albert Y. C. Chen","Lu Xia","Shashwat Verma","Sankalp Dayal","Min Sun","Cheng-Hao Kuo","Daniel Aliaga"],"published":"2026-11-18T17:39:54Z","updated":"2026-11-18T17:39:54Z","abstract_url":"https://arxiv.org/abs/2611.24795v1","html_url":"https://arxiv.org/html/2611.24795v1","pdf_url":"https://arxiv.org/pdf/2611.24795v1.pdf","matched_keywords":["3d","multimodal","diffusion"],"source_used":"html","source_text_chars":107759,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, multimodal, diffusion 相关；摘要显示其主要贡献为：Multimodal Large Language Models (MLLMs) struggle with accurately capturing camera-object relations, especially for object orientation, camera viewpoint, and camera shots. This stems from the fact that existing MLLMs are trained on images with limited diverse...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24793v1","title":"The Elephant in the Question: Unified Models Picture the Concepts Behind Their Answers","abstract":"Visualizing intermediate representations could help us inspect the reasoning steps underlying a model output. Unified multimodal models offer this opportunity by combining understanding and generation in one architecture. Their image generators can access representations formed while processing text. We introduce the V-lens, which uses this connection to visualize a chosen token's hidden state without training a decoder. Across four diffusion-based and two purely autoregressive unified models, the resulting images reveal key intermediate concepts that connect a question to its answer even when the concepts are never named explicitly. Controlled tests show how this content changes with context, token position, and depth. We then introduce lens tuning, which supervises selected hidden states with pictures through the V-lens. Across BAGEL, SenseNova-U1, and HunyuanImage-3.0, the rate of correct visualizations of pronoun referents rises from 2-11% to 86-94%. Surprisingly, such visual supervision also improves text answers without supervising the answer tokens directly. Code is available at https://github.com/multimodal-ai-lab/V-lens.","authors":["Tobias Braun","Marcus Rohrbach","Lorenzo Cavallaro"],"published":"2026-11-18T17:38:46Z","updated":"2026-11-18T17:38:46Z","abstract_url":"https://arxiv.org/abs/2611.24793v1","html_url":"https://arxiv.org/html/2611.24793v1","pdf_url":"https://arxiv.org/pdf/2611.24793v1.pdf","matched_keywords":["representation","multimodal","diffusion"],"source_used":"html","source_text_chars":120325,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal, diffusion 相关；摘要显示其主要贡献为：Visualizing intermediate representations could help us inspect the reasoning steps underlying a model output. Unified multimodal models offer this opportunity by combining understanding and generation in one architecture. Their image generators can access rep...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24792v1","title":"Training-free motion statistics match self-supervised behavior encoders","abstract":"Self-supervised encoders for animal behavior are often trained on, or fed, hand-built movement features. We ask whether they beat those ingredients when compared fairly. A training-free representation, made of generic per-frame measurements summarized over fixed time windows and reduced with PCA, is compared with retrained and released encoders (BAMS, hBehaveMAE) under a preregistered protocol: frozen representations of equal size and one shared classifier. On CalMS21 it reaches 85.8 macro F1 against 82.4 for the best encoder, ties with four labelled videos, and leads when the annotator changes or new behaviors must be learned from a few videos; the reading holds for encoders retrained with three seeds. On the MABe22 mouse triplets it scores 83.7 against 80.3 for the released hBehaveMAE (gap +3.4, 95% interval +2.1 to +4.7). On a second species, the MABe22 fly groups, the same recipe scores 51.6 mean F1 over 50 tasks against 48.2 for BAMS, the best published method. On Shot7M2, the synthetic basketball benchmark built by hBehaveMAE's authors, it scores 68.8 against 64.7 for hBehaveMAE, the best method in that paper, though hBehaveMAE remains better on the shortest movements. Short time windows carry most of the result. Raw keypoints in each body's own frame, summarized over the same windows, already match or beat the encoders on both mouse datasets and on Shot7M2; on the fly groups they fall short, and the measurements add 5.3 points. On these benchmarks, current behavior encoders have yet to beat the hand-built features they learn from, and such baselines should be reported alongside them.","authors":["Ziwen Chen"],"published":"2026-11-18T17:38:27Z","updated":"2026-11-18T17:38:27Z","abstract_url":"https://arxiv.org/abs/2611.24792v1","html_url":"https://arxiv.org/html/2611.24792v1","pdf_url":"https://arxiv.org/pdf/2611.24792v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":41535,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Self-supervised encoders for animal behavior are often trained on, or fed, hand-built movement features. We ask whether they beat those ingredients when compared fairly. A training-free representation, made of generic per-frame measurements summarized over fi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24776v1","title":"4D-TEMPO: Differentiable 4D-STEM ptychography via fast Physics Optimizers","abstract":"Electron ptychography recovers atomic structure from 4D-STEM data: diffraction patterns at multiple positions of a scanned probe. Current codes reconstruct an image and read atoms off it, or fit atoms under an $L_1$ loss; neither gives per-atom uncertainty. We propose 4D-TEMPO, a differentiable physical renderer that fits the atoms, the microscope, and the detector directly to the recorded electron counts under a Poisson likelihood. The output is a list of atoms, each a Gaussian primitive with a 3D position, a thermal width, and a model-conditional error bar from the Fisher information. The Fisher information also conditions the solver, gives the dose (electrons per Å$^2$) each parameter needs, and separates calibration from imaging. On a simulated WSe$_2$ bilayer, starting from the published reconstruction, fitted atoms cut in-plane error by a third (3.2 vs. 4.8 pm) and depth error by 40-61% against its 3D peaks. Depth comes from multiple scattering into the dark field, the faint counts outside the direct beam. The two layers, $10\\times$ closer than the depth of field, separate; per-atom depth then follows the layer geometry. When the model is well specified, the bars are calibrated (69% of position coordinates within $1σ$). On experimental WSe$_2$, fitted atoms predict held-out patterns better than the three published codes we test. With free probe modes where atoms are incomplete, the same likelihood predicts best on all three held-out benchmarks, matches every WSe$_2$ baseline in 5 min against up to 20.5 h, and passes torchslice at its released setting 180$\\times$ sooner on PrScO$_3$. Per-atom error bars, planned doses, and fast reconstruction point to low-dose, real-time 3D imaging of beam-sensitive and dynamic materials.","authors":["Ramani Duraiswami","Yichao Zhang"],"published":"2026-11-18T17:23:50Z","updated":"2026-11-18T17:23:50Z","abstract_url":"https://arxiv.org/abs/2611.24776v1","html_url":"https://arxiv.org/html/2611.24776v1","pdf_url":"https://arxiv.org/pdf/2611.24776v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":192981,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Electron ptychography recovers atomic structure from 4D-STEM data: diffraction patterns at multiple positions of a scanned probe. Current codes reconstruct an image and read atoms off it, or fit atoms under an $L_1$ loss; neither gives per-atom uncertainty. W...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24762v1","title":"A$^3$Bench: Compositional Reasoning over Aggressive Interactions in Videos","abstract":"Recent Multimodal Large Language Models (MLLMs) have achieved strong performance on general video understanding benchmarks, yet their ability to reason about participant roles in aggressive interactions remains largely unexplored. Existing violence and crime datasets primarily evaluate whether aggression occurs, without testing whether models can identify who performed the action, who received it, and how participants are related within the scene. To address this gap, we introduce A$^3$Bench, a benchmark to study aggressive action and association in videos. The benchmark evaluates whether models can jointly recognize aggressive actions, distinguish aggressors from victims and bystanders, and correctly bind actions to participants under challenging distractor settings. We benchmark 17 multimodal models and find that they struggle substantially on fine-grained aggressive-scene understanding. Performance degrades consistently as reasoning complexity increases, with models frequently confusing aggressors with victims or bystanders, revealing a systematic failure in role-action association rather than coarse aggression recognition alone. We further observe that increasing model scale or generic reasoning models experience limited improvement. Finally, we explore a simple role-graph prompting strategy that encourages structured reasoning over participant interactions, leading to improvements in compositional reasoning. Our findings highlight that reliable aggressive-scene understanding remains a major challenge for current MLLMs and motivate future research on role-aware video reasoning beyond coarse violence detection. Code and dataset: https://github.com/austincbaker/A3Bench.","authors":["Austin C Baker","Raiyaan Abdullah","Daniel Zeev Yoffe","Shruti Vyas","Yogesh S Rawat"],"published":"2026-11-18T17:15:58Z","updated":"2026-11-18T17:15:58Z","abstract_url":"https://arxiv.org/abs/2611.24762v1","html_url":"https://arxiv.org/html/2611.24762v1","pdf_url":"https://arxiv.org/pdf/2611.24762v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":110338,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Recent Multimodal Large Language Models (MLLMs) have achieved strong performance on general video understanding benchmarks, yet their ability to reason about participant roles in aggressive interactions remains largely unexplored. Existing violence and crime...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24731v1","title":"HandWorldBench: A Unified Benchmark for Hand-Centric World Models","abstract":"Recent advances in world models are opening new possibilities for fine-grained embodied tasks, with hand-object interaction offering a particularly demanding setting. Modeling these interactions involves capturing how hand actions change objects and how the resulting states persist over time. Yet systematic evaluation tailored to these hand-centric capabilities remains underdeveloped. To address this gap, we introduce HandWorldBench, a unified benchmark that systematically evaluates hand-centric world models across human hands, simulated dexterous hands, and real dexterous hands along six dimensions: visual quality, hand fidelity, appearance consistency, instruction following, physical consistency, and temporal coherence. To construct the benchmark, we develop a data curation pipeline that extracts hand-object interaction clips and screens them for quality, yielding 20,500 high-quality egocentric clips from over 600 hours of footage. We then manually select 500 clips covering seven task families for evaluation. Benchmarking eleven models under a unified protocol reveals that stronger hand-pose control does not consistently translate into coherent object-state evolution and persistence or robust cross-embodiment performance, with several specialized hand-control models underperforming general-purpose text/image-to-video generators on dexterous-hand tasks.","authors":["Zhaolu Wang","Jiacheng Xu","Lihong Wang","Shuqing Wang","Jianjie Fang","Ziyou Wang","Xvyuan Liu","Rongze Tang","Yiding Ma","Xin Zhang","Jiawei Chen","Wei Wu","Chen Gao","Yong Li","Zhibo Chen"],"published":"2026-11-18T16:47:46Z","updated":"2026-11-18T16:47:46Z","abstract_url":"https://arxiv.org/abs/2611.24731v1","html_url":"https://arxiv.org/html/2611.24731v1","pdf_url":"https://arxiv.org/pdf/2611.24731v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":43377,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advances in world models are opening new possibilities for fine-grained embodied tasks, with hand-object interaction offering a particularly demanding setting. Modeling these interactions involves capturing how hand actions change objects and how the r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24723v1","title":"Multi-Band Galaxy Novel-View Synthesis with Radiative Gaussian Fields","abstract":"We propose a novel view synthesis tool for galaxies based on Gaussian Splatting (GS). Unlike RGB data, where GS has achieved success, galaxy observations consist of multi-band signals from a massive number of bodies, contain complex patterns of cross-band interactions, and capture light propagation in highly heterogeneous media. As a result, the underlying physical process poses great challenges in model representation and optimization, which have not been investigated in existing research. To this end, we propose a physically inspired Gaussian Splatting method, GalaxyGS, which is equipped with physically meaningful components that capture both the energy emission mechanism of different astronomical bodies and the light propagation between them. In the absence of directly comparable baseline methods, we adopt a wide range of possible alternative approaches. Comparisons conclusively demonstrate that GalaxyGS is better in accuracy and physical fidelity across datasets and metrics.","authors":["Yuzhe Wu","Jialin Zhu","Doğa Yılmaz","Daisuke Kawata","He Wang"],"published":"2026-11-18T16:41:49Z","updated":"2026-11-18T16:41:49Z","abstract_url":"https://arxiv.org/abs/2611.24723v1","html_url":"https://arxiv.org/html/2611.24723v1","pdf_url":"https://arxiv.org/pdf/2611.24723v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":54517,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：We propose a novel view synthesis tool for galaxies based on Gaussian Splatting (GS). Unlike RGB data, where GS has achieved success, galaxy observations consist of multi-band signals from a massive number of bodies, contain complex patterns of cross-band int...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24719v1","title":"DRIFT: Detachable Reasoning for Runtime-Flexible and Efficient End-to-End Driving","abstract":"The integration of vision-language models (VLMs) into end-to-end (E2E) autonomous driving has demonstrated strong potential by providing scene description and reasoning capabilities. However, VLMs are computationally expensive, and switching language reasoning on and off at runtime without hurting closed-loop performance has not been demonstrated, which hinders practical adoption. To address these issues, we propose DRIFT, an E2E autonomous driving framework that integrates a lightweight language model (LM) for visual question answering and action commentary. By efficiently projecting intermediate driving representations into the language embedding space, we demonstrate that a compact LM (<150M parameters) can achieve strong scene description and action commentary. Furthermore, we introduce a runtime-flexible planning module that is trained on surrogate reasoning features distilled from the LM and can be conditioned on either the LM or the surrogate reasoning features at inference. This design enables bypassing the LM entirely when required by deployment constraints, without sacrificing driving performance. With only 255M parameters, DRIFT reaches up to a Driving Score (DS) of 97.03 and a Success Rate of 89.39% (mean over three runs) on Bench2Drive by interleaving its LM and surrogate reasoning at a chosen reasoning rate. This is on par with the strongest non-language models while being far more compact than existing VLM-based models. DRIFT further achieves competitive results on the real-world NAVSIM and AlpaSim benchmarks at significantly lower computational cost than existing VLM-based approaches. Project page: https://drift-e2e.github.io/","authors":["Emad Aghajanzadeh","Bethany Anne Wong","Leonhard Kunze","Moritz Thoma","Maximilian Forstenhäusler","Nael Fasfous","Manoj Rohit Vemparala","Pierpaolo Mori","Christos Anagnostopoulos","Daniel Mueller-Gritschneder","Ulf Schlichtmann"],"published":"2026-11-18T16:40:13Z","updated":"2026-11-18T16:40:13Z","abstract_url":"https://arxiv.org/abs/2611.24719v1","html_url":"https://arxiv.org/html/2611.24719v1","pdf_url":"https://arxiv.org/pdf/2611.24719v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":57052,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：The integration of vision-language models (VLMs) into end-to-end (E2E) autonomous driving has demonstrated strong potential by providing scene description and reasoning capabilities. However, VLMs are computationally expensive, and switching language reasonin...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24706v1","title":"Can Omni-modal LLMs Understand Spoken Intentions?","abstract":"Omni-modal large language models (omni-modal LLMs) can respond to spoken requests directly through voice and video calls. Such requests rely on the scene shared by the user and the assistant, so the same utterance may call for different help or for no response. Most audio-visual benchmarks provide questions as separate text input, and interactive benchmarks mostly score a response as a whole. It thus remains unclear whether a model recognizes when the user is asking for help, and whether its reply meets the user's need once the request is recognized. We propose O-IN-Bench to evaluate how well omni-modal LLMs understand spoken intentions. A model watches a complete video with native speech and outputs one text response, or [SILENCE] when no response is needed. O-IN-Bench contains 1,000 Chinese and English samples in five categories and 16 subcategories. Contrastive pairs combine the same request with different scene conditions to test whether the response changes with the context. A sample-specific rubric judges language, intent, and content separately, and O-IN-Engine verifies each rubric against the video. Across 30 omni-modal model configurations, the best overall score is 59.6, achieved by Gemini3.7-Flash. Gemini3.7-Flash passes 74.4% of the intent judgments but only 42.6% of the content judgments. When the speech is a conversation between peers rather than a request to the assistant, even strong models often keep responding. When a reply must satisfy several people, the best score is only 25.9. These results indicate that recognizing a request and meeting its requirements are separate abilities, and O-IN-Bench measures each of them.","authors":["Zijie Xin","Tianyi Wang","Daoze Zhang","Jie Yang","Changli Tang","Qijie Wei","Fengyun Rao","Xirong Li"],"published":"2026-11-18T16:31:52Z","updated":"2026-11-18T16:31:52Z","abstract_url":"https://arxiv.org/abs/2611.24706v1","html_url":"https://arxiv.org/html/2611.24706v1","pdf_url":"https://arxiv.org/pdf/2611.24706v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":44873,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Omni-modal large language models (omni-modal LLMs) can respond to spoken requests directly through voice and video calls. Such requests rely on the scene shared by the user and the assistant, so the same utterance may call for different help or for no respons...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24696v1","title":"Improving Zero-shot 3D Semantic Mapping in Offroad with Geometric Priors","abstract":"Semantic 3D mapping is a powerful representation that enables platform agnostic mobile robot navigation in challenging offroad conditions. Current vision foundation models can accurately predict semantics zero-shot on structured scenes but performance is compromised in natural environments. On the other hand, 3D point clouds encode valuable information for discriminating semantics in scenarios where vision foundation models fail. In this work, we propose fitting a sphericity-elevation distribution for each semantic class to act as geometric anchor. Only the points with the most confident vision foundation model predictions are considered when fitting to produce high quality geometric prior distributions. The geometric prior is fused with the vision foundation model prediction to produce the final semantic mapping. The proposed prior improves SAM3 baseline by +6.3 in mIoU and +8.9 in accuracy on the RELLIS-3D dataset, and by +1.7 in mIoU and +2.1 in accuracy on the WildScenes dataset. The source code will be made public upon paper acceptance.","authors":["Eerik Alamikkotervo","Risto Ojala"],"published":"2026-11-18T16:23:05Z","updated":"2026-11-18T16:23:05Z","abstract_url":"https://arxiv.org/abs/2611.24696v1","html_url":"https://arxiv.org/html/2611.24696v1","pdf_url":"https://arxiv.org/pdf/2611.24696v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":38280,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Semantic 3D mapping is a powerful representation that enables platform agnostic mobile robot navigation in challenging offroad conditions. Current vision foundation models can accurately predict semantics zero-shot on structured scenes but performance is comp...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24681v1","title":"DrawScore: Evaluating Generated CAD Models against Engineering Drawings","abstract":"Automatic CAD generation is commonly evaluated with volumetric IoU, Chamfer Distance, and surface F-score, which barely penalize local errors that occupy only a small fraction of a part's volume or surface area, such as a misplaced hole or a slot on the wrong face, even though such errors are critical to manufacturing. We formalize these metrics in a unified integral form and show that the weight of a local error decays as the $(k+q)$-th power of its size, where $k$ is the dimension of the integration domain and $q$ is determined by the penalty function. Guided by this analysis, we propose DrawScore, which projects both models into three orthographic views with visible and hidden lines, as in engineering drawings, and applies a saturating penalty along the projected curves, so that the weight of a local error decays only linearly. Controlled experiments confirm the predicted decay orders, and on outputs of existing CAD generation agents, DrawScore exposes errors in outputs that IoU rates as nearly perfect. DrawScore further improves generation as a reinforcement learning reward and, for CAD generation from engineering drawings, serves as a test-time verifier without 3D ground truth or an additional reward model. Our code is available at https://github.com/UESTC-Simon/DrawScore.","authors":["Haorui Chen","Shiteng Lu","Zhanyu Guo","Zaixi Li","Yunhe Ni","Yaosong Du","Yichen Xiang","Xiande Huang","Rui Huang"],"published":"2026-11-18T16:14:30Z","updated":"2026-11-18T16:14:30Z","abstract_url":"https://arxiv.org/abs/2611.24681v1","html_url":"https://arxiv.org/html/2611.24681v1","pdf_url":"https://arxiv.org/pdf/2611.24681v1.pdf","matched_keywords":["3d","agent"],"source_used":"html","source_text_chars":47609,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, agent 相关；摘要显示其主要贡献为：Automatic CAD generation is commonly evaluated with volumetric IoU, Chamfer Distance, and surface F-score, which barely penalize local errors that occupy only a small fraction of a part's volume or surface area, such as a misplaced hole or a slot on the wrong...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24651v1","title":"Piccolo: Co-Evolving Decision Models and Data through Recursive Self-Improvement","abstract":"We present Piccolo, a family of multimodal decision models (0.8B to 27B) that coevolves model capabilities and training data via Agentic Data Engineering and recursive self-improvement (RSI). The models predict probabilities over candidate answers for general-purpose text and visual judgments, agent harnesses, data workflows, and interactive games. Piccolo-27B tops the Decision Index Vision Full leaderboard with a score of 75.59, while Piccolo-9B and Piccolo-4B achieve 68.35 and 67.46, respectively. All three rank first on the Private benchmark in their respective model-size categories. Research agents analyze model behavior, construct training data, conduct experiments, and use the results to refine subsequent proposals. Semantic slices and a shared research memory connect these actions across the model family's development. With training recipes comprising hundreds of thousands of examples, data selection and feedback-driven refinement are central to the self-improvement process. Our large-scale RSI exploration yields three counter-intuitive insights for decision-model development: (1) Backbone-recipe co-adaptation outweighs raw model recency: earlier backbones can surpass newer generations on visual tasks under identical recipes; (2) Targeted data curation enables 4B-9B models to rival 27B baselines on specialized workflows; and (3) Continuous loss reduction can decouple from and even degrade discrete decision accuracy. Together with the released weights and tools from the Data-Juicer and AgentScope ecosystems, Piccolo provides an actionable blueprint for building frontier decision models and scaling data-driven RSI.","authors":["Zhenqing Ling","Qirui Jiao","Daoyuan Chen","Cheng Chen","Xinji Mai","Haowen Gao","Zhuo Zhang","Xuchen Pan","Mengsu Ding","Jiaji Deng","Yuexiang Xie","Xiaoming Qin","Weirui Kuang","Zhaoyang Liu","Yaliang Li","Bolin Ding","Jingren Zhou"],"published":"2026-11-18T15:53:39Z","updated":"2026-11-18T15:53:39Z","abstract_url":"https://arxiv.org/abs/2611.24651v1","html_url":"https://arxiv.org/html/2611.24651v1","pdf_url":"https://arxiv.org/pdf/2611.24651v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":76234,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：We present Piccolo, a family of multimodal decision models (0.8B to 27B) that coevolves model capabilities and training data via Agentic Data Engineering and recursive self-improvement (RSI). The models predict probabilities over candidate answers for general...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24643v1","title":"AggCLIP: Aggregating CLIP for Zero-Shot Multimodal Anomaly Detection","abstract":"Zero-Shot Multimodal Anomaly Detection (ZSMAD) aims to identify both appearance and geometric defects in novel categories without relying on target-specific training data, making it especially valuable in real-world scenarios constrained by data scarcity, privacy concerns, or high annotation costs. While recent approaches successfully adapt vision-language models like CLIP to achieve this open-vocabulary generalization, they still face significant challenges: (i) severe geometric information loss during 3D-to-2D point cloud rendering; (ii) spatially noisy 2D feature maps produced by raw CLIP patch embeddings, compounded by shallow late-stage modality fusion; and (iii) severe cross-modal semantic misalignment due to decoupled processing streams. To address these limitations, we propose AggCLIP, a novel framework that adapts frozen CLIP representations for ZSMAD by explicitly incorporating local geometric structure and visual spatial context. Specifically, to accurately localize fine-grained defects, we design a Geometry-Aware Spatial Aggregation (GSA) module that refines back-projected 3D point features via density-adaptive neighborhood weighting, alongside a Context-Aware Spatial Aggregation (CSA) module that smooths multi-scale 2D patch embeddings using a lightweight trainable adapter. Furthermore, to prevent semantic drift between modalities, we introduce a Dual-Stream Prompt Contrastive (DSPC) loss, which aligns the abstract concepts of normality and abnormality across the point cloud and RGB streams. Extensive experiments demonstrate that the proposed AggCLIP framework achieves state-of-the-art performance on the MVTec 3D-AD and Eyecandies benchmarks under both one-vs-rest and cross-dataset zero-shot settings, notably surpassing the strongest competitive methods by up to 2.9% in pixel-level AUPRO.","authors":["Zhi Li","Hanyu Wang","Fei Shen","Zhengtao Zhang"],"published":"2026-11-18T15:49:05Z","updated":"2026-11-18T15:49:05Z","abstract_url":"https://arxiv.org/abs/2611.24643v1","html_url":"https://arxiv.org/html/2611.24643v1","pdf_url":"https://arxiv.org/pdf/2611.24643v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"html","source_text_chars":62762,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal 相关；摘要显示其主要贡献为：Zero-Shot Multimodal Anomaly Detection (ZSMAD) aims to identify both appearance and geometric defects in novel categories without relying on target-specific training data, making it especially valuable in real-world scenarios constrained by data scarcity, pri...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24633v1","title":"H3Remover: Reinforcing Video Object Removal without Paired Data","abstract":"Pretrained video editors possess rich removal and completion priors, yet may retain targets or alter unrelated content. We present H3Remover, which reinforces MiniMax-H3 Base Ref2VA for video object removal without paired object-free training targets. To discourage superficial edits such as recoloring, a target-removal reward favors calibrated depth changes consistent with revealing farther content. To limit unintended scene changes, a background-geometry reward encourages preservation of relative depth ordering. To preserve background appearance without retaining unwanted shadows or reflections, an appearance reward constrains RGB changes in source-derived protected regions while exempting targets and estimated effects. Frozen HPSv3 complements these constraints with perceptual-quality feedback for synthesized content. Evaluation regions remain fixed across candidates, and DiffusionART optimizes LoRA adapters with the backbone frozen. Experiments show substantial reconstruction gains over original H3, with qualitative comparisons demonstrating more effective object removal and better preservation of surrounding scene content.","authors":["Kangjie Chen","Xiangyu Li","Jinhao Deng","Dongbin Zhang","Chaoda Zheng","Shijia Chen","Yuqi Zhang","Choo Sin Wai","Boyi Sun","Puyi Wang","Yu Zhang","Xianming Liu","Boyang Wang"],"published":"2026-11-18T15:45:18Z","updated":"2026-11-18T15:45:18Z","abstract_url":"https://arxiv.org/abs/2611.24633v1","html_url":"https://arxiv.org/html/2611.24633v1","pdf_url":"https://arxiv.org/pdf/2611.24633v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24616v1","title":"EgoJev: Finding Evidence in Egocentric Video by Reading VLM Decisions","abstract":"Questions about long egocentric video often depend on one brief moment, such as the second a hand puts an object down. A vision-language model (VLM) that sees a few evenly spaced frames usually misses it. Training-free methods rank frames with a separate image-text model or ask the VLM to write a time. In a controlled test, the VLM itself locates the moment better when it chooses among labeled frames, and we read this choice from its output distribution. With the same candidates, this choice lands on the evidence more often than image-text scores or a written time span, and it compares all candidates in one decision. Based on this finding, we propose EgoJev, a training-free frame selector for wearable assistants. EgoJev reads where the evidence is from labeled thumbnails and looks again at the windows it points to. It places its few answer frames at the quantiles of the resulting distribution. One frozen VLM selects, answers and returns the evidence time, with no second model. A wearable device can encode its coarse thumbnails while it records. With Qwen3.5-4B and 8 answer frames, EgoJev raises QAEgo4D accuracy from 51.2% with uniform sampling to 62.0%, and it outperforms recent training-free frame selectors on QAEgo4D and MyEgo. A single-level version runs on a Mac and an iPhone.","authors":["Chunggi Lee","Hanspeter Pfister"],"published":"2026-11-18T15:34:10Z","updated":"2026-11-18T15:34:10Z","abstract_url":"https://arxiv.org/abs/2611.24616v1","html_url":"https://arxiv.org/html/2611.24616v1","pdf_url":"https://arxiv.org/pdf/2611.24616v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24579v1","title":"ALIVE: Bring Foundation Features to Life with Events","abstract":"Visual foundation models provide powerful representations for diverse tasks, but their features become stale as visual content changes between image observations. Refreshing them requires new frames and repeated runs of a computationally expensive image encoder. We introduce ALIVE, an event-based method that incrementally updates native foundation model features between image observations. Given an anchor image, ALIVE uses subsequent events to transport and correct existing multi-layer features extracted by a frozen DINOv3 encoder. Its lightweight updater is trained end-to-end using only synthetic data, without downstream task supervision, and transfers directly to real-world event streams without any adaptation. Across three real-world datasets and five task-dataset settings spanning object detection, semantic segmentation, and depth estimation, ALIVE outperforms all evaluated event-based methods in every metric. On DSEC, when the anchor frame is 200,ms old, ALIVE improves over anchor-image predictions by 30.9,mAP in detection, 11.6,mIoU in segmentation, and 15.9% in depth AbsRel. Compared with image re-encoding, ALIVE reduces FLOPs by 82.4% and latency by a factor of 2.5.","authors":["Rong Zou","Haiqing Hao","Davide Scaramuzza"],"published":"2026-11-18T15:10:48Z","updated":"2026-11-18T15:10:48Z","abstract_url":"https://arxiv.org/abs/2611.24579v1","html_url":"https://arxiv.org/html/2611.24579v1","pdf_url":"https://arxiv.org/pdf/2611.24579v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24565v1","title":"Beyond Appearance: Evidence-Guided Programmatic 3D Scene Reconstruction with Agentic Lighting Reasoning","abstract":"Image-to-code methods for 3D scene reconstruction produce executable code that generates editable digital content and supports visual simulation. However, existing methods primarily rely on appearance similarity, which provides limited guidance for distinguishing errors in geometry, materials, and illumination. Light shapes scene appearance through its interactions with geometry and materials, influencing shading, cast shadows, and reflections. We therefore present LightHarness, a VLM-based agentic framework that incorporates explicit lighting reasoning into iterative scene reconstruction. To be specific, we leverage complementary geometric, intrinsic, and illumination cues to jointly refine scene structure and appearance, and propose Lighting Reasoning Memory to maintain light-source hypotheses, which supports evidence, and revision history throughout iterations. Together, they support reasoning about partially visible and unseen sources, with evidence-guided verification directing subsequent revisions. Our framework reconstructs explicit scenes through coherent reasoning about geometry, materials, and illumination without additional training or differentiable rendering. Extensive experiments demonstrate superior image-to-code reconstruction accuracy under challenging shadows and complex illumination, further supporting downstream scene editing, object insertion, and versatile relighting.","authors":["Zeting Luo","Yifan Li","Shuai Yang"],"published":"2026-11-18T15:01:21Z","updated":"2026-11-18T15:01:21Z","abstract_url":"https://arxiv.org/abs/2611.24565v1","html_url":"https://arxiv.org/html/2611.24565v1","pdf_url":"https://arxiv.org/pdf/2611.24565v1.pdf","matched_keywords":["3d","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24558v1","title":"SCR: Detecting Backdoor-Poisoned Samples through Clean-Reference Residuals","abstract":"Deep neural networks are vulnerable to backdoor attacks, in which adversaries manipulate model predictions by injecting poisoned samples into training data. Detecting these samples remains challenging because legitimate semantic variation can obscure poisoning-related signals in learned representations. Consequently, class-level statistics used by existing detectors may flag benign feature deviations while overlooking poisoned samples that blend into the class distribution. In this paper, we propose Semantic Counterfactual Residualization (SCR), which uses a small set of clean reference samples to account for benign variation through sample-specific feature reconstruction. SCR identifies poisoned samples by detecting coherent deviations from these clean baselines, without requiring prior knowledge of the attacks. We evaluate SCR through experiments covering twelve dirty-label and clean-label attacks across CIFAR-10, CIFAR-100, and Tiny ImageNet. With a small clean-reference set, SCR achieves attack-averaged true positive rates above 99.5\\% and false positive rates below 2\\% on each dataset, outperforming eight representative detection baselines in macro-TPR.","authors":["Yi Yang","Jinyang Huang","Feng-Qi Cui","Yu-Tong Guo","Sirui Zhao","Haiming Jin","Weihua Li","Quan Bai","Meng Li"],"published":"2026-11-18T14:57:37Z","updated":"2026-11-18T14:57:37Z","abstract_url":"https://arxiv.org/abs/2611.24558v1","html_url":"https://arxiv.org/html/2611.24558v1","pdf_url":"https://arxiv.org/pdf/2611.24558v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24541v1","title":"Fuse Before Reconstruct: A Novel Reconstruction Paradigm for Multimodal Industrial Anomaly Detection","abstract":"Industrial anomaly detection plays a pivotal role in precision manufacturing, where joint analysis of multimodal data emerges as a critical approach to enhance detection accuracy. Feature reconstruction, a dominant paradigm for such joint analysis, is primarily implemented through intra-modal and cross-modal methods, both of which are plagued by significant limitations. Intra-modal reconstruction neglects complementary cross-modal information, while its cross-modal counterpart is prone to projection errors and ambiguous one-to-many mappings (e.g., same textures mapping to multiple geometries), leading to detection failures. To address these limitations, we propose a novel feature reconstruction paradigm, Fuse Before Reconstruct (FBR), which first fuses multimodal features and then performs reconstruction for anomaly detection. Firstly, we propose a bidirectional cross-modal attention mechanism to achieve deep feature complementarity between image and point cloud features, mitigating projection bias through channel alignment and dynamic spatial prior integration. Besides, a learnable pixel-wise gated fusion strategy is adopted to preserve multi-modal structural consistency while optimizing local feature combination. Finally, dual-path collaborative reconstruction is implemented to recover original modal features from the fused representations, where cross-modal consistency constraints effectively eliminate mapping ambiguities. Extensive experiments show that FBR achieves 98.3% I-AUROC on MVTec 3D-AD and 92.6% I-AUROC on Eyecandies, surpassing previous state-of-the-art methods by +2.9% and +4.1%, respectively.","authors":["Zhi Li","Hanyu Wang","Qiyu Chen","Fei Shen","Zhengtao Zhang"],"published":"2026-11-18T14:49:34Z","updated":"2026-11-18T14:49:34Z","abstract_url":"https://arxiv.org/abs/2611.24541v1","html_url":"https://arxiv.org/html/2611.24541v1","pdf_url":"https://arxiv.org/pdf/2611.24541v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24524v1","title":"SCRiD: Spatial and Contextual References for Generalizable AI-Generated Video Detection","abstract":"Generalizable AI-generated video detection remains challenging because natural motion and content variations can resemble synthesis artifacts, making isolated video discrepancies unreliable indicators of authenticity. To address this challenge, we propose Spatial and Contextual Reference-informed Detection (SCRiD), a framework that interprets video variations through complementary spatial and contextual references. Specifically, we introduce Matched-Coordinate Residual Response (MCR) to characterize temporal residual associations under motion and coordinate references with matched subpixel sampling conditions. We further develop Real-Conditioned Score Adaptation (RCSA), which learns a content-conditioned denoising reference from authentic videos and probes its responses across multiple noise scales and quality views to guide feature adaptation. To integrate these complementary sources of evidence, we design Reversible Evidence Exchange (REE) to enable information exchange through reversible symplectic updates. We train SCRiD using synthetic videos from only 4 generators and evaluate it across 88 generator or task subsets spanning 6 benchmarks. Our method achieves average ACC and AP of 72.72% and 74.23%, respectively, outperforming the strongest baseline by 3.24 and 0.81 percentage points.Ablation and robustness experiments further validate the effectiveness of the proposed components and the stability of SCRiD under common post-processing operations.","authors":["Hao Tan","Zekai Zuo","Boyang Chen","Jinghui Qin"],"published":"2026-11-18T14:39:20Z","updated":"2026-11-18T14:39:20Z","abstract_url":"https://arxiv.org/abs/2611.24524v1","html_url":"https://arxiv.org/html/2611.24524v1","pdf_url":"https://arxiv.org/pdf/2611.24524v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24521v1","title":"RAID: Representation Autoencoder for Intrinsic Decomposition","abstract":"Single-image intrinsic decomposition is an inherently ill-posed problem, requiring the disentanglement of strongly coupled appearance factors from a single RGB observation. Recent methods address this ambiguity with diffusion priors, at the cost of large, iterative, and often stochastic models. We show that accurate decomposition does not require a large generative model. Our key idea is to decouple reconstruction from decomposition on top of a strong pretrained representation. First, an $X \\rightarrow X$ teacher learns to reconstruct each intrinsic map from DINOv3 features using a shared decoder, without paired RGB-to-intrinsic supervision. Then, a DINOv3-based student predicts the corresponding teacher representations from RGB through lightweight, modality-specific projections, enabling training on partially annotated datasets and predicting all intrinsics in a single forward pass. \\textbf{RAID}, predicts intrinsic properties in the structured latent space, enabling a compact 165M-parameter model, 100x faster than diffusion-based methods. Despite its compact size, it achieves competitive or superior decomposition quality, with improved robustness to input resolution. Additionally, our learned projections yield interpretable, modality-specific feature spaces.","authors":["Claudia Cuttano","Tamy Boubekeur","Elena Garces","Giuseppe Vecchio"],"published":"2026-11-18T14:38:46Z","updated":"2026-11-18T14:38:46Z","abstract_url":"https://arxiv.org/abs/2611.24521v1","html_url":"https://arxiv.org/html/2611.24521v1","pdf_url":"https://arxiv.org/pdf/2611.24521v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24512v1","title":"Comparing Each Generation with Independent Siblings Gives Video World Model Post-Training a Proper Objective for Outcome Frequencies","abstract":"Video world models are used as simulators, so when a first frame leaves several physical outcomes open, repeated generations should produce each outcome as often as it occurs in the data. Physics post-training scores every generation against the single recorded future of its history, which makes single videos more faithful, but the expected score is linear in the model distribution and is maximized by always producing the most likely outcome. The log-likelihood of the recorded outcome is maximized by the data distribution, and its gradient weights agreement with the record by the inverse of how often the model produces the generated outcome, a frequency that other generations of the same history with independent noise, its siblings, can estimate. To train with this weight from a finite group, we propose SibPO, which performs Sibling-paired Policy Optimization: siblings estimate a truncated inverse-frequency weight for agreement with the record, and a second term subtracts the same weight times the agreement with the siblings, which makes the expected objective a strictly proper divergence over outcome cells at every group size. On PisaBench, SibPO lowers the KS distance to simulated landing times by 9.1-10.2% relative to the strongest method outside its reward family on three of four video models without degrading single videos, and it lowers the error of estimated robot policy success rates by 13%.","authors":["Xin Li","Yiwen Chen"],"published":"2026-11-18T14:34:06Z","updated":"2026-11-18T14:34:06Z","abstract_url":"https://arxiv.org/abs/2611.24512v1","html_url":"https://arxiv.org/html/2611.24512v1","pdf_url":"https://arxiv.org/pdf/2611.24512v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24494v1","title":"RECLAIM: Robot-Vision-Informed Adversarial Patch Defense via Embodied Attention Feedback","abstract":"Vision-language-action policies control embodied agents through a perception-action loop grounded in physical interaction, where adversarial patches can corrupt action predictions and thereby alter subsequent observations. To mitigate these threats, many existing defenses rely on policy adaptation or auxiliary models, but require additional training or inference. We introduce RECLAIM, a training-free, inference-time defense that uses a frozen VLA's own attention response to local visual interventions to guide purification during closed-loop embodied manipulation. Our key insight is that attention changes induced by local edits provide feedback for choosing where and how to purify as the robot interacts with its environment. RECLAIM combines this feedback with robot geometry to refine patch localization and select local treatments, then revalidates them as the agent's embodied actions change the observed scene. We evaluate RECLAIM against patches generated by four adversarial attack methods across multiple manipulation task suites under frozen VLA control. Under adversarial patch attacks, RECLAIM succeeds in at least one rollout on 95% of the evaluated tasks and raises rollout success on LIBERO-Object from 0% without defense to 70.0%. Its mean decision time is only 548.9 ms per control step. These results highlight policy-guided visual purification as an effective approach to defending embodied agents against adversarial patches and recovering closed-loop task execution.","authors":["Jiayou Zhu","Peng Guo","Litian Zhang","Xinze Shi","Yuting Zhang","Zelong Yu","Yize Tian","Jirong Liu","Zifeng Kang"],"published":"2026-11-18T14:24:10Z","updated":"2026-11-18T14:24:10Z","abstract_url":"https://arxiv.org/abs/2611.24494v1","html_url":"https://arxiv.org/html/2611.24494v1","pdf_url":"https://arxiv.org/pdf/2611.24494v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24479v1","title":"Every Query Routes Itself: Accelerating Video Diffusion Transformers with Per-Query Routed Sparse Attention","abstract":"Self-attention over long token sequences dominates the inference cost of video diffusion transformers. Clustering-based sparse attention clusters both queries and keys and lets all queries in a cluster share one selection of key clusters. We show that this sharing limits accuracy: with key clusters and density fixed, attention grows more accurate as the query clusters are refined, and is most accurate when each query selects on its own, which needs no query clustering at all. We therefore propose Per-Query Routed Sparse Attention (PQRS), a training-free method that clusters only keys, lets each query select its own key clusters, and compensates for the unselected ones with their centroids. Per-query selections leave no query tile with a shared key list, so PQRS traverses key clusters instead of queries, buckets queries with identical selections into dense tasks, and merges their partial results in one pass under a fixed softmax offset carried from the previous denoising step. On four text-to-video and image-to-video models from the Wan and HunyuanVideo families, PQRS is the fastest of all the sparse attention methods we evaluate and the closest to the dense output, reaching $28.9$ dB PSNR on Wan2.1-T2V and $35.4$ dB on HunyuanVideo at $1.66$--$2.10\\times$ end-to-end speedup.","authors":["Zhen Huang","Shuwei Li","Ruizhe Yao","Xinrui Chen","Danyi Liu","Haoyuan Liang","Zhiyu Ye","Qiuyan Sun","Bingwei Chen","Yiyuan Li","Xu Zhou","Haohuan Fu"],"published":"2026-11-18T14:17:16Z","updated":"2026-11-18T14:17:16Z","abstract_url":"https://arxiv.org/abs/2611.24479v1","html_url":"https://arxiv.org/html/2611.24479v1","pdf_url":"https://arxiv.org/pdf/2611.24479v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24457v1","title":"ShoWorld: Shape-Faithful Multi-Hypothesis Occupancy World Model","abstract":"Occupancy world models struggle to forecast moving objects due to motion uncertainty and shape distortion. A single trajectory can average plausible futures into an implausible path, and repeated re-voxelization can erode or inflate object shape even under correct motion. We introduce ShoWorld to address these challenges through separate motion and shape representations. The motion forecaster predicts probabilistic trajectories conditioned on scene layout, nearby agents and the future ego trajectory. Each hypothesis is rendered into occupancy and fused according to its probability to retain alternative futures. The shape component predicts sub-voxel points with occupancy probabilities and offsets from local geometry. These points move rigidly with the object, and voxel occupancy follows the probability that at least one occupied point falls within it. This representation reduces shape distortion under motion. ShoWorld achieves state-of-the-art results on Occ3D-nuScenes. With ground-truth occupancy and ego trajectory, it improves mIoU and IoU by 6.56 and 9.16 points overall and by 6.06 and 5.53 points on dynamic classes.","authors":["Zhiqiang Yan","Guangfa Wang","Yuan Wu","Jian Yang","Gim Hee Lee"],"published":"2026-11-18T14:02:31Z","updated":"2026-11-18T14:02:31Z","abstract_url":"https://arxiv.org/abs/2611.24457v1","html_url":"https://arxiv.org/html/2611.24457v1","pdf_url":"https://arxiv.org/pdf/2611.24457v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24451v1","title":"EviScope: Evidence-Conditioned Sampling for Long-Range 3D Detection","abstract":"Query-based camera-radar detectors choose where and over which frames each object query samples from the query's position or feature. We test whether radar evidence around the query should also set these choices at the 150 m range of MAN TruckScenes, where recall differs across object-level radar-return counts within every range band. EviScope is a minimal test: the current frame's returns form a non-learned bird's-eye evidence field, which each query reads at its decoded centre to scale its radial sampling extent and to weight eight frames. It adds 5,450 parameters (0.009%) to RaCFormer, with no latency increase in our timing. Our module-free recipe exceeds the published TruckScenes mAP (25.9 over seven runs against 24.1), so we measure the module only against its own baseline at matched seeds. The evidence a query reads rises with its object's return count (Spearman 0.51) but captures zero-return objects only in part, and the learned radius tracks it ($ρ\\approx-0.91$ in four runs). Over seven four-epoch pairs the module changes NDS by $+0.31\\pm0.36$ and mAP by $-0.27\\pm0.22$ (mean $\\pm$ SE). Against a geometry-only conditioner with the same parameter count, trained at three matched seeds, it is higher by $+1.25\\pm0.72$ NDS and $+0.87\\pm0.21$ mAP, on mAP in every pair, and the control's mean NDS is near the baseline's. An exploratory far-range gain failed an internally pre-specified held-out test, and large inference-time substitution penalties also occur without query-local evidence: neither learned allocation nor inference-time dependence substitutes for matched end-to-end comparisons.","authors":["Mingyang Lyu","Yinqian Sun","Gongce Cao","Chujie Tang","Yuhao Zhang","Lu Jia","Qian Zhang","Bo Wang","Pin Lyu"],"published":"2026-11-18T14:00:09Z","updated":"2026-11-18T14:00:09Z","abstract_url":"https://arxiv.org/abs/2611.24451v1","html_url":"https://arxiv.org/html/2611.24451v1","pdf_url":"https://arxiv.org/pdf/2611.24451v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24443v1","title":"NativeSeg: Native Vision Language Segmentation of 3D Computed Tomography via Spatial Visual Tokens and Verified Local Zoom","abstract":"Text prompted 3D computed tomography (CT) segmentation requires both full slice context and fine boundary precision across volumes where over $80\\%$ of organ prompted slices lack the queried target. Existing medical vision language models (VLMs) are largely non native segmenters: they delegate pixel delineation outside the VLM by compressing reasoning into a 1D [SEG] vector for an external Segment Anything Model (SAM) decoder, quantizing masks into lossy discrete codebooks, or issuing box prompts to stateless external SAM tools without empty slice screening or spatial state memory. We introduce NativeSeg, a native vision language segmentation framework on Low Rank Adaptation (LoRA) adapted Qwen3.8-27B that performs dense mask decoding, volumetric triage, spatial error self diagnosis, and multiround local zoom directly over the VLM's 2D spatial visual tokens without external SAM decoders. NativeSeg decodes confidence maps from upper layer 2D spatial tokens fused with a five slice U-Net pathway, halts at zero zooms on $>91\\%$ of standalone evaluations via a native presence gate (<pres>), localizes uncertain boundaries via a 20 cell multiscale error gate (<err>), and accepts zoomed updates only when predicted error decreases. Trained solely on adult CT, NativeSeg improves Round $0$ DSC by $+19.81$ and $+7.04$ points over discrete codebook and 1D [SEG] readouts on the identical backbone, reaches $86.81\\%$ adult and $87.04\\%$ zero shot pediatric DSC, and safely refines 2D nnU-Net ($89.52\\%$ adult; $86.86\\%$ pediatric), 3D SegVol ($86.81\\%$), and 3D VoxTell ($89.85\\%$).","authors":["Chengqian Ma","Gaole Dai","Zijie Meng","Weixuan Jin","Yijie Du","Yuexiao Ma","Xiawu Zheng","Fei Chao"],"published":"2026-11-18T13:56:12Z","updated":"2026-11-18T13:56:12Z","abstract_url":"https://arxiv.org/abs/2611.24443v1","html_url":"https://arxiv.org/html/2611.24443v1","pdf_url":"https://arxiv.org/pdf/2611.24443v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24433v1","title":"MLIE-CoT: Chain-of-Thought Reasoning via Multi-Level Image Editing","abstract":"Chain-of-thought (CoT) reasoning has proven effective in improving the reasoning abilities of large language models by breaking complex tasks into step-by-step solutions. In recent years, researchers have attempted to extend CoT reasoning to visual generative models to improve their ability to handle complex tasks. However, existing CoT methods for text-to-image generation still rely mainly on textual reasoning and therefore cannot fully use and preserve the correct semantic information already present in an image, as even the most detailed language cannot capture all visual information. With advances in image generation, models such as FLUX and BAGEL can generate images conditioned on visual inputs. Recent work has attempted to carry images forward as context in the chain of thought, but this introduces another limitation: unsuitable earlier images can strongly interfere with the model, while repeated whole-image regeneration introduces new hallucinations at each round and causes them to accumulate. To address these issues, we propose MLIE-CoT, a visual chain-of-thought framework based on multi-level image editing. MLIE-CoT learns to select the repair granularity from three levels, preserving correct semantics whenever possible during reasoning while reducing the effect of incorrect content. To improve the ability of multimodal models to route errors of different severity to appropriate repair levels, we construct an image-repair dataset covering different error cases and use it to train a repair-level router. Extensive experiments demonstrate that MLIE-CoT significantly outperforms both its base models and methods using fixed repair strategies, producing clear improvements across multiple benchmarks.","authors":["Baichuan Yang","Dongyuan Xu","Zhao Yang","Yong Liu","Bing Su"],"published":"2026-11-18T13:49:34Z","updated":"2026-11-18T13:49:34Z","abstract_url":"https://arxiv.org/abs/2611.24433v1","html_url":"https://arxiv.org/html/2611.24433v1","pdf_url":"https://arxiv.org/pdf/2611.24433v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24423v1","title":"Probing Physics in Motion Diffusion Models Against Their Own Estimate","abstract":"Recent studies report that video diffusion models \"know more than they show\": physical properties decode better from their activations than from their inputs or outputs. But a diffusion model computes its clean-sample estimate from those same activations, so such a comparison measures how easily a readout extracts the information. Whether the model hides anything is a separate question. We set out to find hidden physical knowledge in kinematic text-to-motion diffusion models, where the physics of every intermediate estimate can be computed exactly, and recorded every layer along the sampling trajectories of MDM (two checkpoints) and MotionDiffuse. Against the usual baselines the layers do look ahead of the model's own estimate on balance and flight. With every readout tuned the same way, the estimate closes the gap: for balance and flight, adding a layer gains at most 0.01, a size that a positive control shows we would detect. The fall rate of jumps is the one clear exception. Early in denoising, MDM's layers add about 0.08 in $R^2$ (up to 0.11 in a refit) that the estimate does not yet show, and the gain fades as sampling proceeds; on MotionDiffuse it is small and not robust. The estimate also flags floating samples without training, but aborting them saves under a tenth of the compute. In a video model, plausibility that linear probes miss in Wan 2.1's clean latent becomes readable after one fixed nonlinearity.","authors":["Saeed Ghorbani"],"published":"2026-11-18T13:44:03Z","updated":"2026-11-18T13:44:03Z","abstract_url":"https://arxiv.org/abs/2611.24423v1","html_url":"https://arxiv.org/html/2611.24423v1","pdf_url":"https://arxiv.org/pdf/2611.24423v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24422v1","title":"Resolution as Attention for Efficient Agent Memory Perception","abstract":"LLM-based agents accumulate extensive interaction histories when solving complex, long-horizon tasks, making efficient memory management critical to their performance and scalability. While existing memory management methods primarily focus on what to retain or retrieve, they often overlook how much perceptual detail should be allocated to individual past interactions. We posit that effective agent memory depends not only on the information preserved, but also on the granularity at which each past interaction is perceived. Motivated by this insight, we propose Resolution as Attention (RAA), a memory perception mechanism that uses visual resolution as a means of attention allocation across interaction histories. RAA renders past interactions as images and dynamically adjusts their resolution at every step according to their relevance to the agent's upcoming decision, preserving fine-grained information for critical interactions while reducing visual-token consumption for less relevant ones. To adaptively determine the perceptual fidelity of each interaction, we train a lightweight relevance estimator with teacher-model guidance and further optimize it to preserve the agent's decision consistency at a reduced visual-token cost. Experiments across multiple tasks and backbones show that RAA reduces token consumption by over 50% without compromising task performance. Moreover, RAA can be integrated as a plug-in perception layer with existing memory management methods, yielding further token savings and revealing adaptive perception as a complementary dimension of agent memory.","authors":["Siqi Xiang","Zhipeng Xu","Shengrui Liu","Zulong Chen","Chunyan Miao","Shijian Lu"],"published":"2026-11-18T13:43:16Z","updated":"2026-11-18T13:43:16Z","abstract_url":"https://arxiv.org/abs/2611.24422v1","html_url":"https://arxiv.org/html/2611.24422v1","pdf_url":"https://arxiv.org/pdf/2611.24422v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24419v1","title":"PhysResponse: Probing the Physics of Video Generation with Controlled Interventions","abstract":"Video generation models are increasingly viewed as world simulators, which requires not only plausible motion but dynamics that respond correctly to specified physical parameters. Existing models, datasets and benchmarks, however, largely target physical plausibility, leaving this physical parameter responsiveness insufficiently explored. We introduce PhysResponse, a benchmark that measures it at two levels: scene-conditioned simulator inversion recovers the effective gravity, friction and initial speed of generated motion, and event evaluation tests outcomes near and across critical transitions. Evaluating ten image-to-video models, we find that even the lowest parameter errors exceed those of physically correct videos by over an order of magnitude, that models rarely reproduce both outcomes of a transition pair, and that the two levels expose complementary failures that visual metrics such as PSNR miss. To supply the missing training signal, we construct 72,000 simulated videos of 20 multi-object interaction types with controlled parameters; fine-tuning on them lowers parameter errors, even on held-out interaction types, and transfers to real videos and an external physics benchmark. Continued training with a numerical encoder further lowers all three errors on held-out types. PhysResponse provides a foundation for world simulators that follow physical conditions, not just appearances.","authors":["Yuhan Li","Shuran Zhang","Haixin Tian","Baonuo Rao","Weipeng Li","Yujia Hou","Zhenyu Wang","Zijun Wang","Luoyang Lin","Lijing Luo","Jiehui Huang","Kaiyuan Yang","Jingbin Tan","Panwen Hu","Xiaodan Liang"],"published":"2026-11-18T13:42:16Z","updated":"2026-11-18T13:42:16Z","abstract_url":"https://arxiv.org/abs/2611.24419v1","html_url":"https://arxiv.org/html/2611.24419v1","pdf_url":"https://arxiv.org/pdf/2611.24419v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24410v1","title":"Why Multi-Source Audio Fails to Compose: A Geometric Diagnosis and Its Remedy","abstract":"Multi-source audio-to-image generation exhibits consistent compositional failures when audio tokens occupy geometrically displaced, semantically unanchored positions in the CLIP text-token space, where the diffusion U-Net lacks the prior to reliably attend to them or ground them in distinct spatial regions. We formalize this as the geometric displacement phenomenon and expose it through a two-level clustering analysis comparing BEATs and CLAP embeddings at the raw encoder and projected CLIP token levels. Three geometric properties emerge as important: intra-class compactness, angular alignment with the CLIP text manifold, and inter-token spatial separation. We show that CLAP, whose contrastive language-audio pretraining aligns embeddings with natural language semantics, substantially outperforms BEATs on all three properties, improving the silhouette score by more than 3x and the Audio-Image Content score as well. Building on this analysis, we introduce a multi-token extension that requires no diffusion-backbone retraining and assigns each audio source to a distinct placeholder token in the CLIP tokenizer, complemented by a mixed inference-time objective that combines Attend-and-Excite with an A* spatial separation loss to resolve residual cross-token interference. For evaluation, we construct multi-audio compositional benchmarks from VGGSound (VGG2, VGG3, and VGGN) and extend six standard audio-image metrics to the multi-source setting. Across five benchmarks and four strong baselines, our method achieves strong results on the metrics most directly tied to compositional faithfulness, with AIC improvements of up to 2.25x over the strongest baseline and FID reduced by nearly 2x on two-source generation. We propose geometric displacement as a diagnostic framework for cross-modal generation systems that project learned embeddings into a pretrained contrastive space.","authors":["Anurag Singh","Prajwal Singh","Shanmuganathan Raman"],"published":"2026-11-18T13:38:35Z","updated":"2026-11-18T13:38:35Z","abstract_url":"https://arxiv.org/abs/2611.24410v1","html_url":"https://arxiv.org/html/2611.24410v1","pdf_url":"https://arxiv.org/pdf/2611.24410v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24408v1","title":"StrideWorld: Benchmarking Scene Rigidity and Action Consistency in Interactive Video World Model","abstract":"Interactive video world models turn user commands into the exploration of a generated scene, which requires the scene to keep its 3D structure as the camera moves and each action to keep a stable effect. Existing benchmarks mostly evaluate these properties against references fitted to the video under test, either a scene reconstructed from its own frames or a camera trajectory aligned to the command path with a free scale. Such references can absorb gradual scene deformation and changes in pace and route length, so these errors can pass undetected. We therefore introduce StrideWorld, a benchmark whose references are fixed before the motion they judge. It evaluates scene rigidity against the ground-truth geometry of the start view, and action consistency against the stride of each action, the camera motion of one command. The stride is measured on the model's first steps and then used to test the steps that follow, so each model is judged only against its own steps. Its measurements are validated on rendered videos with known camera motion, and its scores agree with human judgments. Across \\nvideos{} videos generated by \\nmodels{} open models from $140$ start views, all models but one deform their scenes as the camera moves, with offsets up to $7.3$ times those of a rigid rendering along the same camera path. Most models keep a steady pace when a single action is held. Along composed routes, several models often stall, and most completed routes end away from the positions predicted by each model's own strides. Only the two models that scale commands by the estimated scene depth bring most routes close to these positions. Fine-tuning two models on a few rendered clips removes most of their mid-route stalls. Code, data, and a leaderboard are publicly available at https://github.com/chuangwang123/strideworld.","authors":["Chuang Wang","Rui Nie","Jie Song","Junyuan Gao","Jiahe Song","Haitao Zhou","Boyu Zhu","Xing Li","Jiang Wu","Conghui He","Qian Yu","Weijia Li"],"published":"2026-11-18T13:37:51Z","updated":"2026-11-18T13:37:51Z","abstract_url":"https://arxiv.org/abs/2611.24408v1","html_url":"https://arxiv.org/html/2611.24408v1","pdf_url":"https://arxiv.org/pdf/2611.24408v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24404v1","title":"RAPID: Reconstruction Accelerated by Polarization-Informed Depth for 2D Gaussian Splatting","abstract":"Efficient and accurate 3D surface reconstruction from multi-view images remains a fundamental challenge in Gaussian splatting. Many existing methods rely on sparse geometric initialization and iterative densification, resulting in substantial optimization overhead and difficulties in balancing rendering quality and geometric accuracy, particularly in reflective and weakly textured regions. To address these limitations, we propose RAPID, a geometry-first framework that uses multiview polarization cues to recover dense surface priors. We integrate surface normals into depth maps using sparse geometric anchors. These depth maps are then fused across views. Curvature-adaptive sampling and oriented Gaussian initialization then support efficient optimization. Experiments on the PISR dataset demonstrate an approximately \\(5\\times\\) speedup over PhyGaP, which is a state-of-the-art Gaussian-based reconstruction method. RAPID reduces the average optimization time from approximately 21 minutes (PhyGaP) to 4 minutes while maintaining competitive novel-view synthesis quality and mesh reconstruction accuracy. These results demonstrate the effectiveness of RAPID in accelerating Gaussian optimization from polarimetric multi-view inputs.","authors":["Daisong Ouyang","Linlin Xia","Liangkun Yan","Song Gu","Shedong Zhao","Xin Dai","Yi Zheng"],"published":"2026-11-18T13:35:43Z","updated":"2026-11-18T13:35:43Z","abstract_url":"https://arxiv.org/abs/2611.24404v1","html_url":"https://arxiv.org/html/2611.24404v1","pdf_url":"https://arxiv.org/pdf/2611.24404v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24380v1","title":"Where Should a Diffusion Transformer Meet Its Teacher?","abstract":"Representation Alignment (REPA) significantly accelerates Diffusion Transformer training by guiding intermediate student features with a pretrained visual teacher, yet existing methods typically attach supervision to a single fixed layer. As student representations evolve, however, we find that the most effective layer for alignment varies across training stages. To track this evolving layer suitability online without costly search, we measure gradient compatibility between the flow-matching and alignment objectives, and propose AdaREPA, an online routing framework that adaptively selects the supervision layer as training progresses. AdaREPA uses a softmax distribution over smoothed layer compatibility scores to sample a layer for alignment at each training step. This probabilistic routing adapts teacher supervision to the student's changing learning needs, with minimal training overhead and no additional inference cost. On ImageNet-256, AdaREPA accelerates convergence and improves generation quality across model sizes, while revealing how the most suitable layers for supervision shift over training.","authors":["Zhuoqi Hu","Shiwei Li","Haozhao Wang","Xiandi Luo","Yihao Ouyang","Wenting Shen","Ang Wang","Jiamang Wang","Minyi Guo","Ruixuan Li"],"published":"2026-11-18T13:09:28Z","updated":"2026-11-18T13:09:28Z","abstract_url":"https://arxiv.org/abs/2611.24380v1","html_url":"https://arxiv.org/html/2611.24380v1","pdf_url":"https://arxiv.org/pdf/2611.24380v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24373v1","title":"CanopyKV: Remember beyond the Crop for Fast Active Visual Reasoning","abstract":"Active visual reasoning enables multimodal models to answer challenging visual questions by gathering fine-grained evidence through iterative image inspection and tool use. However, accumulating crops and reasoning tokens expands the key-value (KV) cache, making compression important for reducing memory and inference costs. Existing KV compression methods typically select historical tokens based on attention, recency, or redundancy. These criteria do not explicitly distinguish locally replaced evidence from complementary information needed for future exploration: each crop refreshes a local region, while earlier views may still support subsequent decisions. Discarding such evidence can impair accuracy or require additional search, while scoring and cache reorganization can offset the computational savings from compression. We introduce CanopyKV, a training-free KV compression framework that uses parent-child crop relationships to retain complementary evidence, keeps retained history stable, and protects the state needed for ongoing reasoning. Tool metadata provides retention signals without additional attention scoring, while compact KV storage reduces subsequent attention costs. Across VisualProbe, V*, HR-Bench, and MME-Lite, CanopyKV achieves state-of-the-art answer accuracy and end-to-end efficiency among the evaluated KV compression methods. On MME-Lite, it retains approximately one-quarter of Dense's total KV while improving accuracy by 10.5 percentage points and accelerating complete reasoning by $1.64\\times$.","authors":["Lei Yang","Dayan Wu","Yiliang Zhu","Xinze Liu","Hengjie Zhu","Zihao Zhang","Ding Wang","Peng Fu","Zheng Lin"],"published":"2026-11-18T13:05:16Z","updated":"2026-11-18T13:05:16Z","abstract_url":"https://arxiv.org/abs/2611.24373v1","html_url":"https://arxiv.org/html/2611.24373v1","pdf_url":"https://arxiv.org/pdf/2611.24373v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24371v1","title":"One Affinity, Two Axes: Bidirectional Slot Attention for Iterative Aggregation across the Structure--Detail Spectrum in Visual Retrieval","abstract":"Aggregating dense patch tokens into compact and discriminative global descriptors is central to visual retrieval. Although foundation models provide rich local features, existing aggregation heads still rely on single-pass mappings and lack an explicit mechanism to coordinate structural and fine-grained cues. Therefore, we propose Bidirectional Slot Attention (BiSA), which reformulates aggregation as an iterative coupled system. Cross-Axis Consensus (CAC) progressively refines learnable slots by interpreting a single shared token--slot affinity along two complementary axes. Along the competition axis, slots vie for each token under a temperature shared across all of them, determining token ownership and inducing a non-redundant scene decomposition. Along the selection axis, a slot-specific temperature governs the breadth of each slot's response, spanning a spectrum from broad layouts to sparse fine-grained details. Their consensus couples non-redundant decomposition with multi-granular slot specialization. Furthermore, the two axes expose intrinsic token-reliability cues at no extra cost: a token's claim strength under competition and its salience under selection. Progressive Token Filtering (PTF) converts these cues into a retention probability that down-weights unreliable tokens before the next CAC iteration, without any segmentation branch or external prior, forming a self-reinforcing loop of competitive decomposition, selective focusing, and feedback purification. Across all three retrieval tasks, BiSA leads on five of six place recognition benchmarks (+4.2 R@1 on Baidu Mall), tops all 16 metrics of drone--satellite geo-localization (+8.4 R@1 at 150 m), and improves instance-level retrieval on ROxford-Hard by 4.5 mAP points. Notably, the selection axis adds only 20 learnable scalars, yet improves average R@1 by 2.8 points.","authors":["Zihang Wang","Wenkai Zhu","Lingdong Kong","Teng Yan","Alan Liang","Shuyuan Li","Xieyuanli Chen","Dong Kong","Guanyu Zong"],"published":"2026-11-18T13:04:10Z","updated":"2026-11-18T13:04:10Z","abstract_url":"https://arxiv.org/abs/2611.24371v1","html_url":"https://arxiv.org/html/2611.24371v1","pdf_url":"https://arxiv.org/pdf/2611.24371v1.pdf","matched_keywords":["retrieval","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24366v1","title":"SCOUT: Risk-Guided Foundation-Model Escalation for Robust Tissue Detection in Whole-Slide Images","abstract":"Reliable tissue detection is essential for whole-slide image analysis, yet high average segmentation accuracy can conceal failures involving pale tissue, small fragments, and heterogeneous staining. Pathology foundation models offer transferable representations, but exhaustive inference is computationally demanding and may introduce false-positive tissue predictions. We propose SCOUT (Selective Correction of Uncertain Tissue), a risk-guided cascade that selectively refines an initial thumbnail-based tissue mask. A lightweight audit network estimates the spatial distribution of segmentation errors and prioritizes candidate regions for processing by a frozen pathology foundation model. An asymmetric consensus rule integrates the resulting predictions with the initial mask to recover missed tissue while limiting false positives. A calibrated slide-level review score additionally controls the marginal rate of unflagged case-group failures under the calibration assumptions. Evaluation on a public multi-source, multi-stain benchmark shows that SCOUT reduces the proportion of case groups requiring mask correction from 38.1% for the best released detector to 18.6%, with particularly pronounced improvements in immunohistochemistry. Source-held-out experiments demonstrate better generalization than a segmentation network trained on the same annotations, while selective inference achieves an observed failure rate no higher than processing all candidate regions. Downstream, lymph-node classification with SCOUT masks is non-inferior to that obtained with two of the three released detectors evaluated. A variant built on an openly licensed foundation model is publicly released as an installable Python package with trained weights. These results support risk-guided foundation-model inference as an effective approach to tissue detection across heterogeneous histopathology data.","authors":["Cristian Tommasino","Antonio M. Rinaldi"],"published":"2026-11-18T13:00:38Z","updated":"2026-11-18T13:00:38Z","abstract_url":"https://arxiv.org/abs/2611.24366v1","html_url":"https://arxiv.org/html/2611.24366v1","pdf_url":"https://arxiv.org/pdf/2611.24366v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24363v1","title":"Transferable Named Sparse Features for Morphology-based Gleason Grading","abstract":"Deep learning systems grade prostate biopsies at the level of pathologists, but most report a grade without the glandular architecture that justifies it. This work presents a grading system built on a sparse code over the tokens of a pathology foundation model. A sparse autoencoder pretrained on biopsies is aligned with multi-reader annotations, so that 69 of its 2048 features are named after Gleason morphologies such as cribriform glands, cords, and comedonecrosis. The same code feeds a grading network, which reads all features to predict Gleason patterns and the Grade Group, while morphology maps read directly from the named features. We evaluate the system on five public datasets that include needle biopsies, tissue-microarray cores, multi-reader annotations, and three scanners. The morphology maps remain stable across alignment runs and, without retraining, detect cribriform glands in external biopsies (area under the receiver operating characteristic curve, AUROC, 0.849) and pattern 5 in unseen cores when evaluated by up to six pathologists (AUROC 0.846 to 0.919). In an independent biopsy cohort, Grade Group agreement with three pathologists on Leica scans is close to their agreement with each other. Removing the named features reduces the corresponding Gleason pattern predictions by 49% to 98%, with effects larger than those from 20 activity-matched random feature removals. These results show that a shared sparse representation can support competitive Gleason grading while providing named morphological evidence that transfers across datasets and whose contribution to grading can be measured directly.","authors":["Argyrios Zafeiriou","Athanasios Kallipolitis","Ilias Maglogiannis"],"published":"2026-11-18T12:57:35Z","updated":"2026-11-18T12:57:35Z","abstract_url":"https://arxiv.org/abs/2611.24363v1","html_url":"https://arxiv.org/html/2611.24363v1","pdf_url":"https://arxiv.org/pdf/2611.24363v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24352v1","title":"OCTR2A: Real-Time RGB-to-BEV Trajectory Projection and Forecasting at Urban Intersections","abstract":"Trajectory forecasting at urban intersections is often studied assuming that reliable bird's-eye-view (BEV) motion histories are available, which in practice requires costly resources such as LiDAR, aerial views, HD maps, or calibrated infrastructure. We address this upstream perception-to-forecasting problem by reconstructing and predicting agents' BEV trajectories only from paired opposite-corner RGB cameras mounted on existing urban infrastructure at variable heights at inference time. We introduce the Opposite-Corner Trajectory Reconstruction and Anticipation Architecture (OCTR2A), a modular pipeline integrating per-view detection with class refinement, geometric cross-camera matching, transformer-based BEV projection, and egocentric GRU forecasting, trained in cascade and mainly supervised with a soft multi-scale spatial-overlap loss. Since no public benchmark provides this sensing configuration, we introduce R3ST++, a Blender-based synthetic benchmark built from SIND trajectories that provides synchronized opposite-corner views, cross-view correspondences, and BEV ground truth, while also serving as a deployment-support simulator for site-specific fine-tuning. Experiments on these datasets show that, with 12 observed and 12 predicted frames at 10\\,Hz, OCTR2A achieves projection~-~forecasting ADE/FDE of 0.144/0.140~-~0.154/0.241~meters in real time on a single consumer GPU. Evaluated on ground-truth BEV histories, the forecasting module improves over the strongest state-of-the-art methods on SIND by 66.7\\%/41.7\\% ADE/FDE. Transfer experiments on TUMTraf-V2X show that R3ST++ pretraining supports adaptation to real-world roadside domains with different sensing configurations.","authors":["Emanuele Iacobelli","Simone Teglia","Francesco Pro","Claudia Melis Tonti","Irene Amerini"],"published":"2026-11-18T12:47:15Z","updated":"2026-11-18T12:47:15Z","abstract_url":"https://arxiv.org/abs/2611.24352v1","html_url":"https://arxiv.org/html/2611.24352v1","pdf_url":"https://arxiv.org/pdf/2611.24352v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24296v1","title":"AnchorUp: Anchoring Feature Upsampling on a Classical Interpolation","abstract":"Vision foundation models produce semantically strong features on a coarse patch grid, and dense prediction needs them at pixel resolution. Existing learned upsamplers close that gap by regressing the high-resolution feature map from the low-resolution one, typically through cross-attention driven by the input image. We observe that most of what they regress needs no learning: plain bilinear interpolation already reproduces the smooth regions of the target, and recent benchmarks even report bilinear and bicubic on par with several learned upsamplers. The rest is mostly edges and fine details, which suggests that these learned upsamplers spend much of their capacity re-computing the smooth content that classical interpolation provides. We therefore introduce AnchorUp, which stops predicting the high-resolution feature map and predicts only its correction from the interpolation. It keeps a parameter-free classical upsampler as an anchor, obtains a second prediction from a small guidance network, and blends the two through a single learnable scalar gate. Because the anchor supplies the smooth content, the guidance network only has to correct what remains. An analysis of the learned correction confirms that it concentrates on edges and fine details, and so the network can be small: AnchorUp uses 167,425 parameters, a quarter of the budget of the strongest baseline, NAF, and runs at 64% of its latency. Trained once on DINOv3 with only the first of NAF's two training stages, and evaluated on that backbone plus six held-out ones, it is already on par with NAF trained through both stages on Pascal VOC and Cityscapes. Our method surpasses it on DAVIS-2017 video object segmentation; the gain holds on every backbone and is larger in contour accuracy F. Code is available at https://github.com/KotaroHorikawa/AnchorUp.","authors":["Kotaro Horikawa","Keisuke Toida","Junya Komori","Kazuhiro Hotta"],"published":"2026-11-18T12:08:07Z","updated":"2026-11-18T12:08:07Z","abstract_url":"https://arxiv.org/abs/2611.24296v1","html_url":"https://arxiv.org/html/2611.24296v1","pdf_url":"https://arxiv.org/pdf/2611.24296v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24284v1","title":"CROMPT: Adapting CLIP via Cross-Modal Prompting for Robust Zero-Shot Generalization under Adverse Weather","abstract":"Domain adaptation for semantic segmentation is challenging when target-domain images are unavailable during training. Zero-shot domain adaptation addresses this by adapting models using only textual descriptions of the target domain. However, existing prompt-learning methods are not well suited for ResNet-based CLIP vision backbones or pixel-level cross-modal feature alignment. We propose CROMPT, a prompt-learning framework for zero-shot domain adaptation in semantic segmentation. CROMPT introduces Cross-Modal Feature Augmentation (CROMA), combining Random Visual Prompting with Hybrid Textual Prompting (HTP) to jointly adapt visual and textual representations. We further propose CROMA-VL, which leverages vision-language models to generate domain-conditioned prompts, and a progressive easy-to-hard adaptation strategy for improved domain invariance. Experiments on two benchmark datasets demonstrate consistent improvements over strong baselines and state-of-the-art methods, achieving 1.63-2.63% mIoU gains while maintaining inference-time complexity. These results establish CROMPT as an effective and efficient framework for zero-shot multi-domain semantic segmentation. OpenReview: https://openreview.net/forum?id=FxqFsIL685","authors":["Aniruddh Sikdar","Arya Kishor","Snehashis Dhibar","Suresh Sundaram"],"published":"2026-11-18T11:59:24Z","updated":"2026-11-18T11:59:24Z","abstract_url":"https://arxiv.org/abs/2611.24284v1","html_url":"https://arxiv.org/html/2611.24284v1","pdf_url":"https://arxiv.org/pdf/2611.24284v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24277v1","title":"Semantic Guidance for Joint Infrared-Visible Video Fusion and Frame Interpolation","abstract":"Infrared and visible video fusion at high frame rates requires recovering missing observations when camera rates differ or fall below the desired output rate. Cascading interpolation and fusion can accumulate errors and cause brightness fluctuations. Motion and occlusion further complicate content selection, particularly when missing visible frames also remove direct semantic guidance. We propose SAFI, which uses semantics at the target time to guide joint interpolation and fusion. When the visible frame rate exceeds the infrared rate, available visible frames provide semantic context directly. At times without visible observations, motion guides local matching, and propagation recovers semantics from neighboring frames. Semantic context complements aligned image features at the target time, while matching confidence helps select reliable infrared and visible information. Reconstruction and fusion share source selection within each scale, allowing supervision on missing frames to guide fusion. To preserve visible appearance and reduce flicker, we bound thermal enhancement and penalize brightness inconsistencies across frames while accounting for changes in thermal contrast. Experiments on three datasets show improved visual quality with less computation than cascaded baselines and consistent temporal gains when input rates differ. SAFI maintains strong downstream tracking performance despite missing frames. The code is available at https://github.com/XylonXu01/SAFI.","authors":["Yushen Xu","Xiaosong Li","Huaming Wu","Dongwei Ren"],"published":"2026-11-18T11:54:45Z","updated":"2026-11-18T11:54:45Z","abstract_url":"https://arxiv.org/abs/2611.24277v1","html_url":"https://arxiv.org/html/2611.24277v1","pdf_url":"https://arxiv.org/pdf/2611.24277v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24267v1","title":"Look Closer, Look Back, or Wait for Agentic Streaming Video Understanding","abstract":"Streaming video models must answer questions about a live video under strict memory and latency limits. Feeding only the latest few frames keeps present perception sharp, whereas adding past frames dilutes attention on the current scene and triggers hallucinations. Recent cascade methods retrieve past frames when uncertain, but they still fail when current frames are blurry or when decisive future clues have not appeared yet. We introduce ActiveForager, a streaming video agent that maintains a clean short working window and gathers extra evidence only on demand. For each query, the agent either answers directly, zooms into high-resolution recent frames, recalls past events from memory, or waits for upcoming frames. When recalling history, a shared-weight sub-agent verifies candidate clips in isolation and returns a compact evidence summary. A stream-decoupled attention mask then keeps historical evidence from interfering with present visual tokens. We train this policy using counterfactual information gain, which rewards a tool call only when the gathered evidence makes the true answer more likely and prevents tool collapse across all actions. Across Qwen2.5-VL-7B and Qwen3-VL-8B on OVO-Bench, ActiveForager improves real-time perception, historical recall, and proactive response at once, lifting overall accuracy on Qwen3-VL-8B from 47.6% to 65.9%. It also doubles zero-shot accuracy on the multi-hop Video-Holmes benchmark while adding minimal visual tokens per query.","authors":["Pengyu Li","Zhitao Gao","Lingling Zhang","Wenxuan Huang","YiCheng Xiao","Chen Zheng","Jun Liu"],"published":"2026-11-18T11:48:00Z","updated":"2026-11-18T11:48:00Z","abstract_url":"https://arxiv.org/abs/2611.24267v1","html_url":"https://arxiv.org/html/2611.24267v1","pdf_url":"https://arxiv.org/pdf/2611.24267v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24259v1","title":"Do Thinking VLMs Need to Keep Looking at Long Videos? Write It Down, Then Look Away","abstract":"Vision-language models (VLMs) reason about long videos over hundreds to thousands of tokens. Every decoding step re-reads the key-value (KV) cache of the entire video. Must the model keep looking while it reasons? In LookAway, the model first writes timestamped notes on what the question needs and then puts the video away. Once the notes close, the inference engine hides the video's KV cache for the rest of the response. Across both hybrid and pure-attention VLMs, dependence on the video is concentrated early in the response. On Qwen3.6-27B, writing notes preserves accuracy better than free reasoning at the same withdrawal step. Replacing them with another video's notes harms accuracy, whereas keeping the video visible alongside the model's own notes adds no significant benefit. Without additional training, LookAway nearly matches full-video thinking accuracy at 0.12-0.13 times its modeled decode cost. To shorten this initial look, we fine-tune the model on its own correct LookAway responses. Reinforcement learning then rewards correct answers while penalizing KV reads. The trained model puts the video away after a median of 66-68 tokens. Across three held-out benchmarks, it writes more tokens than an identically trained full-video model yet reads only 27-35% as many KV positions at matched accuracy.","authors":["Pengyu Li","Zhitao Gao","Lingling Zhang","Heng Wang","Chengqian Ma","WenHao Wang","Wenxuan Huang","Chen Zheng","Jun Liu"],"published":"2026-11-18T11:42:17Z","updated":"2026-11-18T11:42:17Z","abstract_url":"https://arxiv.org/abs/2611.24259v1","html_url":"https://arxiv.org/html/2611.24259v1","pdf_url":"https://arxiv.org/pdf/2611.24259v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24256v1","title":"Spark-H3: Adaptive Block Sparse Attention for Video Diffusion Models","abstract":"Long video sequences make attention a substantial cost in video diffusion models. Block sparse attention (BSA) reduces this cost by computing selected blocks exactly while compressing the remaining blocks. However, fixed token grouping can place tokens with dissimilar attention preferences in the same group, while uniform key averaging can underestimate the attention mass of compressed blocks. We introduce Spark-Attn, a training-free BSA method comprising Spark-Reblock and Spark-Reweight. Spark-Reblock recursively groups tokens by attention preference while preserving regular block shapes for efficient GPU execution. Spark-Reweight uses the global mean query as an anchor to construct attention-weighted key-value representations and logit biases for the compressed blocks, calibrating their attention mass. We instantiate Spark-Attn in MiniMax-H3 as Spark-H3. At 10% exact-block density, Spark-H3 delivers a 2.49$\\times$ DiT speedup and reaches 24.81 dB PSNR against the corresponding dense outputs on MiniMax-H3 (20 denoising steps, 345 frames, 1344$\\times$768). Increasing the density to 20% further improves PSNR to 26.76 dB while still achieving a 2.26$\\times$ DiT speedup. These results demonstrate that Spark-H3 achieves a state-of-the-art quality-efficiency trade-off for training-free BSA on video diffusion models.","authors":["Zecheng Tang","Jiaye Fu","Youtian Lin","Xinyao Rao","Liuxuan Sun","Jian Zhang","Yao Yao","Wei Li"],"published":"2026-11-18T11:32:53Z","updated":"2026-11-18T11:32:53Z","abstract_url":"https://arxiv.org/abs/2611.24256v1","html_url":"https://arxiv.org/html/2611.24256v1","pdf_url":"https://arxiv.org/pdf/2611.24256v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24253v1","title":"One Shot, Any View: High-Fidelity Video Reshooting with Geometry Guidance and Visual References","abstract":"Filming a scene from an additional angle after production usually requires a costly reshoot. We present One Shot Any View, a system that takes a recorded clip and generates a reshot video of the same performance along a user-specified camera trajectory. As in recent geometry-grounded methods, the system conditions generation on the source video and an explicit 3D prior, namely a point video rendered along the requested trajectory from a feed-forward reconstruction of the source video. We target human-centric cinematic videos, which are often shot with long lenses, shallow depth of field, and low-key lighting, all of which degrade feed-forward reconstruction. Existing geometry-grounded methods tend to inherit the degraded point video, and their output quality drops visibly. Two designs make such point videos usable. First, in addition to rendered videos of 3D assets, we train on real-world multi-camera videos, whose point videos are produced by the same reconstruction pipeline as at inference. This training-inference consistency enables the generator to take only the composition of people and scene elements from the point video, and their appearance from the source video. Second, a geometry-anchored RoPE offset keeps the generated video temporally synchronized with the source while largely preventing the output from copying the degraded appearance of the point video. Meanwhile, since the generator is a pretrained reference-to-video (R2V) model, the system also accepts optional character and scene reference images, which supply the appearance of regions that the source never shows. In both objective and human evaluations, One Shot Any View outperforms existing reshooting methods.","authors":["Kai Huang","Runze Xu","Hui Ren","Taiyi Wu","Xinyuan Li","Xun Gao","Quande Liu","Dong Tang","Tongtong Shen","Xuefeng Su","Alan Zhao"],"published":"2026-11-18T11:31:56Z","updated":"2026-11-18T11:31:56Z","abstract_url":"https://arxiv.org/abs/2611.24253v1","html_url":"https://arxiv.org/html/2611.24253v1","pdf_url":"https://arxiv.org/pdf/2611.24253v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24240v1","title":"ViLFlow: Parallel Vision-Language Generation with Continuous Latent Flows","abstract":"Vision-language generation has predominantly relied on autoregressive and discrete diffusion models. Autoregressive models generate tokens sequentially, while discrete diffusion models typically predict tokens independently within each denoising step. We propose ViLFlow (Vision-Language Flow), a continuous-flow vision-language model that combines joint modeling of output embeddings with parallel token decoding. ViLFlow adapts pretrained continuous language generation to visual question answering and image captioning through learned image guidance and prediction-aware token decoding. A visually adapted teacher provides image-guided predictions as additional denoising supervision. The denoiser learns to reproduce these predictions directly, retaining one image-conditioned prediction per generation step. We train the token decoder on denoiser predictions and paired reference text to improve the conversion of continuous outputs into words. The decoder can be adapted independently, improving answering and captioning without further denoiser training. For captioning, it also supplies text feedback during late denoising, allowing decoded words to inform subsequent refinement. ViLFlow outperforms autoregressive and masked-diffusion baselines by up to 8.46 percentage points on VQAv2 and 4.50 points on GQA without GQA training. On COCO Karpathy test, it improves CIDEr by 16.25 over masked diffusion and 17.81 over sampled autoregression.","authors":["Kevin Zhai","Bian Sun","Zhenyi Wang","Song Wang"],"published":"2026-11-18T11:19:11Z","updated":"2026-11-18T11:19:11Z","abstract_url":"https://arxiv.org/abs/2611.24240v1","html_url":"https://arxiv.org/html/2611.24240v1","pdf_url":"https://arxiv.org/pdf/2611.24240v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24233v1","title":"Psychometrics-Inspired Coreset Selection for Image Quality Assessment","abstract":"Collecting large-scale subjective annotations remains a critical bottleneck in training accurate image quality assessment (IQA) models. Coreset selection reduces this burden by selecting representative images before annotation. However, diversity in a visual feature space does not necessarily reflect diversity in perceptual quality, raising a fundamental question about which quality-related factors the representation should encode. We propose GRAM, a quality-aware representation learning framework inspired by the graded response model (GRM) from psychometrics. GRM describes how an individual's latent ability determines the probabilities of reaching successive assessment grades, with response sensitivity and grade thresholds governing this relationship. In this paper, we find that this principle naturally aligns with perceptual quality assessment, where the impact of image degradation depends on image content and distortion characteristics. Building on this connection, GRAM models quality judgments through three complementary factors: latent quality, content-dependent response sensitivity, and distortion-dependent grade thresholds. These factors jointly determine the probabilities of attaining different quality grades and the resulting expected quality score. The learned parameters provide a structured quality-aware representation that complements general visual features for coreset selection. Experiments on nine datasets demonstrate improvements across different selection strategies, downstream IQA models, and annotation budgets. The code will be made publicly available.","authors":["Susu Jiang","Xuelin Shen","Baoliang Chen"],"published":"2026-11-18T11:08:48Z","updated":"2026-11-18T11:08:48Z","abstract_url":"https://arxiv.org/abs/2611.24233v1","html_url":"https://arxiv.org/html/2611.24233v1","pdf_url":"https://arxiv.org/pdf/2611.24233v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24223v1","title":"Training Denoising Models of Any Architecture Without Stored Images","abstract":"Can a pretrained denoising model replace the dataset used to train it? We investigate this question through teacher-supervised training, showing for the first time that continuous-time diffusion and flow models of any architecture and size can be trained from random initialization without stored images. Our students regress the teacher's velocity on a rolling pool of noisy samples, advanced along trajectories of random step counts to obtain independent, dense and approximately continuous noise levels. This saves considerable storage for large datasets and applies even when the data are unreleased or private. Our experiments include 12 teachers of 6 families and 6 datasets. Our method outperforms standard training of the same network on CIFAR-10 for students 4x smaller than the teacher, comes within 0.75 to 1.92 FID of it at the teacher's size and surpasses training on teacher-generated images and step reduction methods without teacher-based initialization. Our code is available at https://github.com/mever-team/ddm.","authors":["Christos Koutlis","Ioannis Kompatsiaris","Symeon Papadopoulos"],"published":"2026-11-18T10:58:54Z","updated":"2026-11-18T10:58:54Z","abstract_url":"https://arxiv.org/abs/2611.24223v1","html_url":"https://arxiv.org/html/2611.24223v1","pdf_url":"https://arxiv.org/pdf/2611.24223v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24222v1","title":"Target-Consistent Action Guidance via Semi-Unbalanced Optimal Transport for Drifting World Models","abstract":"Action-conditioned world models let robots imagine the outcomes of their actions for planning and offline policy evaluation, but these uses need many rollouts, which multi-step diffusion makes expensive. Drifting models move the iteration from inference to training and generate samples in one network pass. DriftWorld brought this paradigm to action-conditioned world models; to strengthen action following, it repels predictions from the current frame, a construction borrowed from classifier-free guidance. We show that this accentuation has a target bias: the push persists even when a prediction matches the recorded future, in kernel, balanced, and unbalanced Wasserstein drifting fields alike. We introduce Mass-Share Accentuation (MSA) to remove this bias. MSA treats the current frame as a counterfactual destination competing with the recorded future in a semi-relaxed optimal transport problem; subtracting the closed-form share of the correct future makes the guidance vanish at the target, and the remainder is shared by all predictions. We prove that the recorded future is the unique fixed point along the motion direction for collapsed predictions, and that the guidance fades with prediction error. On Push-T, Robomimic, and BridgeV2, where trained models under-react rather than overshoot, MSA improves action ranking, response slope, and moving-region error over latent-space baselines at no inference cost, though these benchmarks do not isolate bias removal as the cause.","authors":["Md Abtahi Majeed Chowdhury","Md Rifat Ur Rahman","Md Sakib Hossain Shovon","Jaesik Choi","Minhyuk Sung"],"published":"2026-11-18T10:58:48Z","updated":"2026-11-18T10:58:48Z","abstract_url":"https://arxiv.org/abs/2611.24222v1","html_url":"https://arxiv.org/html/2611.24222v1","pdf_url":"https://arxiv.org/pdf/2611.24222v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24200v1","title":"SpiderMark: Hybrid Watermarking for Generative AI via Algorithmic Injection and Learning-Based Verification","abstract":"The proliferation of diffusion-based generative models has intensified the need for reliable methods to trace and verify the provenance of AI-generated images. Existing watermarking approaches for diffusion models typically rely on isotropic frequency patterns and handcrafted detection metrics, which are prone to directional vulnerability and threshold instability across diverse image transformations. We propose SpiderMark, a hybrid watermarking framework that combines algorithmic frequency-domain injection with learning-based probabilistic verification, requiring no modifications to pretrained diffusion model weights. SpiderMark embeds a structured spider-web pattern, comprising radial spokes and concentric polygonal rings, into the Fourier representation of the initial latent noise, and trains a lightweight ResNet-18 verifier augmented with auxiliary similarity cues (PSNR and L1) to produce a continuous watermark confidence score for watermark detection. Across nine evaluation conditions, SpiderMark achieves the highest fixed-threshold Accuracy in eight, while retaining strong detection on unseen COCO prompts without verifier retraining. CLIP similarity and FID measurements show that these detection gains are accompanied by small measured differences in prompt alignment and distributional image quality. SpiderMark establishes that structured watermark geometry and learned probabilistic verification can be unified into a single, practical framework, bridging the gap between imperceptibility, robustness, and real-world verifiability for generative AI content attribution.","authors":["Chihcheng Hsieh","Yang Song","Flora Salim","Martin Bell","Jacinto C. Nascimento","Catarina Moreira"],"published":"2026-11-18T10:36:51Z","updated":"2026-11-18T10:36:51Z","abstract_url":"https://arxiv.org/abs/2611.24200v1","html_url":"https://arxiv.org/html/2611.24200v1","pdf_url":"https://arxiv.org/pdf/2611.24200v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24197v1","title":"From Neural Tokens to Language: Dual-View EEG Semantic Bridging for Brain-to-Text Generation","abstract":"Visually evoked EEG-to-text generation aims to produce natural-language descriptions from neural responses elicited by visual stimuli. Existing approaches typically compress EEG signals into a single global representation and directly project it into the hidden space of a large language model (LLM), which may limit the preservation of complementary visual semantics under noisy and subject-dependent EEG signals. We propose a dual-view semantic token bridging framework that exploits raw images and sketch images as complementary visual supervision to learn raw-oriented and sketch-oriented EEG semantic token streams. To interface these structured neural representations with an LLM, we introduce a branch-specific semantic query bridge that aggregates each token stream into compact semantic slots and converts them into LLM-compatible soft prompts. A progressive adaptation strategy further transitions the learned visual-semantic interface from image-supported training to image-free EEG-conditioned generation. Experiments demonstrate strong subject-wise EEG classification performance and competitive EEG-to-text generation across multiple LLM backbones. Ablation, branch-level representation, and EEG-label disentanglement analyses further show that the two EEG streams learn complementary view-oriented representations and that EEG-derived prompts provide sample-specific information beyond category labels.","authors":["YaoYang Liu","Jun Dai","ZhuoShi Tang","Weijun Sun","Xiaozhao Fang","Jie Wen"],"published":"2026-11-18T10:32:57Z","updated":"2026-11-18T10:32:57Z","abstract_url":"https://arxiv.org/abs/2611.24197v1","html_url":"https://arxiv.org/html/2611.24197v1","pdf_url":"https://arxiv.org/pdf/2611.24197v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24193v1","title":"WM^MLLM: Turning MLLMs into World Models","abstract":"Video world models keep the world in the context of a generator, so a revisit is synthesized again and earlier edits can drift or disappear. We present WM^MLLM, the first interactive world model built on multimodal large language models (MLLMs), for persistent, editable world generation from a single image. WM^MLLM keeps the world state outside every generator, as a panorama with a revision history, and lets the MLLMs write it: they turn each request into operations on this state, select where a local edit is written, and check every candidate before it becomes the next state. Image generators only propose views, and video only presents them. Users can walk to new places and return, edit objects through text or a box, place subjects, and change lighting, weather or season. By construction, a revisit at the same revision reproduces the earlier view exactly, a local edit leaves every panorama pixel outside its region unchanged, and each request starts from the result of the previous one. Against six world model baselines on MBench-A, WM^MLLM has the highest mean on all four environment-recovery metrics (Epipolar 91.5 versus 0.1 to 74.0) and completes the most camera round trips (85.3% versus at most 50.9%). It has the best value in all 15 CompBench columns against 15 baselines. On 112 local edits judged blind, selecting the region to write after generation raises completion from 34.8% to 83.0%. On 258 WBench and MBench-A items, all 46 revisits recover their earlier views, and all 97 local edits that pass the check leave panorama pixels outside their region unchanged.","authors":["Baiang Li","Enze Xie","Jincheng Yu","Jin Wang","Haozhe Liu","Yitong Li","Juanxi Tian","Felix Heide"],"published":"2026-11-18T10:29:16Z","updated":"2026-11-18T10:29:16Z","abstract_url":"https://arxiv.org/abs/2611.24193v1","html_url":"https://arxiv.org/html/2611.24193v1","pdf_url":"https://arxiv.org/pdf/2611.24193v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24192v1","title":"TrajWAM: Trajectory-Conditioned Future Learning for Vision-Language Driving","abstract":"World Action Models (WAMs) connect future scene prediction with action planning for autonomous driving. Each driving record pairs an executed ego trajectory with its observed future, providing a factual outcome for learning this connection. We present TrajWAM, a trajectory-conditioned WAM that improves vision-language driving through auxiliary bird's-eye-view (BEV) future learning. An ego-trajectory query conditions DINOv3-aligned BEV predictions from shared planner representations. Training combines factual reconstruction under the executed trajectory with one-sided feature separation under an unlabeled perturbed trajectory. Together, these objectives train the shared planner to generate driving waypoints. Native inference directly generates waypoints and bypasses the auxiliary future-prediction branch. On all 220 Bench2Drive routes, TrajWAM achieves 91.53 Driving Score and 75.45% Success Rate, exceeding a schedule-matched planning-only fine-tuning baseline by 5.31 Driving Score points and eight successful routes.","authors":["Xuerui Fang","Gulimila Kezierbieke","Chen Wangxing","Hui Li"],"published":"2026-11-18T10:28:56Z","updated":"2026-11-18T10:28:56Z","abstract_url":"https://arxiv.org/abs/2611.24192v1","html_url":"https://arxiv.org/html/2611.24192v1","pdf_url":"https://arxiv.org/pdf/2611.24192v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24184v1","title":"VideoACE: Benchmarking Agentic Video Understanding through High-Frame-Rate Actions","abstract":"Agentic video understanding requires models to actively interact with video environments to gather evidence and form judgments. Evaluating this capability therefore requires assessing whether models can translate opportunities for interaction into better understanding. We introduce VideoACE, a benchmark for assessing video understanding under conditions that support sustained interaction. We focus on high-frame-rate action videos, where rapid, subtle changes make targeted observation especially valuable. The benchmark comprises 1,000 multiple-choice questions spanning six categories of fine-grained action understanding, accompanied by temporal evidence annotations and user hints screened for answer leakage. Its evaluation environment combines video inspection tools with a user simulator, allowing models to adjust temporal coverage, sampling density, and spatial detail, and to revisit evidence and revise their judgments under simulated user feedback. We evaluate single-pass observation, autonomous tool use, and tool use combined with user feedback to examine how effectively models exploit these opportunities. Evaluation of five models reveals distinct patterns in how they acquire evidence and respond to opportunities for further interaction. These findings establish VideoACE as a testbed for examining agentic video understanding beyond performance under a fixed observation setting.","authors":["Luoyuan Zhang","Xuanyu Zheng","Yancheng Long","Haoyang Xu","Bin Wen","Tingting Gao"],"published":"2026-11-18T10:26:07Z","updated":"2026-11-18T10:26:07Z","abstract_url":"https://arxiv.org/abs/2611.24184v1","html_url":"https://arxiv.org/html/2611.24184v1","pdf_url":"https://arxiv.org/pdf/2611.24184v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24182v1","title":"ART: Bridging the Embodiment Gap in 3D Human-to-Robot Affordance Transfer","abstract":"3D affordance acts as a critical link between perception and action, providing priors for robotic manipulation. While existing approaches predominantly leverage human priors as direct references, they often overlook that affordance is not an object-intrinsic property but is inherently coupled with the agent's embodiment. Due to the structural and morphological disparities between human hands and robot end-effectors, directly applying human priors causes severe incompatibility for robotic execution. Motivated by this, we introduce a novel task setting, 3D Human-to-Robot Affordance Transfer, which addresses the affordance misalignment arising from distinct embodiment structures. To support this task, we construct the Human-Robot Paired Affordance Dataset (HPAD), the first large-scale 3D affordance benchmark in which every object is annotated with both human-prior and simulation-validated robot labels. HPAD covers 2,137 objects across 80 categories and 13 atomic action primitives, yielding over 27,000 object-action pairs. On top of HPAD, we propose the 3D Affordance tRansfer neTwork (ART). ART first filters geometric false positives in the human prior via a reliability gating stream, then reconstructs the prior into a robot-actionable distribution through hierarchical reconstruction and a graph-diffusion refinement that resolves the topological mismatch between human and robot affordances. Experiments on HPAD demonstrate the reliability of the proposed task and the superiority of ART. We further validate ART on a 6-DoF arm with a parallel-jaw gripper in a 2,400-execution benchmark across 12 objects and 4 action categories; ART attains the best success rate (86.5% over its 480 trials), confirming the practicality of the transfer paradigm. Project page: https://derek0907.github.io/ART/","authors":["Zichen Zhang","Wei Zhai","Xuji Zhang","Yang Cao","Yu Kang"],"published":"2026-11-18T10:22:42Z","updated":"2026-11-18T10:22:42Z","abstract_url":"https://arxiv.org/abs/2611.24182v1","html_url":"https://arxiv.org/html/2611.24182v1","pdf_url":"https://arxiv.org/pdf/2611.24182v1.pdf","matched_keywords":["3d","agent","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24171v1","title":"Efficient World-Model Planning via Physics-Guided Search Distillation","abstract":"World models support autonomous driving by evaluating candidate trajectories through predicted future scene evolution. However, accurate future prediction does not ensure road-compliant execution; when all candidates violate road boundaries, re-ranking cannot select a feasible trajectory. We propose Physics-Guided Search Distillation (PGSD), a single-view planning framework that combines future representations and execution feedback for verified beyond-pool repair through three components: (1) Execution-Aware Selection checks ego-vehicle road compliance under simulated execution and selects the highest-scoring feasible trajectory; (2) a Clearance-Aware Search Teacher generates beyond-pool corrections and selects demonstrations with larger minimum road-boundary clearance during execution to buffer imitation errors; and (3) a Future-Conditioned Repair Student predicts one correction from rewarder features and execution feedback for single-rollout verification. The pretrained planner and rewarder remain frozen; no future scenes are generated online. On NAVSIM v1, single-view PGSD achieves 90.97 PDMS, exceeding all compared prior single-view planners and retaining 73.2% of the search teacher's PDMS gain over execution-aware selection. On NAVSIM v2 navhard, it reaches 38.96 EPDMS, improving on WorldDrive by 11.24 points (40.5%). The student replaces up to ten search rollouts with a single verification rollout per repair trigger. HUGSIM Hard examples provide qualitative evidence of zero-shot transfer.","authors":["Hongyu Zhang","Xiaoshuai Hao","Heye Huang","Qingwen Meng","Wenjun Shi","Jianao Xu","Xin Hu","Xuanru Jin","Jingyi Zhang","Baicang Guo"],"published":"2026-11-18T10:14:22Z","updated":"2026-11-18T10:14:22Z","abstract_url":"https://arxiv.org/abs/2611.24171v1","html_url":"https://arxiv.org/html/2611.24171v1","pdf_url":"https://arxiv.org/pdf/2611.24171v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24170v1","title":"ViStep-RL: Stepwise Reinforcement Learning for Long-Horizon Visual Agents","abstract":"Long-horizon visual agents must do more than inspect images: they must turn observations into evidence that remains usable as a task unfolds. Existing active-perception methods teach agents where and how to look, while a final-answer reward gives little structure for deciding which observations satisfy dependent subgoals or should be retained for later use. We present ViStep-RL (Visual Stepwise Reinforcement Learning), which models execution as a dependency-linked graph of evidence-bearing subgoals. A verifier tracks which subgoals are supported by valid evidence, and changes in graph potential provide a net-progress learning signal; an active memory protocol preserves evidence across turns and links retrieval to downstream use. On ViInteract, ViStep-RL reaches 60.0% strict completion with Qwen2.5-VL-7B, compared with 10.0% for the base model and 46.5% after supervised fine-tuning. Controlled studies show that incremental task-state rewards outperform cumulative rewards by 3.2 points, while active evidence writing improves strict completion by 7.75 points over automatic writing. Under a common interaction framework, the task-trained ViStep-RL policy achieves 59.5% answer accuracy, 24.0 points above the strongest of six general-purpose reference models. Held-out episodes confirm the gain at both Qwen scales, and gains extend to three external visual reasoning benchmarks.","authors":["Junyang Chen","Yao Qin","Xiao Li","Ningchao Wang","Yiguo Qiao","Wenbin Li","Xin Geng"],"published":"2026-11-18T10:12:30Z","updated":"2026-11-18T10:12:30Z","abstract_url":"https://arxiv.org/abs/2611.24170v1","html_url":"https://arxiv.org/html/2611.24170v1","pdf_url":"https://arxiv.org/pdf/2611.24170v1.pdf","matched_keywords":["retrieval","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24164v1","title":"Gaussian Primitive Fusion for Any-Resolution Multimodal Images","abstract":"Multimodal image fusion integrates complementary observations from different modalities into a unified representation. Existing methods typically estimate modality contributions on a common discrete grid. When source modalities have different native resolutions, constructing such a grid generally involves resampling, which may introduce artifacts and affect subsequent fusion decisions. To address this problem, we propose Gaussian Primitive Fusion (GPF), which reformulates heterogeneous-resolution fusion in a shared continuous Gaussian space. Instead of first converting source images to a common resolution, GPF directly fits their native-resolution observations with shared Gaussian geometry and modality-specific content representations, and learns modality contributions within the resulting continuous representation. Once optimized, the fused representation is rendered at the finest native resolution without resampling the sources. With heterogeneous-resolution inputs, GPF produces clearer target contours and finer textures, with less blurring and blocking artifacts than resample-then-fuse pipelines. Quantitatively, it achieves the best results on multiple infrared-visible benchmarks against state-of-the-art fusion methods equipped with interpolation or super-resolution frontends.","authors":["Baoshuo Cai","Xinrui Jiang","Bing Cao"],"published":"2026-11-18T10:06:21Z","updated":"2026-11-18T10:06:21Z","abstract_url":"https://arxiv.org/abs/2611.24164v1","html_url":"https://arxiv.org/html/2611.24164v1","pdf_url":"https://arxiv.org/pdf/2611.24164v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24163v1","title":"Stabilizing Neural-to-Image Retrieval with Frequency-Domain Priors and Adaptive Supervision","abstract":"Visual neural decoding aims to infer perceived visual stimuli from brain activity, offering important insights into human visual cognition while enabling transformative applications in brain computer interfaces and artificial intelligence. Recent advances in pretrained vision-language models have provided a semantically rich representation space for this task. However, reliable alignment between EEG/MEG signals and visual embeddings remains challenging because neural responses are noisy, highly variable across trials, and subject dependent. To address this issue, we propose a unified neural-to-image retrieval framework that improves retrieval performance by aligning neural and image representations in a shared semantic space. The framework integrates dual-stream adaptation, frequency-domain calibration, and phase-guided temperature modulation to promote more robust cross-modal semantic alignment. Specifically, dual-stream adaptation models a low-dimensional shared subspace with correlation regularization to suppress redundant noise and enhance cross-modal consistency. Frequency-domain calibration conditionally modulates neural representations using amplitude and phase statistics. Phase-guided temperature modulation further adjusts the supervision strength in contrastive learning according to the stability of neural responses. Experiments on THINGS-EEG and THINGS-MEG under both intra-subject and inter-subject settings demonstrate that the proposed framework consistently outperforms strong baselines. These results suggest that robust neural-to-image retrieval under heterogeneous neural conditions benefits from a stable shared semantic space, frequency-informed representation calibration, and adaptive supervision. Code will be released at github.com/wanfkuabc/Geometry-Regularized-Brain-Embeddings.","authors":["YaoYang Liu","ZhuoShi Tang","Haopeng Lai","Weijun Sun","Xiaozhao Fang","Jie Wen"],"published":"2026-11-18T10:06:13Z","updated":"2026-11-18T10:06:13Z","abstract_url":"https://arxiv.org/abs/2611.24163v1","html_url":"https://arxiv.org/html/2611.24163v1","pdf_url":"https://arxiv.org/pdf/2611.24163v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24161v1","title":"AVTR: Adaptive Multimodal Reasoning with Visual Imagination","abstract":"Vision-Language Models increasingly rely on textual reasoning to solve advanced multimodal tasks. Despite its effectiveness, this paradigm faces two fundamental limitations. First, relying on textual reasoning alone can limit perceptual ability in vision-centric questions, where accurate answers depend on interpreting task-relevant visual evidence. Second, applying textual reasoning uniformly across inputs overlooks question-dependent variation in both reasoning modality and depth, often producing verbose and unnecessary traces when little logical inference is required. To this end, we propose Adaptive Visual-Textual Reasoning (AVTR), which introduces visual imagination as a complementary reasoning modality to textual thinking, enabling the model to revisit its visual observations and distill the salient evidence through generative visual reflection. Furthermore, we formulate reasoning-modality selection as a learned routing problem, allowing a single policy to adaptively harness the complementary strengths of visual reflection and textual reasoning in response to the perceptual and inferential demands of the input. Across 16 benchmarks, AVTR improves the average score by 4.5 points over Qwen3.5 baseline, while reducing inference latency by 33\\%. It also scales effectively into a smaller size backbone, outperforming the evaluated 2B-scale baselines.","authors":["Xiaoqian Shen","Yunyang Xiong","Changsheng Zhao","Saksham Suri","Chong Zhou","Zechun Liu","Zhipeng Cai","Zhuang Liu","Qi Qian","Wei Wen","Hongyu Xu","Hanxian Huang","Ernie Chang","Yanbei Chen","Vikas Chandra","Raghuraman Krishnamoorthi","Mohamed Elhoseiny","Lemeng Wu"],"published":"2026-11-18T10:05:18Z","updated":"2026-11-18T10:05:18Z","abstract_url":"https://arxiv.org/abs/2611.24161v1","html_url":"https://arxiv.org/html/2611.24161v1","pdf_url":"https://arxiv.org/pdf/2611.24161v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24154v1","title":"Game2Player: Scaling Gameplay Experience for Visual Agents through Environment-Player Co-Development","abstract":"Games are a rich testbed for visual agents, demanding perception, long-horizon planning, and precise control. However, collecting human gameplay is costly, and learning from gameplay videos requires inferring missing actions. Existing datasets also cover a limited range of games, often without explicit tasks or verifiable outcomes. To address these gaps, we introduce Game2Player, a framework that co-develops game environments and players to collect diverse and verifiable gameplay experience at scale. In the Game2Player loop, a Builder agent adapts existing web games, exposes their internal state, and defines tasks with state-based progress measures and success checks. A Coding Player and a VLM Player then attempt the tasks and report problems to the Builder for repair, so that play serves as both environment validation and training data collection. With Game2Player, we build 568 verified web games with 3,436 tasks, collect 15.7K trajectories (307 hours of gameplay), and hold out 50 games as the benchmark PlayerBench. To evaluate the collected experience as training data, we train VLM agents with progress-weighted SFT, assigning greater weight to steps that advance task progress. Game2Player-9B improves progress from 14.3% to 31.2% on PlayerBench and from 30.0% to 53.1% on the external GameWorld benchmark. More broadly, our work suggests a path for visual agents to scale their gameplay experience by building, verifying, and learning from existing game worlds.","authors":["Xirui Jiang","Yuxi Chen","Rui Yang","Feng Luo","Pengcheng Wang","Bingxuan Li","Zihao Zhao","Yushan Li","Han Wang","Manling Li","Yang Zhang","Shiyu Chang","Tong Zhang","Huan Zhang"],"published":"2026-11-18T09:58:53Z","updated":"2026-11-18T09:58:53Z","abstract_url":"https://arxiv.org/abs/2611.24154v1","html_url":"https://arxiv.org/html/2611.24154v1","pdf_url":"https://arxiv.org/pdf/2611.24154v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24152v1","title":"SEER: Semantic Evidence for Executable Region Propagation in Open-Vocabulary Semantic Segmentation","abstract":"Training-free open-vocabulary semantic segmentation (OVSS) has made strong progress by adapting CLIP-like representations to dense prediction, but its remaining errors are often local, structured, and tied to the active label space. A successful correction must be visually plausible, legal under the target vocabulary, and executable in the segmentation score field. We propose SEER, a training-free test-time repair layer for Semantic Evidence and Executable Region propagation. SEER casts post-prediction OVSS repair as evidence-conditioned label propagation. The OVSS score space proposes compact candidate labels, a frozen VLM verifies closed-set regional evidence, and an execution gate certifies whether the evidence is legally and semantically actionable. The accepted label is then propagated by an OVSS-side policy: coherent high-confidence regions allow broad propagation, while object- or boundary-risk cases use conservative score-grounded propagation. Across eight standard OVSS benchmarks, SEER reaches 58.0 average mIoU without updating OVSS weights. Matched-input controls isolate the repair mechanism, while resource measurements report the cost of the complete frozen system.","authors":["Junyang Chen","Xiao Li","Yiguo Qiao","Wenbin Li"],"published":"2026-11-18T09:56:02Z","updated":"2026-11-18T09:56:02Z","abstract_url":"https://arxiv.org/abs/2611.24152v1","html_url":"https://arxiv.org/html/2611.24152v1","pdf_url":"https://arxiv.org/pdf/2611.24152v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-11-19T08:18:20+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":71,"new_or_recent_papers":[{"id":"2611.24941v1","title":"UltraTex: Aligning Physical Knowledge for High-Fidelity PBR Texture Generation","abstract":"Generating physically based rendering (PBR) texture maps for a 3D mesh from a single reference image is highly ambiguous, as the observed appearance entangles material identity, surface reflectance, and illumination. While current generative methods produce realistic albedo maps, they still struggle to infer accurate metallic and roughness attributes for relighting. We present UltraTex, a cascaded multi-view framework that moves beyond appearance matching by integrating physical knowledge into multi-view diffusion-based PBR generation. UltraTex first jointly predicts albedo and world-space shading normals to generate more detailed albedo maps, and then predicts metallic-roughness (MR) maps conditioned on the generated albedo, reference image, and material semantic priors. To inject material semantics, a lightweight adapter transforms hidden-layer features of a vision-language model (VLM) into intrinsic material representation tokens, providing part-level knowledge anchors for MR estimation. To model material-light interaction, photometric representation alignment guides intermediate diffusion features toward ground-truth material renderings under controlled lighting. This makes metallic and roughness variations observable through highlight intensity, specular sharpness, and local reflectance contrast, providing stronger guidance for fine-grained material prediction without explicit lighting supervision. Extensive experiments show that UltraTex generates high-quality textures and outperforms existing open-source and commercial methods in visual fidelity, material accuracy, and physical plausibility.","authors":["Jingzhi Bao","Xiaohe Ma","Hong Li","Yuanming Hu","Xiaoguang Han"],"published":"2026-11-18T18:59:57Z","updated":"2026-11-18T18:59:57Z","abstract_url":"https://arxiv.org/abs/2611.24941v1","html_url":"https://arxiv.org/html/2611.24941v1","pdf_url":"https://arxiv.org/pdf/2611.24941v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"html","source_text_chars":73645,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, diffusion 相关；摘要显示其主要贡献为：Generating physically based rendering (PBR) texture maps for a 3D mesh from a single reference image is highly ambiguous, as the observed appearance entangles material identity, surface reflectance, and illumination. While current generative methods produce r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24940v1","title":"$Z$-sight: Unifying Vision-Language-Action and Latent World Modeling","abstract":"We introduce $Z$-sight, a unified robot foundation model that couples vision-language-action (VLA) and generative latent world modeling. Video-based world action models (WAMs) show the value of joint future-and-action generation for control, yet inherit the heavy cost of video generators. Recent latent-space policies avoid pixel generation, yet typically align intermediate features or rely on frozen target encoders, decoupling future prediction from the VLM's native feature space. $Z$-sight instead predicts the future directly in the visual token space in which its VLM perceives the present. Coupling a foresight expert and a continuous action expert with the VLM in a mixture-of-transformers, $Z$-sight jointly denoises future spatial tokens and actions at inference without pixel reconstruction or external encoders. Trained on human video and robot trajectories, $Z$-sight achieves 81.9% success on SIMPLE (+9.6 points over the strongest baseline) and 73.3% across six Unitree G1 tasks (+20.0 points) at 110 ms per chunk, while remaining competitive on tabletop benchmarks.","authors":["Junjie Ye","Yiqi Zhao","Muchen Xu","Celina Shiyu Wang","Hao Dong","Ruohai Ge","Rong Xue","Benjamin J Kolligs","Aditya Dutt","Sasanka Nagavalli","Nassim A. Samad","Gaurav S. Sukhatme","Jyotirmoy V. Deshmukh","Yue Wang","Yuliang Guo"],"published":"2026-11-18T18:59:38Z","updated":"2026-11-18T18:59:38Z","abstract_url":"https://arxiv.org/abs/2611.24940v1","html_url":"https://arxiv.org/html/2611.24940v1","pdf_url":"https://arxiv.org/pdf/2611.24940v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":86804,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We introduce $Z$-sight, a unified robot foundation model that couples vision-language-action (VLA) and generative latent world modeling. Video-based world action models (WAMs) show the value of joint future-and-action generation for control, yet inherit the h...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24915v1","title":"PrismRestore: A Compact Restoration Toolbox for Agentic Image Restoration","abstract":"Agentic image restoration composes operations to handle mixed degradations, yet its toolbox often requires storing multiple restoration networks. We propose PrismRestore, which constructs a compact bank of callable restoration actions from a single frozen all-in-one model. Our approach builds on task-dependent yet overlapping channel responses in the shared model. An offline task-prior search uses activation and gradient statistics to group channels with similar response profiles, then searches task-specific modulation coefficients over non-representative channels while leaving representative channels unmodulated. The resulting prior bank enables explicit action selection and composition without additional restoration backbones or task-specific adapter modules. A state-conditioned policy learns to compose these actions using Group Relative Policy Optimization. Its objective separately normalizes fidelity and perceptual feedback within groups of trajectories sampled for the same input, and combines terminal evaluation with return-to-go derived from stepwise quality changes. Experiments on synthetic composite-degradation and real-world multi-task benchmarks show improvements over the evaluated all-in-one baselines and restoration quality competitive with multi-model agents. PrismRestore achieves these results with a single restoration backbone and faster inference than the evaluated agentic baselines.","authors":["Zhaocheng Yu","Kui Jiang","Jing Cao","Yiang Chen","Xiaocheng Feng","Junjun Jiang","Xianming Liu"],"published":"2026-11-18T18:48:01Z","updated":"2026-11-18T18:48:01Z","abstract_url":"https://arxiv.org/abs/2611.24915v1","html_url":"https://arxiv.org/html/2611.24915v1","pdf_url":"https://arxiv.org/pdf/2611.24915v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":50008,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic image restoration composes operations to handle mixed degradations, yet its toolbox often requires storing multiple restoration networks. We propose PrismRestore, which constructs a compact bank of callable restoration actions from a single frozen all...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24864v1","title":"NereidVLA: Learning to Understand and Navigate the Underwater World","abstract":"Underwater navigation requires translating visual spatial cues into motion, yet marine vision-language datasets rarely include paired robot trajectories. We present NereidVLA, a vision-language-action model that transfers marine spatial knowledge to language-conditioned 3D navigation. We first train Sea2Know on approximately two million marine examples to learn target grounding, spatial relations, and scene structure without paired robot-motion supervision. We then adapt it using expert trajectories executed under simulated underwater vehicle dynamics. Given RGB histories and a language instruction, NereidVLA predicts discrete motion tokens that decode into local 3D trajectories for closed-loop tracking. Evaluation combines an independent six-dimensional underwater navigation understanding benchmark with offline prediction and closed-loop navigation. Under matched navigation training and execution settings, marine spatial pretraining increases simulation success from 72.4% to 84.4%. Without fine-tuning on the real test environment, NereidVLA achieves 78.75% success in laboratory-pool robot trials, compared with 47.50% for InternVLA-N1. These results show that marine spatial supervision can support downstream motion learning and physical underwater navigation.","authors":["Chenjie Zhao","Zhiliang Zhu","Quan Chen","Yuquan Xue","Xingxue Shi","Puyue Wang","Zhiqiang Zhao","Kangye Zheng","Boyang Xu","Mingwei Lin","Dejun Li"],"published":"2026-11-18T18:19:00Z","updated":"2026-11-18T18:19:00Z","abstract_url":"https://arxiv.org/abs/2611.24864v1","html_url":"https://arxiv.org/html/2611.24864v1","pdf_url":"https://arxiv.org/pdf/2611.24864v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":58634,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Underwater navigation requires translating visual spatial cues into motion, yet marine vision-language datasets rarely include paired robot trajectories. We present NereidVLA, a vision-language-action model that transfers marine spatial knowledge to language-...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24862v1","title":"Gaspard: Expressive unified speech and gesture synthesis with continuous autoregressive flow-matching and decoupled classifier-free guidance","abstract":"Human communication involves highly coordinated multimodal signals such as speech and co-speech gestures. Existing approaches for generating both modalities commonly follow a cascaded pipeline, where speech is generated first and subsequently used to drive gesture generation; speech generation is therefore independent of gestures. We introduce Gaspard, a unified speech--gesture generation model based on continuous autoregressive generation with next-step flow-matching predictions, and trained on Seamless Interaction, a large-scale multimodal dataset. The heterogeneous temporal properties of speech and gesture motivate modality-specific prediction heads and decoupled classifier-free guidance over the two generation streams. This guidance rebalances the influence of speech and gesture at inference time, improving expressivity while mitigating dynamics collapse in continuous autoregressive gesture generation. Objective and perceptual evaluations show that Gaspard is a strong gesture generation model against unimodal baselines and that it produces highly synchronous speech and gestures compared to a matched cascaded system.","authors":["Téo Guichoux","Théodor Lemerle","Catherine Pelachaud","Nicolas Obin"],"published":"2026-11-18T18:18:44Z","updated":"2026-11-18T18:18:44Z","abstract_url":"https://arxiv.org/abs/2611.24862v1","html_url":"https://arxiv.org/html/2611.24862v1","pdf_url":"https://arxiv.org/pdf/2611.24862v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":87957,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Human communication involves highly coordinated multimodal signals such as speech and co-speech gestures. Existing approaches for generating both modalities commonly follow a cascaded pipeline, where speech is generated first and subsequently used to drive ge...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24806v1","title":"ReCoCo: From Patches to Compositions for Visual Representation Learning","abstract":"Self-supervised learning has produced powerful visual representations, yet learning strong dense features remains challenging. While consistency between augmented views provides strong image-level supervision, extending this principle to local visual content is less straightforward. Existing approaches often match individual patches across views or identify coherent regions, introducing uncertainties in correspondence estimation and assumptions about how visual content should be grouped. We introduce ReCoCo (Regional Composition Consistency), a principled approach that extends cross-view consistency to the regional level without requiring such correspondences or semantic grouping. ReCoCo represents the content shared between augmented views through compositions of their patch-level predictions over learned visual prototypes. By aligning these compositions, the model learns from regions containing multiple visual concepts without requiring them to be separated beforehand. ReCoCo integrates naturally with teacher-student self-distillation and introduces no additional learned parameters. Extensive experiments demonstrate substantial improvements in frozen-feature segmentation, clustering, and regional retrieval while maintaining competitive image-level recognition, alleviating the trade-off between dense and global representation quality.","authors":["Juan Gutiérrez","Saman Zadtootaghaj","José Luis Blanco-Murillo","Sara Atito"],"published":"2026-11-18T17:45:04Z","updated":"2026-11-18T17:45:04Z","abstract_url":"https://arxiv.org/abs/2611.24806v1","html_url":"https://arxiv.org/html/2611.24806v1","pdf_url":"https://arxiv.org/pdf/2611.24806v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"html","source_text_chars":53330,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, representation 相关；摘要显示其主要贡献为：Self-supervised learning has produced powerful visual representations, yet learning strong dense features remains challenging. While consistency between augmented views provides strong image-level supervision, extending this principle to local visual content...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24805v1","title":"Edge-Efficient Joint RAW Image Compression and Restoration for Smart Wearable Devices","abstract":"Smart wearable devices, such as augmented reality glasses, increasingly rely on cameras to understand and interact with their surroundings. However, their compact sensors often capture noisy RAW images, while limited compute and power make high-quality on-device restoration difficult. This creates an emerging need to reduce both local computation and transmission cost without sacrificing image quality. Two common solutions are to offload restoration or to compress the raw data before transmission. The first makes RAW transmission costly; the second reduces the payload but can spend bitrate preserving sensor noise. We address this fundamental mismatch with an asymmetric framework for joint RAW compression and restoration that directly optimizes the transmitted representation for clean image reconstruction. A lightweight on-device encoder compresses noisy RAW measurements into a bitstream, while a higher-capacity backend decoder jointly denoises and demosaics the encoded representation. We use knowledge distillation to train a smaller encoder for tighter compute budgets. Experiments on real and synthetic data show improved rate-restoration performance over strong cascaded compression-restoration pipelines and learned compression baselines. On SIDD, our method improves PSNR by more than 1.5 dB over cascaded baselines at approximately 0.25 bits per pixel. We further validate the method on real 12 MP RAW images captured with commercial smart glasses and measure sender-side latency on both smartphone and smart-glasses hardware. The distilled encoder achieves a 27.6$\\times$ NPU inference speedup over on-device NAFNet for 256$\\times$256 output patches. The code is available at https://github.com/coolsyn2000/CRAW","authors":["Yunong Sun","Sicheng Chen","Fei Xia"],"published":"2026-11-18T17:44:34Z","updated":"2026-11-18T17:44:34Z","abstract_url":"https://arxiv.org/abs/2611.24805v1","html_url":"https://arxiv.org/html/2611.24805v1","pdf_url":"https://arxiv.org/pdf/2611.24805v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":47821,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Smart wearable devices, such as augmented reality glasses, increasingly rely on cameras to understand and interact with their surroundings. However, their compact sensors often capture noisy RAW images, while limited compute and power make high-quality on-dev...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:22+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24795v1","title":"Ultimate3D: Teaching Multimodal LLMs 3D Camera-Object Relations by Large-Scale Visual Instruction Data","abstract":"Multimodal Large Language Models (MLLMs) struggle with accurately capturing camera-object relations, especially for object orientation, camera viewpoint, and camera shots. This stems from the fact that existing MLLMs are trained on images with limited diverse camera-object relations and corresponding textual descriptions. To address this, we propose a synthetic generation pipeline to create large-scale 3D visual instruction datasets. Our framework takes 3D assets as input and uses rendering and diffusion-based image generation models to create photorealistic images preserving precise camera-object relations. Additionally, large language models (LLMs) are used to generate text prompts for guiding visual instruction tuning and controlling image generation. We create Ultimate3D, a large-scale 3D-grounded 2D visual instruction dataset. Ultimate3D consists of 240K VQAs with precise camera-object annotations, and corresponding benchmark. MLLMs fine-tuned on our proposed dataset outperform commercial models by a large margin, achieving an average accuracy improvement of 29.7% on camera-object relation recognition tasks. Our code, dataset, and benchmark will contribute to broad MLLM applications.","authors":["Liu He","Yizhi Song","Ruiqi Xu","Baris Sarper Tezcan","Xiao Zeng","Albert Y. C. Chen","Lu Xia","Shashwat Verma","Sankalp Dayal","Min Sun","Cheng-Hao Kuo","Daniel Aliaga"],"published":"2026-11-18T17:39:54Z","updated":"2026-11-18T17:39:54Z","abstract_url":"https://arxiv.org/abs/2611.24795v1","html_url":"https://arxiv.org/html/2611.24795v1","pdf_url":"https://arxiv.org/pdf/2611.24795v1.pdf","matched_keywords":["3d","multimodal","diffusion"],"source_used":"html","source_text_chars":107759,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, multimodal, diffusion 相关；摘要显示其主要贡献为：Multimodal Large Language Models (MLLMs) struggle with accurately capturing camera-object relations, especially for object orientation, camera viewpoint, and camera shots. This stems from the fact that existing MLLMs are trained on images with limited diverse...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24793v1","title":"The Elephant in the Question: Unified Models Picture the Concepts Behind Their Answers","abstract":"Visualizing intermediate representations could help us inspect the reasoning steps underlying a model output. Unified multimodal models offer this opportunity by combining understanding and generation in one architecture. Their image generators can access representations formed while processing text. We introduce the V-lens, which uses this connection to visualize a chosen token's hidden state without training a decoder. Across four diffusion-based and two purely autoregressive unified models, the resulting images reveal key intermediate concepts that connect a question to its answer even when the concepts are never named explicitly. Controlled tests show how this content changes with context, token position, and depth. We then introduce lens tuning, which supervises selected hidden states with pictures through the V-lens. Across BAGEL, SenseNova-U1, and HunyuanImage-3.0, the rate of correct visualizations of pronoun referents rises from 2-11% to 86-94%. Surprisingly, such visual supervision also improves text answers without supervising the answer tokens directly. Code is available at https://github.com/multimodal-ai-lab/V-lens.","authors":["Tobias Braun","Marcus Rohrbach","Lorenzo Cavallaro"],"published":"2026-11-18T17:38:46Z","updated":"2026-11-18T17:38:46Z","abstract_url":"https://arxiv.org/abs/2611.24793v1","html_url":"https://arxiv.org/html/2611.24793v1","pdf_url":"https://arxiv.org/pdf/2611.24793v1.pdf","matched_keywords":["representation","multimodal","diffusion"],"source_used":"html","source_text_chars":120325,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal, diffusion 相关；摘要显示其主要贡献为：Visualizing intermediate representations could help us inspect the reasoning steps underlying a model output. Unified multimodal models offer this opportunity by combining understanding and generation in one architecture. Their image generators can access rep...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24792v1","title":"Training-free motion statistics match self-supervised behavior encoders","abstract":"Self-supervised encoders for animal behavior are often trained on, or fed, hand-built movement features. We ask whether they beat those ingredients when compared fairly. A training-free representation, made of generic per-frame measurements summarized over fixed time windows and reduced with PCA, is compared with retrained and released encoders (BAMS, hBehaveMAE) under a preregistered protocol: frozen representations of equal size and one shared classifier. On CalMS21 it reaches 85.8 macro F1 against 82.4 for the best encoder, ties with four labelled videos, and leads when the annotator changes or new behaviors must be learned from a few videos; the reading holds for encoders retrained with three seeds. On the MABe22 mouse triplets it scores 83.7 against 80.3 for the released hBehaveMAE (gap +3.4, 95% interval +2.1 to +4.7). On a second species, the MABe22 fly groups, the same recipe scores 51.6 mean F1 over 50 tasks against 48.2 for BAMS, the best published method. On Shot7M2, the synthetic basketball benchmark built by hBehaveMAE's authors, it scores 68.8 against 64.7 for hBehaveMAE, the best method in that paper, though hBehaveMAE remains better on the shortest movements. Short time windows carry most of the result. Raw keypoints in each body's own frame, summarized over the same windows, already match or beat the encoders on both mouse datasets and on Shot7M2; on the fly groups they fall short, and the measurements add 5.3 points. On these benchmarks, current behavior encoders have yet to beat the hand-built features they learn from, and such baselines should be reported alongside them.","authors":["Ziwen Chen"],"published":"2026-11-18T17:38:27Z","updated":"2026-11-18T17:38:27Z","abstract_url":"https://arxiv.org/abs/2611.24792v1","html_url":"https://arxiv.org/html/2611.24792v1","pdf_url":"https://arxiv.org/pdf/2611.24792v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":41535,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Self-supervised encoders for animal behavior are often trained on, or fed, hand-built movement features. We ask whether they beat those ingredients when compared fairly. A training-free representation, made of generic per-frame measurements summarized over fi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24776v1","title":"4D-TEMPO: Differentiable 4D-STEM ptychography via fast Physics Optimizers","abstract":"Electron ptychography recovers atomic structure from 4D-STEM data: diffraction patterns at multiple positions of a scanned probe. Current codes reconstruct an image and read atoms off it, or fit atoms under an $L_1$ loss; neither gives per-atom uncertainty. We propose 4D-TEMPO, a differentiable physical renderer that fits the atoms, the microscope, and the detector directly to the recorded electron counts under a Poisson likelihood. The output is a list of atoms, each a Gaussian primitive with a 3D position, a thermal width, and a model-conditional error bar from the Fisher information. The Fisher information also conditions the solver, gives the dose (electrons per Å$^2$) each parameter needs, and separates calibration from imaging. On a simulated WSe$_2$ bilayer, starting from the published reconstruction, fitted atoms cut in-plane error by a third (3.2 vs. 4.8 pm) and depth error by 40-61% against its 3D peaks. Depth comes from multiple scattering into the dark field, the faint counts outside the direct beam. The two layers, $10\\times$ closer than the depth of field, separate; per-atom depth then follows the layer geometry. When the model is well specified, the bars are calibrated (69% of position coordinates within $1σ$). On experimental WSe$_2$, fitted atoms predict held-out patterns better than the three published codes we test. With free probe modes where atoms are incomplete, the same likelihood predicts best on all three held-out benchmarks, matches every WSe$_2$ baseline in 5 min against up to 20.5 h, and passes torchslice at its released setting 180$\\times$ sooner on PrScO$_3$. Per-atom error bars, planned doses, and fast reconstruction point to low-dose, real-time 3D imaging of beam-sensitive and dynamic materials.","authors":["Ramani Duraiswami","Yichao Zhang"],"published":"2026-11-18T17:23:50Z","updated":"2026-11-18T17:23:50Z","abstract_url":"https://arxiv.org/abs/2611.24776v1","html_url":"https://arxiv.org/html/2611.24776v1","pdf_url":"https://arxiv.org/pdf/2611.24776v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":192981,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Electron ptychography recovers atomic structure from 4D-STEM data: diffraction patterns at multiple positions of a scanned probe. Current codes reconstruct an image and read atoms off it, or fit atoms under an $L_1$ loss; neither gives per-atom uncertainty. W...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24762v1","title":"A$^3$Bench: Compositional Reasoning over Aggressive Interactions in Videos","abstract":"Recent Multimodal Large Language Models (MLLMs) have achieved strong performance on general video understanding benchmarks, yet their ability to reason about participant roles in aggressive interactions remains largely unexplored. Existing violence and crime datasets primarily evaluate whether aggression occurs, without testing whether models can identify who performed the action, who received it, and how participants are related within the scene. To address this gap, we introduce A$^3$Bench, a benchmark to study aggressive action and association in videos. The benchmark evaluates whether models can jointly recognize aggressive actions, distinguish aggressors from victims and bystanders, and correctly bind actions to participants under challenging distractor settings. We benchmark 17 multimodal models and find that they struggle substantially on fine-grained aggressive-scene understanding. Performance degrades consistently as reasoning complexity increases, with models frequently confusing aggressors with victims or bystanders, revealing a systematic failure in role-action association rather than coarse aggression recognition alone. We further observe that increasing model scale or generic reasoning models experience limited improvement. Finally, we explore a simple role-graph prompting strategy that encourages structured reasoning over participant interactions, leading to improvements in compositional reasoning. Our findings highlight that reliable aggressive-scene understanding remains a major challenge for current MLLMs and motivate future research on role-aware video reasoning beyond coarse violence detection. Code and dataset: https://github.com/austincbaker/A3Bench.","authors":["Austin C Baker","Raiyaan Abdullah","Daniel Zeev Yoffe","Shruti Vyas","Yogesh S Rawat"],"published":"2026-11-18T17:15:58Z","updated":"2026-11-18T17:15:58Z","abstract_url":"https://arxiv.org/abs/2611.24762v1","html_url":"https://arxiv.org/html/2611.24762v1","pdf_url":"https://arxiv.org/pdf/2611.24762v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":110338,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Recent Multimodal Large Language Models (MLLMs) have achieved strong performance on general video understanding benchmarks, yet their ability to reason about participant roles in aggressive interactions remains largely unexplored. Existing violence and crime...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24731v1","title":"HandWorldBench: A Unified Benchmark for Hand-Centric World Models","abstract":"Recent advances in world models are opening new possibilities for fine-grained embodied tasks, with hand-object interaction offering a particularly demanding setting. Modeling these interactions involves capturing how hand actions change objects and how the resulting states persist over time. Yet systematic evaluation tailored to these hand-centric capabilities remains underdeveloped. To address this gap, we introduce HandWorldBench, a unified benchmark that systematically evaluates hand-centric world models across human hands, simulated dexterous hands, and real dexterous hands along six dimensions: visual quality, hand fidelity, appearance consistency, instruction following, physical consistency, and temporal coherence. To construct the benchmark, we develop a data curation pipeline that extracts hand-object interaction clips and screens them for quality, yielding 20,500 high-quality egocentric clips from over 600 hours of footage. We then manually select 500 clips covering seven task families for evaluation. Benchmarking eleven models under a unified protocol reveals that stronger hand-pose control does not consistently translate into coherent object-state evolution and persistence or robust cross-embodiment performance, with several specialized hand-control models underperforming general-purpose text/image-to-video generators on dexterous-hand tasks.","authors":["Zhaolu Wang","Jiacheng Xu","Lihong Wang","Shuqing Wang","Jianjie Fang","Ziyou Wang","Xvyuan Liu","Rongze Tang","Yiding Ma","Xin Zhang","Jiawei Chen","Wei Wu","Chen Gao","Yong Li","Zhibo Chen"],"published":"2026-11-18T16:47:46Z","updated":"2026-11-18T16:47:46Z","abstract_url":"https://arxiv.org/abs/2611.24731v1","html_url":"https://arxiv.org/html/2611.24731v1","pdf_url":"https://arxiv.org/pdf/2611.24731v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":43377,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advances in world models are opening new possibilities for fine-grained embodied tasks, with hand-object interaction offering a particularly demanding setting. Modeling these interactions involves capturing how hand actions change objects and how the r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24723v1","title":"Multi-Band Galaxy Novel-View Synthesis with Radiative Gaussian Fields","abstract":"We propose a novel view synthesis tool for galaxies based on Gaussian Splatting (GS). Unlike RGB data, where GS has achieved success, galaxy observations consist of multi-band signals from a massive number of bodies, contain complex patterns of cross-band interactions, and capture light propagation in highly heterogeneous media. As a result, the underlying physical process poses great challenges in model representation and optimization, which have not been investigated in existing research. To this end, we propose a physically inspired Gaussian Splatting method, GalaxyGS, which is equipped with physically meaningful components that capture both the energy emission mechanism of different astronomical bodies and the light propagation between them. In the absence of directly comparable baseline methods, we adopt a wide range of possible alternative approaches. Comparisons conclusively demonstrate that GalaxyGS is better in accuracy and physical fidelity across datasets and metrics.","authors":["Yuzhe Wu","Jialin Zhu","Doğa Yılmaz","Daisuke Kawata","He Wang"],"published":"2026-11-18T16:41:49Z","updated":"2026-11-18T16:41:49Z","abstract_url":"https://arxiv.org/abs/2611.24723v1","html_url":"https://arxiv.org/html/2611.24723v1","pdf_url":"https://arxiv.org/pdf/2611.24723v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":54517,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：We propose a novel view synthesis tool for galaxies based on Gaussian Splatting (GS). Unlike RGB data, where GS has achieved success, galaxy observations consist of multi-band signals from a massive number of bodies, contain complex patterns of cross-band int...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24719v1","title":"DRIFT: Detachable Reasoning for Runtime-Flexible and Efficient End-to-End Driving","abstract":"The integration of vision-language models (VLMs) into end-to-end (E2E) autonomous driving has demonstrated strong potential by providing scene description and reasoning capabilities. However, VLMs are computationally expensive, and switching language reasoning on and off at runtime without hurting closed-loop performance has not been demonstrated, which hinders practical adoption. To address these issues, we propose DRIFT, an E2E autonomous driving framework that integrates a lightweight language model (LM) for visual question answering and action commentary. By efficiently projecting intermediate driving representations into the language embedding space, we demonstrate that a compact LM (<150M parameters) can achieve strong scene description and action commentary. Furthermore, we introduce a runtime-flexible planning module that is trained on surrogate reasoning features distilled from the LM and can be conditioned on either the LM or the surrogate reasoning features at inference. This design enables bypassing the LM entirely when required by deployment constraints, without sacrificing driving performance. With only 255M parameters, DRIFT reaches up to a Driving Score (DS) of 97.03 and a Success Rate of 89.39% (mean over three runs) on Bench2Drive by interleaving its LM and surrogate reasoning at a chosen reasoning rate. This is on par with the strongest non-language models while being far more compact than existing VLM-based models. DRIFT further achieves competitive results on the real-world NAVSIM and AlpaSim benchmarks at significantly lower computational cost than existing VLM-based approaches. Project page: https://drift-e2e.github.io/","authors":["Emad Aghajanzadeh","Bethany Anne Wong","Leonhard Kunze","Moritz Thoma","Maximilian Forstenhäusler","Nael Fasfous","Manoj Rohit Vemparala","Pierpaolo Mori","Christos Anagnostopoulos","Daniel Mueller-Gritschneder","Ulf Schlichtmann"],"published":"2026-11-18T16:40:13Z","updated":"2026-11-18T16:40:13Z","abstract_url":"https://arxiv.org/abs/2611.24719v1","html_url":"https://arxiv.org/html/2611.24719v1","pdf_url":"https://arxiv.org/pdf/2611.24719v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":57052,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：The integration of vision-language models (VLMs) into end-to-end (E2E) autonomous driving has demonstrated strong potential by providing scene description and reasoning capabilities. However, VLMs are computationally expensive, and switching language reasonin...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:23+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24706v1","title":"Can Omni-modal LLMs Understand Spoken Intentions?","abstract":"Omni-modal large language models (omni-modal LLMs) can respond to spoken requests directly through voice and video calls. Such requests rely on the scene shared by the user and the assistant, so the same utterance may call for different help or for no response. Most audio-visual benchmarks provide questions as separate text input, and interactive benchmarks mostly score a response as a whole. It thus remains unclear whether a model recognizes when the user is asking for help, and whether its reply meets the user's need once the request is recognized. We propose O-IN-Bench to evaluate how well omni-modal LLMs understand spoken intentions. A model watches a complete video with native speech and outputs one text response, or [SILENCE] when no response is needed. O-IN-Bench contains 1,000 Chinese and English samples in five categories and 16 subcategories. Contrastive pairs combine the same request with different scene conditions to test whether the response changes with the context. A sample-specific rubric judges language, intent, and content separately, and O-IN-Engine verifies each rubric against the video. Across 30 omni-modal model configurations, the best overall score is 59.6, achieved by Gemini3.7-Flash. Gemini3.7-Flash passes 74.4% of the intent judgments but only 42.6% of the content judgments. When the speech is a conversation between peers rather than a request to the assistant, even strong models often keep responding. When a reply must satisfy several people, the best score is only 25.9. These results indicate that recognizing a request and meeting its requirements are separate abilities, and O-IN-Bench measures each of them.","authors":["Zijie Xin","Tianyi Wang","Daoze Zhang","Jie Yang","Changli Tang","Qijie Wei","Fengyun Rao","Xirong Li"],"published":"2026-11-18T16:31:52Z","updated":"2026-11-18T16:31:52Z","abstract_url":"https://arxiv.org/abs/2611.24706v1","html_url":"https://arxiv.org/html/2611.24706v1","pdf_url":"https://arxiv.org/pdf/2611.24706v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":44873,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Omni-modal large language models (omni-modal LLMs) can respond to spoken requests directly through voice and video calls. Such requests rely on the scene shared by the user and the assistant, so the same utterance may call for different help or for no respons...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24696v1","title":"Improving Zero-shot 3D Semantic Mapping in Offroad with Geometric Priors","abstract":"Semantic 3D mapping is a powerful representation that enables platform agnostic mobile robot navigation in challenging offroad conditions. Current vision foundation models can accurately predict semantics zero-shot on structured scenes but performance is compromised in natural environments. On the other hand, 3D point clouds encode valuable information for discriminating semantics in scenarios where vision foundation models fail. In this work, we propose fitting a sphericity-elevation distribution for each semantic class to act as geometric anchor. Only the points with the most confident vision foundation model predictions are considered when fitting to produce high quality geometric prior distributions. The geometric prior is fused with the vision foundation model prediction to produce the final semantic mapping. The proposed prior improves SAM3 baseline by +6.3 in mIoU and +8.9 in accuracy on the RELLIS-3D dataset, and by +1.7 in mIoU and +2.1 in accuracy on the WildScenes dataset. The source code will be made public upon paper acceptance.","authors":["Eerik Alamikkotervo","Risto Ojala"],"published":"2026-11-18T16:23:05Z","updated":"2026-11-18T16:23:05Z","abstract_url":"https://arxiv.org/abs/2611.24696v1","html_url":"https://arxiv.org/html/2611.24696v1","pdf_url":"https://arxiv.org/pdf/2611.24696v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":38280,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Semantic 3D mapping is a powerful representation that enables platform agnostic mobile robot navigation in challenging offroad conditions. Current vision foundation models can accurately predict semantics zero-shot on structured scenes but performance is comp...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24681v1","title":"DrawScore: Evaluating Generated CAD Models against Engineering Drawings","abstract":"Automatic CAD generation is commonly evaluated with volumetric IoU, Chamfer Distance, and surface F-score, which barely penalize local errors that occupy only a small fraction of a part's volume or surface area, such as a misplaced hole or a slot on the wrong face, even though such errors are critical to manufacturing. We formalize these metrics in a unified integral form and show that the weight of a local error decays as the $(k+q)$-th power of its size, where $k$ is the dimension of the integration domain and $q$ is determined by the penalty function. Guided by this analysis, we propose DrawScore, which projects both models into three orthographic views with visible and hidden lines, as in engineering drawings, and applies a saturating penalty along the projected curves, so that the weight of a local error decays only linearly. Controlled experiments confirm the predicted decay orders, and on outputs of existing CAD generation agents, DrawScore exposes errors in outputs that IoU rates as nearly perfect. DrawScore further improves generation as a reinforcement learning reward and, for CAD generation from engineering drawings, serves as a test-time verifier without 3D ground truth or an additional reward model. Our code is available at https://github.com/UESTC-Simon/DrawScore.","authors":["Haorui Chen","Shiteng Lu","Zhanyu Guo","Zaixi Li","Yunhe Ni","Yaosong Du","Yichen Xiang","Xiande Huang","Rui Huang"],"published":"2026-11-18T16:14:30Z","updated":"2026-11-18T16:14:30Z","abstract_url":"https://arxiv.org/abs/2611.24681v1","html_url":"https://arxiv.org/html/2611.24681v1","pdf_url":"https://arxiv.org/pdf/2611.24681v1.pdf","matched_keywords":["3d","agent"],"source_used":"html","source_text_chars":47609,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, agent 相关；摘要显示其主要贡献为：Automatic CAD generation is commonly evaluated with volumetric IoU, Chamfer Distance, and surface F-score, which barely penalize local errors that occupy only a small fraction of a part's volume or surface area, such as a misplaced hole or a slot on the wrong...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24651v1","title":"Piccolo: Co-Evolving Decision Models and Data through Recursive Self-Improvement","abstract":"We present Piccolo, a family of multimodal decision models (0.8B to 27B) that coevolves model capabilities and training data via Agentic Data Engineering and recursive self-improvement (RSI). The models predict probabilities over candidate answers for general-purpose text and visual judgments, agent harnesses, data workflows, and interactive games. Piccolo-27B tops the Decision Index Vision Full leaderboard with a score of 75.59, while Piccolo-9B and Piccolo-4B achieve 68.35 and 67.46, respectively. All three rank first on the Private benchmark in their respective model-size categories. Research agents analyze model behavior, construct training data, conduct experiments, and use the results to refine subsequent proposals. Semantic slices and a shared research memory connect these actions across the model family's development. With training recipes comprising hundreds of thousands of examples, data selection and feedback-driven refinement are central to the self-improvement process. Our large-scale RSI exploration yields three counter-intuitive insights for decision-model development: (1) Backbone-recipe co-adaptation outweighs raw model recency: earlier backbones can surpass newer generations on visual tasks under identical recipes; (2) Targeted data curation enables 4B-9B models to rival 27B baselines on specialized workflows; and (3) Continuous loss reduction can decouple from and even degrade discrete decision accuracy. Together with the released weights and tools from the Data-Juicer and AgentScope ecosystems, Piccolo provides an actionable blueprint for building frontier decision models and scaling data-driven RSI.","authors":["Zhenqing Ling","Qirui Jiao","Daoyuan Chen","Cheng Chen","Xinji Mai","Haowen Gao","Zhuo Zhang","Xuchen Pan","Mengsu Ding","Jiaji Deng","Yuexiang Xie","Xiaoming Qin","Weirui Kuang","Zhaoyang Liu","Yaliang Li","Bolin Ding","Jingren Zhou"],"published":"2026-11-18T15:53:39Z","updated":"2026-11-18T15:53:39Z","abstract_url":"https://arxiv.org/abs/2611.24651v1","html_url":"https://arxiv.org/html/2611.24651v1","pdf_url":"https://arxiv.org/pdf/2611.24651v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":76234,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：We present Piccolo, a family of multimodal decision models (0.8B to 27B) that coevolves model capabilities and training data via Agentic Data Engineering and recursive self-improvement (RSI). The models predict probabilities over candidate answers for general...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24643v1","title":"AggCLIP: Aggregating CLIP for Zero-Shot Multimodal Anomaly Detection","abstract":"Zero-Shot Multimodal Anomaly Detection (ZSMAD) aims to identify both appearance and geometric defects in novel categories without relying on target-specific training data, making it especially valuable in real-world scenarios constrained by data scarcity, privacy concerns, or high annotation costs. While recent approaches successfully adapt vision-language models like CLIP to achieve this open-vocabulary generalization, they still face significant challenges: (i) severe geometric information loss during 3D-to-2D point cloud rendering; (ii) spatially noisy 2D feature maps produced by raw CLIP patch embeddings, compounded by shallow late-stage modality fusion; and (iii) severe cross-modal semantic misalignment due to decoupled processing streams. To address these limitations, we propose AggCLIP, a novel framework that adapts frozen CLIP representations for ZSMAD by explicitly incorporating local geometric structure and visual spatial context. Specifically, to accurately localize fine-grained defects, we design a Geometry-Aware Spatial Aggregation (GSA) module that refines back-projected 3D point features via density-adaptive neighborhood weighting, alongside a Context-Aware Spatial Aggregation (CSA) module that smooths multi-scale 2D patch embeddings using a lightweight trainable adapter. Furthermore, to prevent semantic drift between modalities, we introduce a Dual-Stream Prompt Contrastive (DSPC) loss, which aligns the abstract concepts of normality and abnormality across the point cloud and RGB streams. Extensive experiments demonstrate that the proposed AggCLIP framework achieves state-of-the-art performance on the MVTec 3D-AD and Eyecandies benchmarks under both one-vs-rest and cross-dataset zero-shot settings, notably surpassing the strongest competitive methods by up to 2.9% in pixel-level AUPRO.","authors":["Zhi Li","Hanyu Wang","Fei Shen","Zhengtao Zhang"],"published":"2026-11-18T15:49:05Z","updated":"2026-11-18T15:49:05Z","abstract_url":"https://arxiv.org/abs/2611.24643v1","html_url":"https://arxiv.org/html/2611.24643v1","pdf_url":"https://arxiv.org/pdf/2611.24643v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"html","source_text_chars":62762,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal 相关；摘要显示其主要贡献为：Zero-Shot Multimodal Anomaly Detection (ZSMAD) aims to identify both appearance and geometric defects in novel categories without relying on target-specific training data, making it especially valuable in real-world scenarios constrained by data scarcity, pri...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-19T08:18:24+00:00","status":"fallback"},"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24633v1","title":"H3Remover: Reinforcing Video Object Removal without Paired Data","abstract":"Pretrained video editors possess rich removal and completion priors, yet may retain targets or alter unrelated content. We present H3Remover, which reinforces MiniMax-H3 Base Ref2VA for video object removal without paired object-free training targets. To discourage superficial edits such as recoloring, a target-removal reward favors calibrated depth changes consistent with revealing farther content. To limit unintended scene changes, a background-geometry reward encourages preservation of relative depth ordering. To preserve background appearance without retaining unwanted shadows or reflections, an appearance reward constrains RGB changes in source-derived protected regions while exempting targets and estimated effects. Frozen HPSv3 complements these constraints with perceptual-quality feedback for synthesized content. Evaluation regions remain fixed across candidates, and DiffusionART optimizes LoRA adapters with the backbone frozen. Experiments show substantial reconstruction gains over original H3, with qualitative comparisons demonstrating more effective object removal and better preservation of surrounding scene content.","authors":["Kangjie Chen","Xiangyu Li","Jinhao Deng","Dongbin Zhang","Chaoda Zheng","Shijia Chen","Yuqi Zhang","Choo Sin Wai","Boyi Sun","Puyi Wang","Yu Zhang","Xianming Liu","Boyang Wang"],"published":"2026-11-18T15:45:18Z","updated":"2026-11-18T15:45:18Z","abstract_url":"https://arxiv.org/abs/2611.24633v1","html_url":"https://arxiv.org/html/2611.24633v1","pdf_url":"https://arxiv.org/pdf/2611.24633v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24616v1","title":"EgoJev: Finding Evidence in Egocentric Video by Reading VLM Decisions","abstract":"Questions about long egocentric video often depend on one brief moment, such as the second a hand puts an object down. A vision-language model (VLM) that sees a few evenly spaced frames usually misses it. Training-free methods rank frames with a separate image-text model or ask the VLM to write a time. In a controlled test, the VLM itself locates the moment better when it chooses among labeled frames, and we read this choice from its output distribution. With the same candidates, this choice lands on the evidence more often than image-text scores or a written time span, and it compares all candidates in one decision. Based on this finding, we propose EgoJev, a training-free frame selector for wearable assistants. EgoJev reads where the evidence is from labeled thumbnails and looks again at the windows it points to. It places its few answer frames at the quantiles of the resulting distribution. One frozen VLM selects, answers and returns the evidence time, with no second model. A wearable device can encode its coarse thumbnails while it records. With Qwen3.5-4B and 8 answer frames, EgoJev raises QAEgo4D accuracy from 51.2% with uniform sampling to 62.0%, and it outperforms recent training-free frame selectors on QAEgo4D and MyEgo. A single-level version runs on a Mac and an iPhone.","authors":["Chunggi Lee","Hanspeter Pfister"],"published":"2026-11-18T15:34:10Z","updated":"2026-11-18T15:34:10Z","abstract_url":"https://arxiv.org/abs/2611.24616v1","html_url":"https://arxiv.org/html/2611.24616v1","pdf_url":"https://arxiv.org/pdf/2611.24616v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24579v1","title":"ALIVE: Bring Foundation Features to Life with Events","abstract":"Visual foundation models provide powerful representations for diverse tasks, but their features become stale as visual content changes between image observations. Refreshing them requires new frames and repeated runs of a computationally expensive image encoder. We introduce ALIVE, an event-based method that incrementally updates native foundation model features between image observations. Given an anchor image, ALIVE uses subsequent events to transport and correct existing multi-layer features extracted by a frozen DINOv3 encoder. Its lightweight updater is trained end-to-end using only synthetic data, without downstream task supervision, and transfers directly to real-world event streams without any adaptation. Across three real-world datasets and five task-dataset settings spanning object detection, semantic segmentation, and depth estimation, ALIVE outperforms all evaluated event-based methods in every metric. On DSEC, when the anchor frame is 200,ms old, ALIVE improves over anchor-image predictions by 30.9,mAP in detection, 11.6,mIoU in segmentation, and 15.9% in depth AbsRel. Compared with image re-encoding, ALIVE reduces FLOPs by 82.4% and latency by a factor of 2.5.","authors":["Rong Zou","Haiqing Hao","Davide Scaramuzza"],"published":"2026-11-18T15:10:48Z","updated":"2026-11-18T15:10:48Z","abstract_url":"https://arxiv.org/abs/2611.24579v1","html_url":"https://arxiv.org/html/2611.24579v1","pdf_url":"https://arxiv.org/pdf/2611.24579v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24565v1","title":"Beyond Appearance: Evidence-Guided Programmatic 3D Scene Reconstruction with Agentic Lighting Reasoning","abstract":"Image-to-code methods for 3D scene reconstruction produce executable code that generates editable digital content and supports visual simulation. However, existing methods primarily rely on appearance similarity, which provides limited guidance for distinguishing errors in geometry, materials, and illumination. Light shapes scene appearance through its interactions with geometry and materials, influencing shading, cast shadows, and reflections. We therefore present LightHarness, a VLM-based agentic framework that incorporates explicit lighting reasoning into iterative scene reconstruction. To be specific, we leverage complementary geometric, intrinsic, and illumination cues to jointly refine scene structure and appearance, and propose Lighting Reasoning Memory to maintain light-source hypotheses, which supports evidence, and revision history throughout iterations. Together, they support reasoning about partially visible and unseen sources, with evidence-guided verification directing subsequent revisions. Our framework reconstructs explicit scenes through coherent reasoning about geometry, materials, and illumination without additional training or differentiable rendering. Extensive experiments demonstrate superior image-to-code reconstruction accuracy under challenging shadows and complex illumination, further supporting downstream scene editing, object insertion, and versatile relighting.","authors":["Zeting Luo","Yifan Li","Shuai Yang"],"published":"2026-11-18T15:01:21Z","updated":"2026-11-18T15:01:21Z","abstract_url":"https://arxiv.org/abs/2611.24565v1","html_url":"https://arxiv.org/html/2611.24565v1","pdf_url":"https://arxiv.org/pdf/2611.24565v1.pdf","matched_keywords":["3d","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24558v1","title":"SCR: Detecting Backdoor-Poisoned Samples through Clean-Reference Residuals","abstract":"Deep neural networks are vulnerable to backdoor attacks, in which adversaries manipulate model predictions by injecting poisoned samples into training data. Detecting these samples remains challenging because legitimate semantic variation can obscure poisoning-related signals in learned representations. Consequently, class-level statistics used by existing detectors may flag benign feature deviations while overlooking poisoned samples that blend into the class distribution. In this paper, we propose Semantic Counterfactual Residualization (SCR), which uses a small set of clean reference samples to account for benign variation through sample-specific feature reconstruction. SCR identifies poisoned samples by detecting coherent deviations from these clean baselines, without requiring prior knowledge of the attacks. We evaluate SCR through experiments covering twelve dirty-label and clean-label attacks across CIFAR-10, CIFAR-100, and Tiny ImageNet. With a small clean-reference set, SCR achieves attack-averaged true positive rates above 99.5\\% and false positive rates below 2\\% on each dataset, outperforming eight representative detection baselines in macro-TPR.","authors":["Yi Yang","Jinyang Huang","Feng-Qi Cui","Yu-Tong Guo","Sirui Zhao","Haiming Jin","Weihua Li","Quan Bai","Meng Li"],"published":"2026-11-18T14:57:37Z","updated":"2026-11-18T14:57:37Z","abstract_url":"https://arxiv.org/abs/2611.24558v1","html_url":"https://arxiv.org/html/2611.24558v1","pdf_url":"https://arxiv.org/pdf/2611.24558v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24541v1","title":"Fuse Before Reconstruct: A Novel Reconstruction Paradigm for Multimodal Industrial Anomaly Detection","abstract":"Industrial anomaly detection plays a pivotal role in precision manufacturing, where joint analysis of multimodal data emerges as a critical approach to enhance detection accuracy. Feature reconstruction, a dominant paradigm for such joint analysis, is primarily implemented through intra-modal and cross-modal methods, both of which are plagued by significant limitations. Intra-modal reconstruction neglects complementary cross-modal information, while its cross-modal counterpart is prone to projection errors and ambiguous one-to-many mappings (e.g., same textures mapping to multiple geometries), leading to detection failures. To address these limitations, we propose a novel feature reconstruction paradigm, Fuse Before Reconstruct (FBR), which first fuses multimodal features and then performs reconstruction for anomaly detection. Firstly, we propose a bidirectional cross-modal attention mechanism to achieve deep feature complementarity between image and point cloud features, mitigating projection bias through channel alignment and dynamic spatial prior integration. Besides, a learnable pixel-wise gated fusion strategy is adopted to preserve multi-modal structural consistency while optimizing local feature combination. Finally, dual-path collaborative reconstruction is implemented to recover original modal features from the fused representations, where cross-modal consistency constraints effectively eliminate mapping ambiguities. Extensive experiments show that FBR achieves 98.3% I-AUROC on MVTec 3D-AD and 92.6% I-AUROC on Eyecandies, surpassing previous state-of-the-art methods by +2.9% and +4.1%, respectively.","authors":["Zhi Li","Hanyu Wang","Qiyu Chen","Fei Shen","Zhengtao Zhang"],"published":"2026-11-18T14:49:34Z","updated":"2026-11-18T14:49:34Z","abstract_url":"https://arxiv.org/abs/2611.24541v1","html_url":"https://arxiv.org/html/2611.24541v1","pdf_url":"https://arxiv.org/pdf/2611.24541v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24524v1","title":"SCRiD: Spatial and Contextual References for Generalizable AI-Generated Video Detection","abstract":"Generalizable AI-generated video detection remains challenging because natural motion and content variations can resemble synthesis artifacts, making isolated video discrepancies unreliable indicators of authenticity. To address this challenge, we propose Spatial and Contextual Reference-informed Detection (SCRiD), a framework that interprets video variations through complementary spatial and contextual references. Specifically, we introduce Matched-Coordinate Residual Response (MCR) to characterize temporal residual associations under motion and coordinate references with matched subpixel sampling conditions. We further develop Real-Conditioned Score Adaptation (RCSA), which learns a content-conditioned denoising reference from authentic videos and probes its responses across multiple noise scales and quality views to guide feature adaptation. To integrate these complementary sources of evidence, we design Reversible Evidence Exchange (REE) to enable information exchange through reversible symplectic updates. We train SCRiD using synthetic videos from only 4 generators and evaluate it across 88 generator or task subsets spanning 6 benchmarks. Our method achieves average ACC and AP of 72.72% and 74.23%, respectively, outperforming the strongest baseline by 3.24 and 0.81 percentage points.Ablation and robustness experiments further validate the effectiveness of the proposed components and the stability of SCRiD under common post-processing operations.","authors":["Hao Tan","Zekai Zuo","Boyang Chen","Jinghui Qin"],"published":"2026-11-18T14:39:20Z","updated":"2026-11-18T14:39:20Z","abstract_url":"https://arxiv.org/abs/2611.24524v1","html_url":"https://arxiv.org/html/2611.24524v1","pdf_url":"https://arxiv.org/pdf/2611.24524v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24521v1","title":"RAID: Representation Autoencoder for Intrinsic Decomposition","abstract":"Single-image intrinsic decomposition is an inherently ill-posed problem, requiring the disentanglement of strongly coupled appearance factors from a single RGB observation. Recent methods address this ambiguity with diffusion priors, at the cost of large, iterative, and often stochastic models. We show that accurate decomposition does not require a large generative model. Our key idea is to decouple reconstruction from decomposition on top of a strong pretrained representation. First, an $X \\rightarrow X$ teacher learns to reconstruct each intrinsic map from DINOv3 features using a shared decoder, without paired RGB-to-intrinsic supervision. Then, a DINOv3-based student predicts the corresponding teacher representations from RGB through lightweight, modality-specific projections, enabling training on partially annotated datasets and predicting all intrinsics in a single forward pass. \\textbf{RAID}, predicts intrinsic properties in the structured latent space, enabling a compact 165M-parameter model, 100x faster than diffusion-based methods. Despite its compact size, it achieves competitive or superior decomposition quality, with improved robustness to input resolution. Additionally, our learned projections yield interpretable, modality-specific feature spaces.","authors":["Claudia Cuttano","Tamy Boubekeur","Elena Garces","Giuseppe Vecchio"],"published":"2026-11-18T14:38:46Z","updated":"2026-11-18T14:38:46Z","abstract_url":"https://arxiv.org/abs/2611.24521v1","html_url":"https://arxiv.org/html/2611.24521v1","pdf_url":"https://arxiv.org/pdf/2611.24521v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24512v1","title":"Comparing Each Generation with Independent Siblings Gives Video World Model Post-Training a Proper Objective for Outcome Frequencies","abstract":"Video world models are used as simulators, so when a first frame leaves several physical outcomes open, repeated generations should produce each outcome as often as it occurs in the data. Physics post-training scores every generation against the single recorded future of its history, which makes single videos more faithful, but the expected score is linear in the model distribution and is maximized by always producing the most likely outcome. The log-likelihood of the recorded outcome is maximized by the data distribution, and its gradient weights agreement with the record by the inverse of how often the model produces the generated outcome, a frequency that other generations of the same history with independent noise, its siblings, can estimate. To train with this weight from a finite group, we propose SibPO, which performs Sibling-paired Policy Optimization: siblings estimate a truncated inverse-frequency weight for agreement with the record, and a second term subtracts the same weight times the agreement with the siblings, which makes the expected objective a strictly proper divergence over outcome cells at every group size. On PisaBench, SibPO lowers the KS distance to simulated landing times by 9.1-10.2% relative to the strongest method outside its reward family on three of four video models without degrading single videos, and it lowers the error of estimated robot policy success rates by 13%.","authors":["Xin Li","Yiwen Chen"],"published":"2026-11-18T14:34:06Z","updated":"2026-11-18T14:34:06Z","abstract_url":"https://arxiv.org/abs/2611.24512v1","html_url":"https://arxiv.org/html/2611.24512v1","pdf_url":"https://arxiv.org/pdf/2611.24512v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24494v1","title":"RECLAIM: Robot-Vision-Informed Adversarial Patch Defense via Embodied Attention Feedback","abstract":"Vision-language-action policies control embodied agents through a perception-action loop grounded in physical interaction, where adversarial patches can corrupt action predictions and thereby alter subsequent observations. To mitigate these threats, many existing defenses rely on policy adaptation or auxiliary models, but require additional training or inference. We introduce RECLAIM, a training-free, inference-time defense that uses a frozen VLA's own attention response to local visual interventions to guide purification during closed-loop embodied manipulation. Our key insight is that attention changes induced by local edits provide feedback for choosing where and how to purify as the robot interacts with its environment. RECLAIM combines this feedback with robot geometry to refine patch localization and select local treatments, then revalidates them as the agent's embodied actions change the observed scene. We evaluate RECLAIM against patches generated by four adversarial attack methods across multiple manipulation task suites under frozen VLA control. Under adversarial patch attacks, RECLAIM succeeds in at least one rollout on 95% of the evaluated tasks and raises rollout success on LIBERO-Object from 0% without defense to 70.0%. Its mean decision time is only 548.9 ms per control step. These results highlight policy-guided visual purification as an effective approach to defending embodied agents against adversarial patches and recovering closed-loop task execution.","authors":["Jiayou Zhu","Peng Guo","Litian Zhang","Xinze Shi","Yuting Zhang","Zelong Yu","Yize Tian","Jirong Liu","Zifeng Kang"],"published":"2026-11-18T14:24:10Z","updated":"2026-11-18T14:24:10Z","abstract_url":"https://arxiv.org/abs/2611.24494v1","html_url":"https://arxiv.org/html/2611.24494v1","pdf_url":"https://arxiv.org/pdf/2611.24494v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24479v1","title":"Every Query Routes Itself: Accelerating Video Diffusion Transformers with Per-Query Routed Sparse Attention","abstract":"Self-attention over long token sequences dominates the inference cost of video diffusion transformers. Clustering-based sparse attention clusters both queries and keys and lets all queries in a cluster share one selection of key clusters. We show that this sharing limits accuracy: with key clusters and density fixed, attention grows more accurate as the query clusters are refined, and is most accurate when each query selects on its own, which needs no query clustering at all. We therefore propose Per-Query Routed Sparse Attention (PQRS), a training-free method that clusters only keys, lets each query select its own key clusters, and compensates for the unselected ones with their centroids. Per-query selections leave no query tile with a shared key list, so PQRS traverses key clusters instead of queries, buckets queries with identical selections into dense tasks, and merges their partial results in one pass under a fixed softmax offset carried from the previous denoising step. On four text-to-video and image-to-video models from the Wan and HunyuanVideo families, PQRS is the fastest of all the sparse attention methods we evaluate and the closest to the dense output, reaching $28.9$ dB PSNR on Wan2.1-T2V and $35.4$ dB on HunyuanVideo at $1.66$--$2.10\\times$ end-to-end speedup.","authors":["Zhen Huang","Shuwei Li","Ruizhe Yao","Xinrui Chen","Danyi Liu","Haoyuan Liang","Zhiyu Ye","Qiuyan Sun","Bingwei Chen","Yiyuan Li","Xu Zhou","Haohuan Fu"],"published":"2026-11-18T14:17:16Z","updated":"2026-11-18T14:17:16Z","abstract_url":"https://arxiv.org/abs/2611.24479v1","html_url":"https://arxiv.org/html/2611.24479v1","pdf_url":"https://arxiv.org/pdf/2611.24479v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24457v1","title":"ShoWorld: Shape-Faithful Multi-Hypothesis Occupancy World Model","abstract":"Occupancy world models struggle to forecast moving objects due to motion uncertainty and shape distortion. A single trajectory can average plausible futures into an implausible path, and repeated re-voxelization can erode or inflate object shape even under correct motion. We introduce ShoWorld to address these challenges through separate motion and shape representations. The motion forecaster predicts probabilistic trajectories conditioned on scene layout, nearby agents and the future ego trajectory. Each hypothesis is rendered into occupancy and fused according to its probability to retain alternative futures. The shape component predicts sub-voxel points with occupancy probabilities and offsets from local geometry. These points move rigidly with the object, and voxel occupancy follows the probability that at least one occupied point falls within it. This representation reduces shape distortion under motion. ShoWorld achieves state-of-the-art results on Occ3D-nuScenes. With ground-truth occupancy and ego trajectory, it improves mIoU and IoU by 6.56 and 9.16 points overall and by 6.06 and 5.53 points on dynamic classes.","authors":["Zhiqiang Yan","Guangfa Wang","Yuan Wu","Jian Yang","Gim Hee Lee"],"published":"2026-11-18T14:02:31Z","updated":"2026-11-18T14:02:31Z","abstract_url":"https://arxiv.org/abs/2611.24457v1","html_url":"https://arxiv.org/html/2611.24457v1","pdf_url":"https://arxiv.org/pdf/2611.24457v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24451v1","title":"EviScope: Evidence-Conditioned Sampling for Long-Range 3D Detection","abstract":"Query-based camera-radar detectors choose where and over which frames each object query samples from the query's position or feature. We test whether radar evidence around the query should also set these choices at the 150 m range of MAN TruckScenes, where recall differs across object-level radar-return counts within every range band. EviScope is a minimal test: the current frame's returns form a non-learned bird's-eye evidence field, which each query reads at its decoded centre to scale its radial sampling extent and to weight eight frames. It adds 5,450 parameters (0.009%) to RaCFormer, with no latency increase in our timing. Our module-free recipe exceeds the published TruckScenes mAP (25.9 over seven runs against 24.1), so we measure the module only against its own baseline at matched seeds. The evidence a query reads rises with its object's return count (Spearman 0.51) but captures zero-return objects only in part, and the learned radius tracks it ($ρ\\approx-0.91$ in four runs). Over seven four-epoch pairs the module changes NDS by $+0.31\\pm0.36$ and mAP by $-0.27\\pm0.22$ (mean $\\pm$ SE). Against a geometry-only conditioner with the same parameter count, trained at three matched seeds, it is higher by $+1.25\\pm0.72$ NDS and $+0.87\\pm0.21$ mAP, on mAP in every pair, and the control's mean NDS is near the baseline's. An exploratory far-range gain failed an internally pre-specified held-out test, and large inference-time substitution penalties also occur without query-local evidence: neither learned allocation nor inference-time dependence substitutes for matched end-to-end comparisons.","authors":["Mingyang Lyu","Yinqian Sun","Gongce Cao","Chujie Tang","Yuhao Zhang","Lu Jia","Qian Zhang","Bo Wang","Pin Lyu"],"published":"2026-11-18T14:00:09Z","updated":"2026-11-18T14:00:09Z","abstract_url":"https://arxiv.org/abs/2611.24451v1","html_url":"https://arxiv.org/html/2611.24451v1","pdf_url":"https://arxiv.org/pdf/2611.24451v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24443v1","title":"NativeSeg: Native Vision Language Segmentation of 3D Computed Tomography via Spatial Visual Tokens and Verified Local Zoom","abstract":"Text prompted 3D computed tomography (CT) segmentation requires both full slice context and fine boundary precision across volumes where over $80\\%$ of organ prompted slices lack the queried target. Existing medical vision language models (VLMs) are largely non native segmenters: they delegate pixel delineation outside the VLM by compressing reasoning into a 1D [SEG] vector for an external Segment Anything Model (SAM) decoder, quantizing masks into lossy discrete codebooks, or issuing box prompts to stateless external SAM tools without empty slice screening or spatial state memory. We introduce NativeSeg, a native vision language segmentation framework on Low Rank Adaptation (LoRA) adapted Qwen3.8-27B that performs dense mask decoding, volumetric triage, spatial error self diagnosis, and multiround local zoom directly over the VLM's 2D spatial visual tokens without external SAM decoders. NativeSeg decodes confidence maps from upper layer 2D spatial tokens fused with a five slice U-Net pathway, halts at zero zooms on $>91\\%$ of standalone evaluations via a native presence gate (<pres>), localizes uncertain boundaries via a 20 cell multiscale error gate (<err>), and accepts zoomed updates only when predicted error decreases. Trained solely on adult CT, NativeSeg improves Round $0$ DSC by $+19.81$ and $+7.04$ points over discrete codebook and 1D [SEG] readouts on the identical backbone, reaches $86.81\\%$ adult and $87.04\\%$ zero shot pediatric DSC, and safely refines 2D nnU-Net ($89.52\\%$ adult; $86.86\\%$ pediatric), 3D SegVol ($86.81\\%$), and 3D VoxTell ($89.85\\%$).","authors":["Chengqian Ma","Gaole Dai","Zijie Meng","Weixuan Jin","Yijie Du","Yuexiao Ma","Xiawu Zheng","Fei Chao"],"published":"2026-11-18T13:56:12Z","updated":"2026-11-18T13:56:12Z","abstract_url":"https://arxiv.org/abs/2611.24443v1","html_url":"https://arxiv.org/html/2611.24443v1","pdf_url":"https://arxiv.org/pdf/2611.24443v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24433v1","title":"MLIE-CoT: Chain-of-Thought Reasoning via Multi-Level Image Editing","abstract":"Chain-of-thought (CoT) reasoning has proven effective in improving the reasoning abilities of large language models by breaking complex tasks into step-by-step solutions. In recent years, researchers have attempted to extend CoT reasoning to visual generative models to improve their ability to handle complex tasks. However, existing CoT methods for text-to-image generation still rely mainly on textual reasoning and therefore cannot fully use and preserve the correct semantic information already present in an image, as even the most detailed language cannot capture all visual information. With advances in image generation, models such as FLUX and BAGEL can generate images conditioned on visual inputs. Recent work has attempted to carry images forward as context in the chain of thought, but this introduces another limitation: unsuitable earlier images can strongly interfere with the model, while repeated whole-image regeneration introduces new hallucinations at each round and causes them to accumulate. To address these issues, we propose MLIE-CoT, a visual chain-of-thought framework based on multi-level image editing. MLIE-CoT learns to select the repair granularity from three levels, preserving correct semantics whenever possible during reasoning while reducing the effect of incorrect content. To improve the ability of multimodal models to route errors of different severity to appropriate repair levels, we construct an image-repair dataset covering different error cases and use it to train a repair-level router. Extensive experiments demonstrate that MLIE-CoT significantly outperforms both its base models and methods using fixed repair strategies, producing clear improvements across multiple benchmarks.","authors":["Baichuan Yang","Dongyuan Xu","Zhao Yang","Yong Liu","Bing Su"],"published":"2026-11-18T13:49:34Z","updated":"2026-11-18T13:49:34Z","abstract_url":"https://arxiv.org/abs/2611.24433v1","html_url":"https://arxiv.org/html/2611.24433v1","pdf_url":"https://arxiv.org/pdf/2611.24433v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24423v1","title":"Probing Physics in Motion Diffusion Models Against Their Own Estimate","abstract":"Recent studies report that video diffusion models \"know more than they show\": physical properties decode better from their activations than from their inputs or outputs. But a diffusion model computes its clean-sample estimate from those same activations, so such a comparison measures how easily a readout extracts the information. Whether the model hides anything is a separate question. We set out to find hidden physical knowledge in kinematic text-to-motion diffusion models, where the physics of every intermediate estimate can be computed exactly, and recorded every layer along the sampling trajectories of MDM (two checkpoints) and MotionDiffuse. Against the usual baselines the layers do look ahead of the model's own estimate on balance and flight. With every readout tuned the same way, the estimate closes the gap: for balance and flight, adding a layer gains at most 0.01, a size that a positive control shows we would detect. The fall rate of jumps is the one clear exception. Early in denoising, MDM's layers add about 0.08 in $R^2$ (up to 0.11 in a refit) that the estimate does not yet show, and the gain fades as sampling proceeds; on MotionDiffuse it is small and not robust. The estimate also flags floating samples without training, but aborting them saves under a tenth of the compute. In a video model, plausibility that linear probes miss in Wan 2.1's clean latent becomes readable after one fixed nonlinearity.","authors":["Saeed Ghorbani"],"published":"2026-11-18T13:44:03Z","updated":"2026-11-18T13:44:03Z","abstract_url":"https://arxiv.org/abs/2611.24423v1","html_url":"https://arxiv.org/html/2611.24423v1","pdf_url":"https://arxiv.org/pdf/2611.24423v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24422v1","title":"Resolution as Attention for Efficient Agent Memory Perception","abstract":"LLM-based agents accumulate extensive interaction histories when solving complex, long-horizon tasks, making efficient memory management critical to their performance and scalability. While existing memory management methods primarily focus on what to retain or retrieve, they often overlook how much perceptual detail should be allocated to individual past interactions. We posit that effective agent memory depends not only on the information preserved, but also on the granularity at which each past interaction is perceived. Motivated by this insight, we propose Resolution as Attention (RAA), a memory perception mechanism that uses visual resolution as a means of attention allocation across interaction histories. RAA renders past interactions as images and dynamically adjusts their resolution at every step according to their relevance to the agent's upcoming decision, preserving fine-grained information for critical interactions while reducing visual-token consumption for less relevant ones. To adaptively determine the perceptual fidelity of each interaction, we train a lightweight relevance estimator with teacher-model guidance and further optimize it to preserve the agent's decision consistency at a reduced visual-token cost. Experiments across multiple tasks and backbones show that RAA reduces token consumption by over 50% without compromising task performance. Moreover, RAA can be integrated as a plug-in perception layer with existing memory management methods, yielding further token savings and revealing adaptive perception as a complementary dimension of agent memory.","authors":["Siqi Xiang","Zhipeng Xu","Shengrui Liu","Zulong Chen","Chunyan Miao","Shijian Lu"],"published":"2026-11-18T13:43:16Z","updated":"2026-11-18T13:43:16Z","abstract_url":"https://arxiv.org/abs/2611.24422v1","html_url":"https://arxiv.org/html/2611.24422v1","pdf_url":"https://arxiv.org/pdf/2611.24422v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24419v1","title":"PhysResponse: Probing the Physics of Video Generation with Controlled Interventions","abstract":"Video generation models are increasingly viewed as world simulators, which requires not only plausible motion but dynamics that respond correctly to specified physical parameters. Existing models, datasets and benchmarks, however, largely target physical plausibility, leaving this physical parameter responsiveness insufficiently explored. We introduce PhysResponse, a benchmark that measures it at two levels: scene-conditioned simulator inversion recovers the effective gravity, friction and initial speed of generated motion, and event evaluation tests outcomes near and across critical transitions. Evaluating ten image-to-video models, we find that even the lowest parameter errors exceed those of physically correct videos by over an order of magnitude, that models rarely reproduce both outcomes of a transition pair, and that the two levels expose complementary failures that visual metrics such as PSNR miss. To supply the missing training signal, we construct 72,000 simulated videos of 20 multi-object interaction types with controlled parameters; fine-tuning on them lowers parameter errors, even on held-out interaction types, and transfers to real videos and an external physics benchmark. Continued training with a numerical encoder further lowers all three errors on held-out types. PhysResponse provides a foundation for world simulators that follow physical conditions, not just appearances.","authors":["Yuhan Li","Shuran Zhang","Haixin Tian","Baonuo Rao","Weipeng Li","Yujia Hou","Zhenyu Wang","Zijun Wang","Luoyang Lin","Lijing Luo","Jiehui Huang","Kaiyuan Yang","Jingbin Tan","Panwen Hu","Xiaodan Liang"],"published":"2026-11-18T13:42:16Z","updated":"2026-11-18T13:42:16Z","abstract_url":"https://arxiv.org/abs/2611.24419v1","html_url":"https://arxiv.org/html/2611.24419v1","pdf_url":"https://arxiv.org/pdf/2611.24419v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24410v1","title":"Why Multi-Source Audio Fails to Compose: A Geometric Diagnosis and Its Remedy","abstract":"Multi-source audio-to-image generation exhibits consistent compositional failures when audio tokens occupy geometrically displaced, semantically unanchored positions in the CLIP text-token space, where the diffusion U-Net lacks the prior to reliably attend to them or ground them in distinct spatial regions. We formalize this as the geometric displacement phenomenon and expose it through a two-level clustering analysis comparing BEATs and CLAP embeddings at the raw encoder and projected CLIP token levels. Three geometric properties emerge as important: intra-class compactness, angular alignment with the CLIP text manifold, and inter-token spatial separation. We show that CLAP, whose contrastive language-audio pretraining aligns embeddings with natural language semantics, substantially outperforms BEATs on all three properties, improving the silhouette score by more than 3x and the Audio-Image Content score as well. Building on this analysis, we introduce a multi-token extension that requires no diffusion-backbone retraining and assigns each audio source to a distinct placeholder token in the CLIP tokenizer, complemented by a mixed inference-time objective that combines Attend-and-Excite with an A* spatial separation loss to resolve residual cross-token interference. For evaluation, we construct multi-audio compositional benchmarks from VGGSound (VGG2, VGG3, and VGGN) and extend six standard audio-image metrics to the multi-source setting. Across five benchmarks and four strong baselines, our method achieves strong results on the metrics most directly tied to compositional faithfulness, with AIC improvements of up to 2.25x over the strongest baseline and FID reduced by nearly 2x on two-source generation. We propose geometric displacement as a diagnostic framework for cross-modal generation systems that project learned embeddings into a pretrained contrastive space.","authors":["Anurag Singh","Prajwal Singh","Shanmuganathan Raman"],"published":"2026-11-18T13:38:35Z","updated":"2026-11-18T13:38:35Z","abstract_url":"https://arxiv.org/abs/2611.24410v1","html_url":"https://arxiv.org/html/2611.24410v1","pdf_url":"https://arxiv.org/pdf/2611.24410v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24408v1","title":"StrideWorld: Benchmarking Scene Rigidity and Action Consistency in Interactive Video World Model","abstract":"Interactive video world models turn user commands into the exploration of a generated scene, which requires the scene to keep its 3D structure as the camera moves and each action to keep a stable effect. Existing benchmarks mostly evaluate these properties against references fitted to the video under test, either a scene reconstructed from its own frames or a camera trajectory aligned to the command path with a free scale. Such references can absorb gradual scene deformation and changes in pace and route length, so these errors can pass undetected. We therefore introduce StrideWorld, a benchmark whose references are fixed before the motion they judge. It evaluates scene rigidity against the ground-truth geometry of the start view, and action consistency against the stride of each action, the camera motion of one command. The stride is measured on the model's first steps and then used to test the steps that follow, so each model is judged only against its own steps. Its measurements are validated on rendered videos with known camera motion, and its scores agree with human judgments. Across \\nvideos{} videos generated by \\nmodels{} open models from $140$ start views, all models but one deform their scenes as the camera moves, with offsets up to $7.3$ times those of a rigid rendering along the same camera path. Most models keep a steady pace when a single action is held. Along composed routes, several models often stall, and most completed routes end away from the positions predicted by each model's own strides. Only the two models that scale commands by the estimated scene depth bring most routes close to these positions. Fine-tuning two models on a few rendered clips removes most of their mid-route stalls. Code, data, and a leaderboard are publicly available at https://github.com/chuangwang123/strideworld.","authors":["Chuang Wang","Rui Nie","Jie Song","Junyuan Gao","Jiahe Song","Haitao Zhou","Boyu Zhu","Xing Li","Jiang Wu","Conghui He","Qian Yu","Weijia Li"],"published":"2026-11-18T13:37:51Z","updated":"2026-11-18T13:37:51Z","abstract_url":"https://arxiv.org/abs/2611.24408v1","html_url":"https://arxiv.org/html/2611.24408v1","pdf_url":"https://arxiv.org/pdf/2611.24408v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24404v1","title":"RAPID: Reconstruction Accelerated by Polarization-Informed Depth for 2D Gaussian Splatting","abstract":"Efficient and accurate 3D surface reconstruction from multi-view images remains a fundamental challenge in Gaussian splatting. Many existing methods rely on sparse geometric initialization and iterative densification, resulting in substantial optimization overhead and difficulties in balancing rendering quality and geometric accuracy, particularly in reflective and weakly textured regions. To address these limitations, we propose RAPID, a geometry-first framework that uses multiview polarization cues to recover dense surface priors. We integrate surface normals into depth maps using sparse geometric anchors. These depth maps are then fused across views. Curvature-adaptive sampling and oriented Gaussian initialization then support efficient optimization. Experiments on the PISR dataset demonstrate an approximately \\(5\\times\\) speedup over PhyGaP, which is a state-of-the-art Gaussian-based reconstruction method. RAPID reduces the average optimization time from approximately 21 minutes (PhyGaP) to 4 minutes while maintaining competitive novel-view synthesis quality and mesh reconstruction accuracy. These results demonstrate the effectiveness of RAPID in accelerating Gaussian optimization from polarimetric multi-view inputs.","authors":["Daisong Ouyang","Linlin Xia","Liangkun Yan","Song Gu","Shedong Zhao","Xin Dai","Yi Zheng"],"published":"2026-11-18T13:35:43Z","updated":"2026-11-18T13:35:43Z","abstract_url":"https://arxiv.org/abs/2611.24404v1","html_url":"https://arxiv.org/html/2611.24404v1","pdf_url":"https://arxiv.org/pdf/2611.24404v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24380v1","title":"Where Should a Diffusion Transformer Meet Its Teacher?","abstract":"Representation Alignment (REPA) significantly accelerates Diffusion Transformer training by guiding intermediate student features with a pretrained visual teacher, yet existing methods typically attach supervision to a single fixed layer. As student representations evolve, however, we find that the most effective layer for alignment varies across training stages. To track this evolving layer suitability online without costly search, we measure gradient compatibility between the flow-matching and alignment objectives, and propose AdaREPA, an online routing framework that adaptively selects the supervision layer as training progresses. AdaREPA uses a softmax distribution over smoothed layer compatibility scores to sample a layer for alignment at each training step. This probabilistic routing adapts teacher supervision to the student's changing learning needs, with minimal training overhead and no additional inference cost. On ImageNet-256, AdaREPA accelerates convergence and improves generation quality across model sizes, while revealing how the most suitable layers for supervision shift over training.","authors":["Zhuoqi Hu","Shiwei Li","Haozhao Wang","Xiandi Luo","Yihao Ouyang","Wenting Shen","Ang Wang","Jiamang Wang","Minyi Guo","Ruixuan Li"],"published":"2026-11-18T13:09:28Z","updated":"2026-11-18T13:09:28Z","abstract_url":"https://arxiv.org/abs/2611.24380v1","html_url":"https://arxiv.org/html/2611.24380v1","pdf_url":"https://arxiv.org/pdf/2611.24380v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24373v1","title":"CanopyKV: Remember beyond the Crop for Fast Active Visual Reasoning","abstract":"Active visual reasoning enables multimodal models to answer challenging visual questions by gathering fine-grained evidence through iterative image inspection and tool use. However, accumulating crops and reasoning tokens expands the key-value (KV) cache, making compression important for reducing memory and inference costs. Existing KV compression methods typically select historical tokens based on attention, recency, or redundancy. These criteria do not explicitly distinguish locally replaced evidence from complementary information needed for future exploration: each crop refreshes a local region, while earlier views may still support subsequent decisions. Discarding such evidence can impair accuracy or require additional search, while scoring and cache reorganization can offset the computational savings from compression. We introduce CanopyKV, a training-free KV compression framework that uses parent-child crop relationships to retain complementary evidence, keeps retained history stable, and protects the state needed for ongoing reasoning. Tool metadata provides retention signals without additional attention scoring, while compact KV storage reduces subsequent attention costs. Across VisualProbe, V*, HR-Bench, and MME-Lite, CanopyKV achieves state-of-the-art answer accuracy and end-to-end efficiency among the evaluated KV compression methods. On MME-Lite, it retains approximately one-quarter of Dense's total KV while improving accuracy by 10.5 percentage points and accelerating complete reasoning by $1.64\\times$.","authors":["Lei Yang","Dayan Wu","Yiliang Zhu","Xinze Liu","Hengjie Zhu","Zihao Zhang","Ding Wang","Peng Fu","Zheng Lin"],"published":"2026-11-18T13:05:16Z","updated":"2026-11-18T13:05:16Z","abstract_url":"https://arxiv.org/abs/2611.24373v1","html_url":"https://arxiv.org/html/2611.24373v1","pdf_url":"https://arxiv.org/pdf/2611.24373v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24371v1","title":"One Affinity, Two Axes: Bidirectional Slot Attention for Iterative Aggregation across the Structure--Detail Spectrum in Visual Retrieval","abstract":"Aggregating dense patch tokens into compact and discriminative global descriptors is central to visual retrieval. Although foundation models provide rich local features, existing aggregation heads still rely on single-pass mappings and lack an explicit mechanism to coordinate structural and fine-grained cues. Therefore, we propose Bidirectional Slot Attention (BiSA), which reformulates aggregation as an iterative coupled system. Cross-Axis Consensus (CAC) progressively refines learnable slots by interpreting a single shared token--slot affinity along two complementary axes. Along the competition axis, slots vie for each token under a temperature shared across all of them, determining token ownership and inducing a non-redundant scene decomposition. Along the selection axis, a slot-specific temperature governs the breadth of each slot's response, spanning a spectrum from broad layouts to sparse fine-grained details. Their consensus couples non-redundant decomposition with multi-granular slot specialization. Furthermore, the two axes expose intrinsic token-reliability cues at no extra cost: a token's claim strength under competition and its salience under selection. Progressive Token Filtering (PTF) converts these cues into a retention probability that down-weights unreliable tokens before the next CAC iteration, without any segmentation branch or external prior, forming a self-reinforcing loop of competitive decomposition, selective focusing, and feedback purification. Across all three retrieval tasks, BiSA leads on five of six place recognition benchmarks (+4.2 R@1 on Baidu Mall), tops all 16 metrics of drone--satellite geo-localization (+8.4 R@1 at 150 m), and improves instance-level retrieval on ROxford-Hard by 4.5 mAP points. Notably, the selection axis adds only 20 learnable scalars, yet improves average R@1 by 2.8 points.","authors":["Zihang Wang","Wenkai Zhu","Lingdong Kong","Teng Yan","Alan Liang","Shuyuan Li","Xieyuanli Chen","Dong Kong","Guanyu Zong"],"published":"2026-11-18T13:04:10Z","updated":"2026-11-18T13:04:10Z","abstract_url":"https://arxiv.org/abs/2611.24371v1","html_url":"https://arxiv.org/html/2611.24371v1","pdf_url":"https://arxiv.org/pdf/2611.24371v1.pdf","matched_keywords":["retrieval","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24366v1","title":"SCOUT: Risk-Guided Foundation-Model Escalation for Robust Tissue Detection in Whole-Slide Images","abstract":"Reliable tissue detection is essential for whole-slide image analysis, yet high average segmentation accuracy can conceal failures involving pale tissue, small fragments, and heterogeneous staining. Pathology foundation models offer transferable representations, but exhaustive inference is computationally demanding and may introduce false-positive tissue predictions. We propose SCOUT (Selective Correction of Uncertain Tissue), a risk-guided cascade that selectively refines an initial thumbnail-based tissue mask. A lightweight audit network estimates the spatial distribution of segmentation errors and prioritizes candidate regions for processing by a frozen pathology foundation model. An asymmetric consensus rule integrates the resulting predictions with the initial mask to recover missed tissue while limiting false positives. A calibrated slide-level review score additionally controls the marginal rate of unflagged case-group failures under the calibration assumptions. Evaluation on a public multi-source, multi-stain benchmark shows that SCOUT reduces the proportion of case groups requiring mask correction from 38.1% for the best released detector to 18.6%, with particularly pronounced improvements in immunohistochemistry. Source-held-out experiments demonstrate better generalization than a segmentation network trained on the same annotations, while selective inference achieves an observed failure rate no higher than processing all candidate regions. Downstream, lymph-node classification with SCOUT masks is non-inferior to that obtained with two of the three released detectors evaluated. A variant built on an openly licensed foundation model is publicly released as an installable Python package with trained weights. These results support risk-guided foundation-model inference as an effective approach to tissue detection across heterogeneous histopathology data.","authors":["Cristian Tommasino","Antonio M. Rinaldi"],"published":"2026-11-18T13:00:38Z","updated":"2026-11-18T13:00:38Z","abstract_url":"https://arxiv.org/abs/2611.24366v1","html_url":"https://arxiv.org/html/2611.24366v1","pdf_url":"https://arxiv.org/pdf/2611.24366v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24363v1","title":"Transferable Named Sparse Features for Morphology-based Gleason Grading","abstract":"Deep learning systems grade prostate biopsies at the level of pathologists, but most report a grade without the glandular architecture that justifies it. This work presents a grading system built on a sparse code over the tokens of a pathology foundation model. A sparse autoencoder pretrained on biopsies is aligned with multi-reader annotations, so that 69 of its 2048 features are named after Gleason morphologies such as cribriform glands, cords, and comedonecrosis. The same code feeds a grading network, which reads all features to predict Gleason patterns and the Grade Group, while morphology maps read directly from the named features. We evaluate the system on five public datasets that include needle biopsies, tissue-microarray cores, multi-reader annotations, and three scanners. The morphology maps remain stable across alignment runs and, without retraining, detect cribriform glands in external biopsies (area under the receiver operating characteristic curve, AUROC, 0.849) and pattern 5 in unseen cores when evaluated by up to six pathologists (AUROC 0.846 to 0.919). In an independent biopsy cohort, Grade Group agreement with three pathologists on Leica scans is close to their agreement with each other. Removing the named features reduces the corresponding Gleason pattern predictions by 49% to 98%, with effects larger than those from 20 activity-matched random feature removals. These results show that a shared sparse representation can support competitive Gleason grading while providing named morphological evidence that transfers across datasets and whose contribution to grading can be measured directly.","authors":["Argyrios Zafeiriou","Athanasios Kallipolitis","Ilias Maglogiannis"],"published":"2026-11-18T12:57:35Z","updated":"2026-11-18T12:57:35Z","abstract_url":"https://arxiv.org/abs/2611.24363v1","html_url":"https://arxiv.org/html/2611.24363v1","pdf_url":"https://arxiv.org/pdf/2611.24363v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24352v1","title":"OCTR2A: Real-Time RGB-to-BEV Trajectory Projection and Forecasting at Urban Intersections","abstract":"Trajectory forecasting at urban intersections is often studied assuming that reliable bird's-eye-view (BEV) motion histories are available, which in practice requires costly resources such as LiDAR, aerial views, HD maps, or calibrated infrastructure. We address this upstream perception-to-forecasting problem by reconstructing and predicting agents' BEV trajectories only from paired opposite-corner RGB cameras mounted on existing urban infrastructure at variable heights at inference time. We introduce the Opposite-Corner Trajectory Reconstruction and Anticipation Architecture (OCTR2A), a modular pipeline integrating per-view detection with class refinement, geometric cross-camera matching, transformer-based BEV projection, and egocentric GRU forecasting, trained in cascade and mainly supervised with a soft multi-scale spatial-overlap loss. Since no public benchmark provides this sensing configuration, we introduce R3ST++, a Blender-based synthetic benchmark built from SIND trajectories that provides synchronized opposite-corner views, cross-view correspondences, and BEV ground truth, while also serving as a deployment-support simulator for site-specific fine-tuning. Experiments on these datasets show that, with 12 observed and 12 predicted frames at 10\\,Hz, OCTR2A achieves projection~-~forecasting ADE/FDE of 0.144/0.140~-~0.154/0.241~meters in real time on a single consumer GPU. Evaluated on ground-truth BEV histories, the forecasting module improves over the strongest state-of-the-art methods on SIND by 66.7\\%/41.7\\% ADE/FDE. Transfer experiments on TUMTraf-V2X show that R3ST++ pretraining supports adaptation to real-world roadside domains with different sensing configurations.","authors":["Emanuele Iacobelli","Simone Teglia","Francesco Pro","Claudia Melis Tonti","Irene Amerini"],"published":"2026-11-18T12:47:15Z","updated":"2026-11-18T12:47:15Z","abstract_url":"https://arxiv.org/abs/2611.24352v1","html_url":"https://arxiv.org/html/2611.24352v1","pdf_url":"https://arxiv.org/pdf/2611.24352v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24296v1","title":"AnchorUp: Anchoring Feature Upsampling on a Classical Interpolation","abstract":"Vision foundation models produce semantically strong features on a coarse patch grid, and dense prediction needs them at pixel resolution. Existing learned upsamplers close that gap by regressing the high-resolution feature map from the low-resolution one, typically through cross-attention driven by the input image. We observe that most of what they regress needs no learning: plain bilinear interpolation already reproduces the smooth regions of the target, and recent benchmarks even report bilinear and bicubic on par with several learned upsamplers. The rest is mostly edges and fine details, which suggests that these learned upsamplers spend much of their capacity re-computing the smooth content that classical interpolation provides. We therefore introduce AnchorUp, which stops predicting the high-resolution feature map and predicts only its correction from the interpolation. It keeps a parameter-free classical upsampler as an anchor, obtains a second prediction from a small guidance network, and blends the two through a single learnable scalar gate. Because the anchor supplies the smooth content, the guidance network only has to correct what remains. An analysis of the learned correction confirms that it concentrates on edges and fine details, and so the network can be small: AnchorUp uses 167,425 parameters, a quarter of the budget of the strongest baseline, NAF, and runs at 64% of its latency. Trained once on DINOv3 with only the first of NAF's two training stages, and evaluated on that backbone plus six held-out ones, it is already on par with NAF trained through both stages on Pascal VOC and Cityscapes. Our method surpasses it on DAVIS-2017 video object segmentation; the gain holds on every backbone and is larger in contour accuracy F. Code is available at https://github.com/KotaroHorikawa/AnchorUp.","authors":["Kotaro Horikawa","Keisuke Toida","Junya Komori","Kazuhiro Hotta"],"published":"2026-11-18T12:08:07Z","updated":"2026-11-18T12:08:07Z","abstract_url":"https://arxiv.org/abs/2611.24296v1","html_url":"https://arxiv.org/html/2611.24296v1","pdf_url":"https://arxiv.org/pdf/2611.24296v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24284v1","title":"CROMPT: Adapting CLIP via Cross-Modal Prompting for Robust Zero-Shot Generalization under Adverse Weather","abstract":"Domain adaptation for semantic segmentation is challenging when target-domain images are unavailable during training. Zero-shot domain adaptation addresses this by adapting models using only textual descriptions of the target domain. However, existing prompt-learning methods are not well suited for ResNet-based CLIP vision backbones or pixel-level cross-modal feature alignment. We propose CROMPT, a prompt-learning framework for zero-shot domain adaptation in semantic segmentation. CROMPT introduces Cross-Modal Feature Augmentation (CROMA), combining Random Visual Prompting with Hybrid Textual Prompting (HTP) to jointly adapt visual and textual representations. We further propose CROMA-VL, which leverages vision-language models to generate domain-conditioned prompts, and a progressive easy-to-hard adaptation strategy for improved domain invariance. Experiments on two benchmark datasets demonstrate consistent improvements over strong baselines and state-of-the-art methods, achieving 1.63-2.63% mIoU gains while maintaining inference-time complexity. These results establish CROMPT as an effective and efficient framework for zero-shot multi-domain semantic segmentation. OpenReview: https://openreview.net/forum?id=FxqFsIL685","authors":["Aniruddh Sikdar","Arya Kishor","Snehashis Dhibar","Suresh Sundaram"],"published":"2026-11-18T11:59:24Z","updated":"2026-11-18T11:59:24Z","abstract_url":"https://arxiv.org/abs/2611.24284v1","html_url":"https://arxiv.org/html/2611.24284v1","pdf_url":"https://arxiv.org/pdf/2611.24284v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24277v1","title":"Semantic Guidance for Joint Infrared-Visible Video Fusion and Frame Interpolation","abstract":"Infrared and visible video fusion at high frame rates requires recovering missing observations when camera rates differ or fall below the desired output rate. Cascading interpolation and fusion can accumulate errors and cause brightness fluctuations. Motion and occlusion further complicate content selection, particularly when missing visible frames also remove direct semantic guidance. We propose SAFI, which uses semantics at the target time to guide joint interpolation and fusion. When the visible frame rate exceeds the infrared rate, available visible frames provide semantic context directly. At times without visible observations, motion guides local matching, and propagation recovers semantics from neighboring frames. Semantic context complements aligned image features at the target time, while matching confidence helps select reliable infrared and visible information. Reconstruction and fusion share source selection within each scale, allowing supervision on missing frames to guide fusion. To preserve visible appearance and reduce flicker, we bound thermal enhancement and penalize brightness inconsistencies across frames while accounting for changes in thermal contrast. Experiments on three datasets show improved visual quality with less computation than cascaded baselines and consistent temporal gains when input rates differ. SAFI maintains strong downstream tracking performance despite missing frames. The code is available at https://github.com/XylonXu01/SAFI.","authors":["Yushen Xu","Xiaosong Li","Huaming Wu","Dongwei Ren"],"published":"2026-11-18T11:54:45Z","updated":"2026-11-18T11:54:45Z","abstract_url":"https://arxiv.org/abs/2611.24277v1","html_url":"https://arxiv.org/html/2611.24277v1","pdf_url":"https://arxiv.org/pdf/2611.24277v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24267v1","title":"Look Closer, Look Back, or Wait for Agentic Streaming Video Understanding","abstract":"Streaming video models must answer questions about a live video under strict memory and latency limits. Feeding only the latest few frames keeps present perception sharp, whereas adding past frames dilutes attention on the current scene and triggers hallucinations. Recent cascade methods retrieve past frames when uncertain, but they still fail when current frames are blurry or when decisive future clues have not appeared yet. We introduce ActiveForager, a streaming video agent that maintains a clean short working window and gathers extra evidence only on demand. For each query, the agent either answers directly, zooms into high-resolution recent frames, recalls past events from memory, or waits for upcoming frames. When recalling history, a shared-weight sub-agent verifies candidate clips in isolation and returns a compact evidence summary. A stream-decoupled attention mask then keeps historical evidence from interfering with present visual tokens. We train this policy using counterfactual information gain, which rewards a tool call only when the gathered evidence makes the true answer more likely and prevents tool collapse across all actions. Across Qwen2.5-VL-7B and Qwen3-VL-8B on OVO-Bench, ActiveForager improves real-time perception, historical recall, and proactive response at once, lifting overall accuracy on Qwen3-VL-8B from 47.6% to 65.9%. It also doubles zero-shot accuracy on the multi-hop Video-Holmes benchmark while adding minimal visual tokens per query.","authors":["Pengyu Li","Zhitao Gao","Lingling Zhang","Wenxuan Huang","YiCheng Xiao","Chen Zheng","Jun Liu"],"published":"2026-11-18T11:48:00Z","updated":"2026-11-18T11:48:00Z","abstract_url":"https://arxiv.org/abs/2611.24267v1","html_url":"https://arxiv.org/html/2611.24267v1","pdf_url":"https://arxiv.org/pdf/2611.24267v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24259v1","title":"Do Thinking VLMs Need to Keep Looking at Long Videos? Write It Down, Then Look Away","abstract":"Vision-language models (VLMs) reason about long videos over hundreds to thousands of tokens. Every decoding step re-reads the key-value (KV) cache of the entire video. Must the model keep looking while it reasons? In LookAway, the model first writes timestamped notes on what the question needs and then puts the video away. Once the notes close, the inference engine hides the video's KV cache for the rest of the response. Across both hybrid and pure-attention VLMs, dependence on the video is concentrated early in the response. On Qwen3.6-27B, writing notes preserves accuracy better than free reasoning at the same withdrawal step. Replacing them with another video's notes harms accuracy, whereas keeping the video visible alongside the model's own notes adds no significant benefit. Without additional training, LookAway nearly matches full-video thinking accuracy at 0.12-0.13 times its modeled decode cost. To shorten this initial look, we fine-tune the model on its own correct LookAway responses. Reinforcement learning then rewards correct answers while penalizing KV reads. The trained model puts the video away after a median of 66-68 tokens. Across three held-out benchmarks, it writes more tokens than an identically trained full-video model yet reads only 27-35% as many KV positions at matched accuracy.","authors":["Pengyu Li","Zhitao Gao","Lingling Zhang","Heng Wang","Chengqian Ma","WenHao Wang","Wenxuan Huang","Chen Zheng","Jun Liu"],"published":"2026-11-18T11:42:17Z","updated":"2026-11-18T11:42:17Z","abstract_url":"https://arxiv.org/abs/2611.24259v1","html_url":"https://arxiv.org/html/2611.24259v1","pdf_url":"https://arxiv.org/pdf/2611.24259v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24256v1","title":"Spark-H3: Adaptive Block Sparse Attention for Video Diffusion Models","abstract":"Long video sequences make attention a substantial cost in video diffusion models. Block sparse attention (BSA) reduces this cost by computing selected blocks exactly while compressing the remaining blocks. However, fixed token grouping can place tokens with dissimilar attention preferences in the same group, while uniform key averaging can underestimate the attention mass of compressed blocks. We introduce Spark-Attn, a training-free BSA method comprising Spark-Reblock and Spark-Reweight. Spark-Reblock recursively groups tokens by attention preference while preserving regular block shapes for efficient GPU execution. Spark-Reweight uses the global mean query as an anchor to construct attention-weighted key-value representations and logit biases for the compressed blocks, calibrating their attention mass. We instantiate Spark-Attn in MiniMax-H3 as Spark-H3. At 10% exact-block density, Spark-H3 delivers a 2.49$\\times$ DiT speedup and reaches 24.81 dB PSNR against the corresponding dense outputs on MiniMax-H3 (20 denoising steps, 345 frames, 1344$\\times$768). Increasing the density to 20% further improves PSNR to 26.76 dB while still achieving a 2.26$\\times$ DiT speedup. These results demonstrate that Spark-H3 achieves a state-of-the-art quality-efficiency trade-off for training-free BSA on video diffusion models.","authors":["Zecheng Tang","Jiaye Fu","Youtian Lin","Xinyao Rao","Liuxuan Sun","Jian Zhang","Yao Yao","Wei Li"],"published":"2026-11-18T11:32:53Z","updated":"2026-11-18T11:32:53Z","abstract_url":"https://arxiv.org/abs/2611.24256v1","html_url":"https://arxiv.org/html/2611.24256v1","pdf_url":"https://arxiv.org/pdf/2611.24256v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24253v1","title":"One Shot, Any View: High-Fidelity Video Reshooting with Geometry Guidance and Visual References","abstract":"Filming a scene from an additional angle after production usually requires a costly reshoot. We present One Shot Any View, a system that takes a recorded clip and generates a reshot video of the same performance along a user-specified camera trajectory. As in recent geometry-grounded methods, the system conditions generation on the source video and an explicit 3D prior, namely a point video rendered along the requested trajectory from a feed-forward reconstruction of the source video. We target human-centric cinematic videos, which are often shot with long lenses, shallow depth of field, and low-key lighting, all of which degrade feed-forward reconstruction. Existing geometry-grounded methods tend to inherit the degraded point video, and their output quality drops visibly. Two designs make such point videos usable. First, in addition to rendered videos of 3D assets, we train on real-world multi-camera videos, whose point videos are produced by the same reconstruction pipeline as at inference. This training-inference consistency enables the generator to take only the composition of people and scene elements from the point video, and their appearance from the source video. Second, a geometry-anchored RoPE offset keeps the generated video temporally synchronized with the source while largely preventing the output from copying the degraded appearance of the point video. Meanwhile, since the generator is a pretrained reference-to-video (R2V) model, the system also accepts optional character and scene reference images, which supply the appearance of regions that the source never shows. In both objective and human evaluations, One Shot Any View outperforms existing reshooting methods.","authors":["Kai Huang","Runze Xu","Hui Ren","Taiyi Wu","Xinyuan Li","Xun Gao","Quande Liu","Dong Tang","Tongtong Shen","Xuefeng Su","Alan Zhao"],"published":"2026-11-18T11:31:56Z","updated":"2026-11-18T11:31:56Z","abstract_url":"https://arxiv.org/abs/2611.24253v1","html_url":"https://arxiv.org/html/2611.24253v1","pdf_url":"https://arxiv.org/pdf/2611.24253v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24240v1","title":"ViLFlow: Parallel Vision-Language Generation with Continuous Latent Flows","abstract":"Vision-language generation has predominantly relied on autoregressive and discrete diffusion models. Autoregressive models generate tokens sequentially, while discrete diffusion models typically predict tokens independently within each denoising step. We propose ViLFlow (Vision-Language Flow), a continuous-flow vision-language model that combines joint modeling of output embeddings with parallel token decoding. ViLFlow adapts pretrained continuous language generation to visual question answering and image captioning through learned image guidance and prediction-aware token decoding. A visually adapted teacher provides image-guided predictions as additional denoising supervision. The denoiser learns to reproduce these predictions directly, retaining one image-conditioned prediction per generation step. We train the token decoder on denoiser predictions and paired reference text to improve the conversion of continuous outputs into words. The decoder can be adapted independently, improving answering and captioning without further denoiser training. For captioning, it also supplies text feedback during late denoising, allowing decoded words to inform subsequent refinement. ViLFlow outperforms autoregressive and masked-diffusion baselines by up to 8.46 percentage points on VQAv2 and 4.50 points on GQA without GQA training. On COCO Karpathy test, it improves CIDEr by 16.25 over masked diffusion and 17.81 over sampled autoregression.","authors":["Kevin Zhai","Bian Sun","Zhenyi Wang","Song Wang"],"published":"2026-11-18T11:19:11Z","updated":"2026-11-18T11:19:11Z","abstract_url":"https://arxiv.org/abs/2611.24240v1","html_url":"https://arxiv.org/html/2611.24240v1","pdf_url":"https://arxiv.org/pdf/2611.24240v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24233v1","title":"Psychometrics-Inspired Coreset Selection for Image Quality Assessment","abstract":"Collecting large-scale subjective annotations remains a critical bottleneck in training accurate image quality assessment (IQA) models. Coreset selection reduces this burden by selecting representative images before annotation. However, diversity in a visual feature space does not necessarily reflect diversity in perceptual quality, raising a fundamental question about which quality-related factors the representation should encode. We propose GRAM, a quality-aware representation learning framework inspired by the graded response model (GRM) from psychometrics. GRM describes how an individual's latent ability determines the probabilities of reaching successive assessment grades, with response sensitivity and grade thresholds governing this relationship. In this paper, we find that this principle naturally aligns with perceptual quality assessment, where the impact of image degradation depends on image content and distortion characteristics. Building on this connection, GRAM models quality judgments through three complementary factors: latent quality, content-dependent response sensitivity, and distortion-dependent grade thresholds. These factors jointly determine the probabilities of attaining different quality grades and the resulting expected quality score. The learned parameters provide a structured quality-aware representation that complements general visual features for coreset selection. Experiments on nine datasets demonstrate improvements across different selection strategies, downstream IQA models, and annotation budgets. The code will be made publicly available.","authors":["Susu Jiang","Xuelin Shen","Baoliang Chen"],"published":"2026-11-18T11:08:48Z","updated":"2026-11-18T11:08:48Z","abstract_url":"https://arxiv.org/abs/2611.24233v1","html_url":"https://arxiv.org/html/2611.24233v1","pdf_url":"https://arxiv.org/pdf/2611.24233v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24223v1","title":"Training Denoising Models of Any Architecture Without Stored Images","abstract":"Can a pretrained denoising model replace the dataset used to train it? We investigate this question through teacher-supervised training, showing for the first time that continuous-time diffusion and flow models of any architecture and size can be trained from random initialization without stored images. Our students regress the teacher's velocity on a rolling pool of noisy samples, advanced along trajectories of random step counts to obtain independent, dense and approximately continuous noise levels. This saves considerable storage for large datasets and applies even when the data are unreleased or private. Our experiments include 12 teachers of 6 families and 6 datasets. Our method outperforms standard training of the same network on CIFAR-10 for students 4x smaller than the teacher, comes within 0.75 to 1.92 FID of it at the teacher's size and surpasses training on teacher-generated images and step reduction methods without teacher-based initialization. Our code is available at https://github.com/mever-team/ddm.","authors":["Christos Koutlis","Ioannis Kompatsiaris","Symeon Papadopoulos"],"published":"2026-11-18T10:58:54Z","updated":"2026-11-18T10:58:54Z","abstract_url":"https://arxiv.org/abs/2611.24223v1","html_url":"https://arxiv.org/html/2611.24223v1","pdf_url":"https://arxiv.org/pdf/2611.24223v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24222v1","title":"Target-Consistent Action Guidance via Semi-Unbalanced Optimal Transport for Drifting World Models","abstract":"Action-conditioned world models let robots imagine the outcomes of their actions for planning and offline policy evaluation, but these uses need many rollouts, which multi-step diffusion makes expensive. Drifting models move the iteration from inference to training and generate samples in one network pass. DriftWorld brought this paradigm to action-conditioned world models; to strengthen action following, it repels predictions from the current frame, a construction borrowed from classifier-free guidance. We show that this accentuation has a target bias: the push persists even when a prediction matches the recorded future, in kernel, balanced, and unbalanced Wasserstein drifting fields alike. We introduce Mass-Share Accentuation (MSA) to remove this bias. MSA treats the current frame as a counterfactual destination competing with the recorded future in a semi-relaxed optimal transport problem; subtracting the closed-form share of the correct future makes the guidance vanish at the target, and the remainder is shared by all predictions. We prove that the recorded future is the unique fixed point along the motion direction for collapsed predictions, and that the guidance fades with prediction error. On Push-T, Robomimic, and BridgeV2, where trained models under-react rather than overshoot, MSA improves action ranking, response slope, and moving-region error over latent-space baselines at no inference cost, though these benchmarks do not isolate bias removal as the cause.","authors":["Md Abtahi Majeed Chowdhury","Md Rifat Ur Rahman","Md Sakib Hossain Shovon","Jaesik Choi","Minhyuk Sung"],"published":"2026-11-18T10:58:48Z","updated":"2026-11-18T10:58:48Z","abstract_url":"https://arxiv.org/abs/2611.24222v1","html_url":"https://arxiv.org/html/2611.24222v1","pdf_url":"https://arxiv.org/pdf/2611.24222v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24200v1","title":"SpiderMark: Hybrid Watermarking for Generative AI via Algorithmic Injection and Learning-Based Verification","abstract":"The proliferation of diffusion-based generative models has intensified the need for reliable methods to trace and verify the provenance of AI-generated images. Existing watermarking approaches for diffusion models typically rely on isotropic frequency patterns and handcrafted detection metrics, which are prone to directional vulnerability and threshold instability across diverse image transformations. We propose SpiderMark, a hybrid watermarking framework that combines algorithmic frequency-domain injection with learning-based probabilistic verification, requiring no modifications to pretrained diffusion model weights. SpiderMark embeds a structured spider-web pattern, comprising radial spokes and concentric polygonal rings, into the Fourier representation of the initial latent noise, and trains a lightweight ResNet-18 verifier augmented with auxiliary similarity cues (PSNR and L1) to produce a continuous watermark confidence score for watermark detection. Across nine evaluation conditions, SpiderMark achieves the highest fixed-threshold Accuracy in eight, while retaining strong detection on unseen COCO prompts without verifier retraining. CLIP similarity and FID measurements show that these detection gains are accompanied by small measured differences in prompt alignment and distributional image quality. SpiderMark establishes that structured watermark geometry and learned probabilistic verification can be unified into a single, practical framework, bridging the gap between imperceptibility, robustness, and real-world verifiability for generative AI content attribution.","authors":["Chihcheng Hsieh","Yang Song","Flora Salim","Martin Bell","Jacinto C. Nascimento","Catarina Moreira"],"published":"2026-11-18T10:36:51Z","updated":"2026-11-18T10:36:51Z","abstract_url":"https://arxiv.org/abs/2611.24200v1","html_url":"https://arxiv.org/html/2611.24200v1","pdf_url":"https://arxiv.org/pdf/2611.24200v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24197v1","title":"From Neural Tokens to Language: Dual-View EEG Semantic Bridging for Brain-to-Text Generation","abstract":"Visually evoked EEG-to-text generation aims to produce natural-language descriptions from neural responses elicited by visual stimuli. Existing approaches typically compress EEG signals into a single global representation and directly project it into the hidden space of a large language model (LLM), which may limit the preservation of complementary visual semantics under noisy and subject-dependent EEG signals. We propose a dual-view semantic token bridging framework that exploits raw images and sketch images as complementary visual supervision to learn raw-oriented and sketch-oriented EEG semantic token streams. To interface these structured neural representations with an LLM, we introduce a branch-specific semantic query bridge that aggregates each token stream into compact semantic slots and converts them into LLM-compatible soft prompts. A progressive adaptation strategy further transitions the learned visual-semantic interface from image-supported training to image-free EEG-conditioned generation. Experiments demonstrate strong subject-wise EEG classification performance and competitive EEG-to-text generation across multiple LLM backbones. Ablation, branch-level representation, and EEG-label disentanglement analyses further show that the two EEG streams learn complementary view-oriented representations and that EEG-derived prompts provide sample-specific information beyond category labels.","authors":["YaoYang Liu","Jun Dai","ZhuoShi Tang","Weijun Sun","Xiaozhao Fang","Jie Wen"],"published":"2026-11-18T10:32:57Z","updated":"2026-11-18T10:32:57Z","abstract_url":"https://arxiv.org/abs/2611.24197v1","html_url":"https://arxiv.org/html/2611.24197v1","pdf_url":"https://arxiv.org/pdf/2611.24197v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24193v1","title":"WM^MLLM: Turning MLLMs into World Models","abstract":"Video world models keep the world in the context of a generator, so a revisit is synthesized again and earlier edits can drift or disappear. We present WM^MLLM, the first interactive world model built on multimodal large language models (MLLMs), for persistent, editable world generation from a single image. WM^MLLM keeps the world state outside every generator, as a panorama with a revision history, and lets the MLLMs write it: they turn each request into operations on this state, select where a local edit is written, and check every candidate before it becomes the next state. Image generators only propose views, and video only presents them. Users can walk to new places and return, edit objects through text or a box, place subjects, and change lighting, weather or season. By construction, a revisit at the same revision reproduces the earlier view exactly, a local edit leaves every panorama pixel outside its region unchanged, and each request starts from the result of the previous one. Against six world model baselines on MBench-A, WM^MLLM has the highest mean on all four environment-recovery metrics (Epipolar 91.5 versus 0.1 to 74.0) and completes the most camera round trips (85.3% versus at most 50.9%). It has the best value in all 15 CompBench columns against 15 baselines. On 112 local edits judged blind, selecting the region to write after generation raises completion from 34.8% to 83.0%. On 258 WBench and MBench-A items, all 46 revisits recover their earlier views, and all 97 local edits that pass the check leave panorama pixels outside their region unchanged.","authors":["Baiang Li","Enze Xie","Jincheng Yu","Jin Wang","Haozhe Liu","Yitong Li","Juanxi Tian","Felix Heide"],"published":"2026-11-18T10:29:16Z","updated":"2026-11-18T10:29:16Z","abstract_url":"https://arxiv.org/abs/2611.24193v1","html_url":"https://arxiv.org/html/2611.24193v1","pdf_url":"https://arxiv.org/pdf/2611.24193v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24192v1","title":"TrajWAM: Trajectory-Conditioned Future Learning for Vision-Language Driving","abstract":"World Action Models (WAMs) connect future scene prediction with action planning for autonomous driving. Each driving record pairs an executed ego trajectory with its observed future, providing a factual outcome for learning this connection. We present TrajWAM, a trajectory-conditioned WAM that improves vision-language driving through auxiliary bird's-eye-view (BEV) future learning. An ego-trajectory query conditions DINOv3-aligned BEV predictions from shared planner representations. Training combines factual reconstruction under the executed trajectory with one-sided feature separation under an unlabeled perturbed trajectory. Together, these objectives train the shared planner to generate driving waypoints. Native inference directly generates waypoints and bypasses the auxiliary future-prediction branch. On all 220 Bench2Drive routes, TrajWAM achieves 91.53 Driving Score and 75.45% Success Rate, exceeding a schedule-matched planning-only fine-tuning baseline by 5.31 Driving Score points and eight successful routes.","authors":["Xuerui Fang","Gulimila Kezierbieke","Chen Wangxing","Hui Li"],"published":"2026-11-18T10:28:56Z","updated":"2026-11-18T10:28:56Z","abstract_url":"https://arxiv.org/abs/2611.24192v1","html_url":"https://arxiv.org/html/2611.24192v1","pdf_url":"https://arxiv.org/pdf/2611.24192v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24184v1","title":"VideoACE: Benchmarking Agentic Video Understanding through High-Frame-Rate Actions","abstract":"Agentic video understanding requires models to actively interact with video environments to gather evidence and form judgments. Evaluating this capability therefore requires assessing whether models can translate opportunities for interaction into better understanding. We introduce VideoACE, a benchmark for assessing video understanding under conditions that support sustained interaction. We focus on high-frame-rate action videos, where rapid, subtle changes make targeted observation especially valuable. The benchmark comprises 1,000 multiple-choice questions spanning six categories of fine-grained action understanding, accompanied by temporal evidence annotations and user hints screened for answer leakage. Its evaluation environment combines video inspection tools with a user simulator, allowing models to adjust temporal coverage, sampling density, and spatial detail, and to revisit evidence and revise their judgments under simulated user feedback. We evaluate single-pass observation, autonomous tool use, and tool use combined with user feedback to examine how effectively models exploit these opportunities. Evaluation of five models reveals distinct patterns in how they acquire evidence and respond to opportunities for further interaction. These findings establish VideoACE as a testbed for examining agentic video understanding beyond performance under a fixed observation setting.","authors":["Luoyuan Zhang","Xuanyu Zheng","Yancheng Long","Haoyang Xu","Bin Wen","Tingting Gao"],"published":"2026-11-18T10:26:07Z","updated":"2026-11-18T10:26:07Z","abstract_url":"https://arxiv.org/abs/2611.24184v1","html_url":"https://arxiv.org/html/2611.24184v1","pdf_url":"https://arxiv.org/pdf/2611.24184v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24182v1","title":"ART: Bridging the Embodiment Gap in 3D Human-to-Robot Affordance Transfer","abstract":"3D affordance acts as a critical link between perception and action, providing priors for robotic manipulation. While existing approaches predominantly leverage human priors as direct references, they often overlook that affordance is not an object-intrinsic property but is inherently coupled with the agent's embodiment. Due to the structural and morphological disparities between human hands and robot end-effectors, directly applying human priors causes severe incompatibility for robotic execution. Motivated by this, we introduce a novel task setting, 3D Human-to-Robot Affordance Transfer, which addresses the affordance misalignment arising from distinct embodiment structures. To support this task, we construct the Human-Robot Paired Affordance Dataset (HPAD), the first large-scale 3D affordance benchmark in which every object is annotated with both human-prior and simulation-validated robot labels. HPAD covers 2,137 objects across 80 categories and 13 atomic action primitives, yielding over 27,000 object-action pairs. On top of HPAD, we propose the 3D Affordance tRansfer neTwork (ART). ART first filters geometric false positives in the human prior via a reliability gating stream, then reconstructs the prior into a robot-actionable distribution through hierarchical reconstruction and a graph-diffusion refinement that resolves the topological mismatch between human and robot affordances. Experiments on HPAD demonstrate the reliability of the proposed task and the superiority of ART. We further validate ART on a 6-DoF arm with a parallel-jaw gripper in a 2,400-execution benchmark across 12 objects and 4 action categories; ART attains the best success rate (86.5% over its 480 trials), confirming the practicality of the transfer paradigm. Project page: https://derek0907.github.io/ART/","authors":["Zichen Zhang","Wei Zhai","Xuji Zhang","Yang Cao","Yu Kang"],"published":"2026-11-18T10:22:42Z","updated":"2026-11-18T10:22:42Z","abstract_url":"https://arxiv.org/abs/2611.24182v1","html_url":"https://arxiv.org/html/2611.24182v1","pdf_url":"https://arxiv.org/pdf/2611.24182v1.pdf","matched_keywords":["3d","agent","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24171v1","title":"Efficient World-Model Planning via Physics-Guided Search Distillation","abstract":"World models support autonomous driving by evaluating candidate trajectories through predicted future scene evolution. However, accurate future prediction does not ensure road-compliant execution; when all candidates violate road boundaries, re-ranking cannot select a feasible trajectory. We propose Physics-Guided Search Distillation (PGSD), a single-view planning framework that combines future representations and execution feedback for verified beyond-pool repair through three components: (1) Execution-Aware Selection checks ego-vehicle road compliance under simulated execution and selects the highest-scoring feasible trajectory; (2) a Clearance-Aware Search Teacher generates beyond-pool corrections and selects demonstrations with larger minimum road-boundary clearance during execution to buffer imitation errors; and (3) a Future-Conditioned Repair Student predicts one correction from rewarder features and execution feedback for single-rollout verification. The pretrained planner and rewarder remain frozen; no future scenes are generated online. On NAVSIM v1, single-view PGSD achieves 90.97 PDMS, exceeding all compared prior single-view planners and retaining 73.2% of the search teacher's PDMS gain over execution-aware selection. On NAVSIM v2 navhard, it reaches 38.96 EPDMS, improving on WorldDrive by 11.24 points (40.5%). The student replaces up to ten search rollouts with a single verification rollout per repair trigger. HUGSIM Hard examples provide qualitative evidence of zero-shot transfer.","authors":["Hongyu Zhang","Xiaoshuai Hao","Heye Huang","Qingwen Meng","Wenjun Shi","Jianao Xu","Xin Hu","Xuanru Jin","Jingyi Zhang","Baicang Guo"],"published":"2026-11-18T10:14:22Z","updated":"2026-11-18T10:14:22Z","abstract_url":"https://arxiv.org/abs/2611.24171v1","html_url":"https://arxiv.org/html/2611.24171v1","pdf_url":"https://arxiv.org/pdf/2611.24171v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24170v1","title":"ViStep-RL: Stepwise Reinforcement Learning for Long-Horizon Visual Agents","abstract":"Long-horizon visual agents must do more than inspect images: they must turn observations into evidence that remains usable as a task unfolds. Existing active-perception methods teach agents where and how to look, while a final-answer reward gives little structure for deciding which observations satisfy dependent subgoals or should be retained for later use. We present ViStep-RL (Visual Stepwise Reinforcement Learning), which models execution as a dependency-linked graph of evidence-bearing subgoals. A verifier tracks which subgoals are supported by valid evidence, and changes in graph potential provide a net-progress learning signal; an active memory protocol preserves evidence across turns and links retrieval to downstream use. On ViInteract, ViStep-RL reaches 60.0% strict completion with Qwen2.5-VL-7B, compared with 10.0% for the base model and 46.5% after supervised fine-tuning. Controlled studies show that incremental task-state rewards outperform cumulative rewards by 3.2 points, while active evidence writing improves strict completion by 7.75 points over automatic writing. Under a common interaction framework, the task-trained ViStep-RL policy achieves 59.5% answer accuracy, 24.0 points above the strongest of six general-purpose reference models. Held-out episodes confirm the gain at both Qwen scales, and gains extend to three external visual reasoning benchmarks.","authors":["Junyang Chen","Yao Qin","Xiao Li","Ningchao Wang","Yiguo Qiao","Wenbin Li","Xin Geng"],"published":"2026-11-18T10:12:30Z","updated":"2026-11-18T10:12:30Z","abstract_url":"https://arxiv.org/abs/2611.24170v1","html_url":"https://arxiv.org/html/2611.24170v1","pdf_url":"https://arxiv.org/pdf/2611.24170v1.pdf","matched_keywords":["retrieval","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24164v1","title":"Gaussian Primitive Fusion for Any-Resolution Multimodal Images","abstract":"Multimodal image fusion integrates complementary observations from different modalities into a unified representation. Existing methods typically estimate modality contributions on a common discrete grid. When source modalities have different native resolutions, constructing such a grid generally involves resampling, which may introduce artifacts and affect subsequent fusion decisions. To address this problem, we propose Gaussian Primitive Fusion (GPF), which reformulates heterogeneous-resolution fusion in a shared continuous Gaussian space. Instead of first converting source images to a common resolution, GPF directly fits their native-resolution observations with shared Gaussian geometry and modality-specific content representations, and learns modality contributions within the resulting continuous representation. Once optimized, the fused representation is rendered at the finest native resolution without resampling the sources. With heterogeneous-resolution inputs, GPF produces clearer target contours and finer textures, with less blurring and blocking artifacts than resample-then-fuse pipelines. Quantitatively, it achieves the best results on multiple infrared-visible benchmarks against state-of-the-art fusion methods equipped with interpolation or super-resolution frontends.","authors":["Baoshuo Cai","Xinrui Jiang","Bing Cao"],"published":"2026-11-18T10:06:21Z","updated":"2026-11-18T10:06:21Z","abstract_url":"https://arxiv.org/abs/2611.24164v1","html_url":"https://arxiv.org/html/2611.24164v1","pdf_url":"https://arxiv.org/pdf/2611.24164v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24163v1","title":"Stabilizing Neural-to-Image Retrieval with Frequency-Domain Priors and Adaptive Supervision","abstract":"Visual neural decoding aims to infer perceived visual stimuli from brain activity, offering important insights into human visual cognition while enabling transformative applications in brain computer interfaces and artificial intelligence. Recent advances in pretrained vision-language models have provided a semantically rich representation space for this task. However, reliable alignment between EEG/MEG signals and visual embeddings remains challenging because neural responses are noisy, highly variable across trials, and subject dependent. To address this issue, we propose a unified neural-to-image retrieval framework that improves retrieval performance by aligning neural and image representations in a shared semantic space. The framework integrates dual-stream adaptation, frequency-domain calibration, and phase-guided temperature modulation to promote more robust cross-modal semantic alignment. Specifically, dual-stream adaptation models a low-dimensional shared subspace with correlation regularization to suppress redundant noise and enhance cross-modal consistency. Frequency-domain calibration conditionally modulates neural representations using amplitude and phase statistics. Phase-guided temperature modulation further adjusts the supervision strength in contrastive learning according to the stability of neural responses. Experiments on THINGS-EEG and THINGS-MEG under both intra-subject and inter-subject settings demonstrate that the proposed framework consistently outperforms strong baselines. These results suggest that robust neural-to-image retrieval under heterogeneous neural conditions benefits from a stable shared semantic space, frequency-informed representation calibration, and adaptive supervision. Code will be released at github.com/wanfkuabc/Geometry-Regularized-Brain-Embeddings.","authors":["YaoYang Liu","ZhuoShi Tang","Haopeng Lai","Weijun Sun","Xiaozhao Fang","Jie Wen"],"published":"2026-11-18T10:06:13Z","updated":"2026-11-18T10:06:13Z","abstract_url":"https://arxiv.org/abs/2611.24163v1","html_url":"https://arxiv.org/html/2611.24163v1","pdf_url":"https://arxiv.org/pdf/2611.24163v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24161v1","title":"AVTR: Adaptive Multimodal Reasoning with Visual Imagination","abstract":"Vision-Language Models increasingly rely on textual reasoning to solve advanced multimodal tasks. Despite its effectiveness, this paradigm faces two fundamental limitations. First, relying on textual reasoning alone can limit perceptual ability in vision-centric questions, where accurate answers depend on interpreting task-relevant visual evidence. Second, applying textual reasoning uniformly across inputs overlooks question-dependent variation in both reasoning modality and depth, often producing verbose and unnecessary traces when little logical inference is required. To this end, we propose Adaptive Visual-Textual Reasoning (AVTR), which introduces visual imagination as a complementary reasoning modality to textual thinking, enabling the model to revisit its visual observations and distill the salient evidence through generative visual reflection. Furthermore, we formulate reasoning-modality selection as a learned routing problem, allowing a single policy to adaptively harness the complementary strengths of visual reflection and textual reasoning in response to the perceptual and inferential demands of the input. Across 16 benchmarks, AVTR improves the average score by 4.5 points over Qwen3.5 baseline, while reducing inference latency by 33\\%. It also scales effectively into a smaller size backbone, outperforming the evaluated 2B-scale baselines.","authors":["Xiaoqian Shen","Yunyang Xiong","Changsheng Zhao","Saksham Suri","Chong Zhou","Zechun Liu","Zhipeng Cai","Zhuang Liu","Qi Qian","Wei Wen","Hongyu Xu","Hanxian Huang","Ernie Chang","Yanbei Chen","Vikas Chandra","Raghuraman Krishnamoorthi","Mohamed Elhoseiny","Lemeng Wu"],"published":"2026-11-18T10:05:18Z","updated":"2026-11-18T10:05:18Z","abstract_url":"https://arxiv.org/abs/2611.24161v1","html_url":"https://arxiv.org/html/2611.24161v1","pdf_url":"https://arxiv.org/pdf/2611.24161v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24154v1","title":"Game2Player: Scaling Gameplay Experience for Visual Agents through Environment-Player Co-Development","abstract":"Games are a rich testbed for visual agents, demanding perception, long-horizon planning, and precise control. However, collecting human gameplay is costly, and learning from gameplay videos requires inferring missing actions. Existing datasets also cover a limited range of games, often without explicit tasks or verifiable outcomes. To address these gaps, we introduce Game2Player, a framework that co-develops game environments and players to collect diverse and verifiable gameplay experience at scale. In the Game2Player loop, a Builder agent adapts existing web games, exposes their internal state, and defines tasks with state-based progress measures and success checks. A Coding Player and a VLM Player then attempt the tasks and report problems to the Builder for repair, so that play serves as both environment validation and training data collection. With Game2Player, we build 568 verified web games with 3,436 tasks, collect 15.7K trajectories (307 hours of gameplay), and hold out 50 games as the benchmark PlayerBench. To evaluate the collected experience as training data, we train VLM agents with progress-weighted SFT, assigning greater weight to steps that advance task progress. Game2Player-9B improves progress from 14.3% to 31.2% on PlayerBench and from 30.0% to 53.1% on the external GameWorld benchmark. More broadly, our work suggests a path for visual agents to scale their gameplay experience by building, verifying, and learning from existing game worlds.","authors":["Xirui Jiang","Yuxi Chen","Rui Yang","Feng Luo","Pengcheng Wang","Bingxuan Li","Zihao Zhao","Yushan Li","Han Wang","Manling Li","Yang Zhang","Shiyu Chang","Tong Zhang","Huan Zhang"],"published":"2026-11-18T09:58:53Z","updated":"2026-11-18T09:58:53Z","abstract_url":"https://arxiv.org/abs/2611.24154v1","html_url":"https://arxiv.org/html/2611.24154v1","pdf_url":"https://arxiv.org/pdf/2611.24154v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"},{"id":"2611.24152v1","title":"SEER: Semantic Evidence for Executable Region Propagation in Open-Vocabulary Semantic Segmentation","abstract":"Training-free open-vocabulary semantic segmentation (OVSS) has made strong progress by adapting CLIP-like representations to dense prediction, but its remaining errors are often local, structured, and tied to the active label space. A successful correction must be visually plausible, legal under the target vocabulary, and executable in the segmentation score field. We propose SEER, a training-free test-time repair layer for Semantic Evidence and Executable Region propagation. SEER casts post-prediction OVSS repair as evidence-conditioned label propagation. The OVSS score space proposes compact candidate labels, a frozen VLM verifies closed-set regional evidence, and an execution gate certifies whether the evidence is legally and semantically actionable. The accepted label is then propagated by an OVSS-side policy: coherent high-confidence regions allow broad propagation, while object- or boundary-risk cases use conservative score-grounded propagation. Across eight standard OVSS benchmarks, SEER reaches 58.0 average mIoU without updating OVSS weights. Matched-input controls isolate the repair mechanism, while resource measurements report the cost of the complete frozen system.","authors":["Junyang Chen","Xiao Li","Yiguo Qiao","Wenbin Li"],"published":"2026-11-18T09:56:02Z","updated":"2026-11-18T09:56:02Z","abstract_url":"https://arxiv.org/abs/2611.24152v1","html_url":"https://arxiv.org/html/2611.24152v1","pdf_url":"https://arxiv.org/pdf/2611.24152v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-19T08:18:20+00:00","last_seen_at":"2026-11-19T08:18:20+00:00"}],"tracked_paper_count":71,"storage_mode":"latest_overwrite"}};
